CREATE OR REPLACE FUNCTION "public"."apply_call_outcome_side_effects"("p_attempt_id" integer, "p_worker_id" integer, "p_campaign_id" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row RECORD;
  v_pending_id INTEGER;
  v_financial_id INTEGER;
  v_apply BOOLEAN;
  v_truthy TEXT[];
  v_val TEXT;
  v_ambition_campaign INTEGER;
  v_updated INTEGER;
BEGIN
  IF p_campaign_id IS NULL THEN
    RETURN;
  END IF;

  SELECT union_membership_type_id INTO v_pending_id
  FROM union_membership_types
  WHERE type_name = 'member_pending'
  LIMIT 1;

  SELECT union_membership_type_id INTO v_financial_id
  FROM union_membership_types
  WHERE type_name = 'financial_member'
  LIMIT 1;

  IF v_pending_id IS NULL OR v_financial_id IS NULL THEN
    RETURN;
  END IF;

  FOR v_row IN
    SELECT
      cao.outcome_id,
      cao.response_value,
      cod.side_effect,
      cod.side_effect_payload,
      cod.maps_to_ambition_id,
      cod.response_type
    FROM call_attempt_outcomes cao
    JOIN call_outcome_definitions cod ON cod.outcome_id = cao.outcome_id
    WHERE cao.attempt_id = p_attempt_id
      AND cod.side_effect = 'set_membership_pending'
  LOOP
    v_apply := false;
    IF v_row.response_type = 'checkbox' THEN
      v_apply := true;
    ELSIF v_row.response_type = 'select' THEN
      v_val := lower(trim(coalesce(v_row.response_value, '')));
      v_truthy := ARRAY['joined', 'yes', 'financial_member', 'member', 'member_pending', 'pending'];
      IF v_row.side_effect_payload IS NOT NULL
         AND jsonb_typeof(v_row.side_effect_payload->'select_truthy_values') = 'array' THEN
        SELECT array_agg(lower(t.v))
        INTO v_truthy
        FROM jsonb_array_elements_text(v_row.side_effect_payload->'select_truthy_values') AS t(v);
        IF v_truthy IS NULL THEN
          v_truthy := ARRAY['joined', 'yes', 'financial_member', 'member', 'member_pending', 'pending'];
        END IF;
      END IF;
      IF v_val = ANY (v_truthy) THEN
        v_apply := true;
      END IF;
    END IF;

    IF NOT v_apply THEN
      CONTINUE;
    END IF;

    UPDATE workers w
    SET
      union_membership_type_id = v_pending_id,
      join_date = COALESCE(w.join_date, CURRENT_DATE),
      updated_at = now()
    WHERE w.worker_id = p_worker_id
      AND w.union_membership_type_id IS DISTINCT FROM v_financial_id
      AND w.union_membership_type_id IS DISTINCT FROM v_pending_id;
    GET DIAGNOSTICS v_updated = ROW_COUNT;

    IF v_updated = 0 THEN
      CONTINUE;
    END IF;

    IF v_row.maps_to_ambition_id IS NULL THEN
      CONTINUE;
    END IF;

    SELECT csp.campaign_id INTO v_ambition_campaign
    FROM plan_ambitions pa
    JOIN campaign_stage_plans csp ON csp.plan_id = pa.plan_id
    WHERE pa.ambition_id = v_row.maps_to_ambition_id
    LIMIT 1;

    IF v_ambition_campaign IS NULL OR v_ambition_campaign <> p_campaign_id THEN
      CONTINUE;
    END IF;

    INSERT INTO ambition_progress_events (
      ambition_id, campaign_id, worker_id, source, attempt_id, outcome_id, delta_numeric, metadata
    ) VALUES (
      v_row.maps_to_ambition_id,
      p_campaign_id,
      p_worker_id,
      'phone_call',
      p_attempt_id,
      v_row.outcome_id,
      1,
      jsonb_build_object('side_effect', 'set_membership_pending')
    )
    ON CONFLICT (attempt_id, outcome_id, worker_id) DO NOTHING;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."apply_call_outcome_side_effects"("p_attempt_id" integer, "p_worker_id" integer, "p_campaign_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_employer_wizard_changes"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_group           JSONB;
  v_update          JSONB;
  v_conflicts       JSONB := '[]'::JSONB;
  v_new_parent_id   INT;
  v_existing_id     INT;
  v_actual_ts       TIMESTAMPTZ;
  v_expected_ts     TIMESTAMPTZ;
  v_member_id       INT;
  v_parents_created INT := 0;
  v_employers_updated INT := 0;
  v_worksites_updated INT := 0;
  v_admin_user_id   UUID;
BEGIN
  v_admin_user_id := (payload->>'admin_user_id')::UUID;

  -- Phase 1: Optimistic-lock validation
  FOR v_update IN
    SELECT value FROM jsonb_array_elements(
      COALESCE(payload->'category_updates', '[]'::JSONB)
    )
  LOOP
    IF v_update->>'expected_updated_at' IS NOT NULL THEN
      SELECT updated_at INTO v_actual_ts
        FROM employers
       WHERE employer_id = (v_update->>'employer_id')::INT;

      v_expected_ts := (v_update->>'expected_updated_at')::TIMESTAMPTZ;

      IF v_actual_ts IS NOT NULL
         AND v_expected_ts IS NOT NULL
         AND v_actual_ts != v_expected_ts
      THEN
        v_conflicts := v_conflicts || jsonb_build_object(
          'type',     'employer',
          'id',       (v_update->>'employer_id')::INT,
          'field',    'category',
          'expected', v_expected_ts,
          'actual',   v_actual_ts
        );
      END IF;
    END IF;
  END LOOP;

  FOR v_update IN
    SELECT value FROM jsonb_array_elements(
      COALESCE(payload->'worksite_updates', '[]'::JSONB)
    )
  LOOP
    IF v_update->>'expected_updated_at' IS NOT NULL THEN
      SELECT updated_at INTO v_actual_ts
        FROM worksites
       WHERE worksite_id = (v_update->>'worksite_id')::INT;

      v_expected_ts := (v_update->>'expected_updated_at')::TIMESTAMPTZ;

      IF v_actual_ts IS NOT NULL
         AND v_expected_ts IS NOT NULL
         AND v_actual_ts != v_expected_ts
      THEN
        v_conflicts := v_conflicts || jsonb_build_object(
          'type',     'worksite',
          'id',       (v_update->>'worksite_id')::INT,
          'field',    'principal_employer',
          'expected', v_expected_ts,
          'actual',   v_actual_ts
        );
      END IF;
    END IF;
  END LOOP;

  IF jsonb_array_length(v_conflicts) > 0 THEN
    RETURN jsonb_build_object(
      'success',   false,
      'error',     'stale_data',
      'conflicts', v_conflicts,
      'message',   'Some records were modified since the wizard loaded data. Please re-run the analysis with fresh data.'
    );
  END IF;

  -- Phase 2: Create parent companies & link children
  FOR v_group IN
    SELECT value FROM jsonb_array_elements(
      COALESCE(payload->'parent_groups', '[]'::JSONB)
    )
  LOOP
    IF (v_group->>'is_new_parent')::BOOLEAN THEN
      SELECT employer_id INTO v_existing_id
        FROM employers
       WHERE lower(employer_name) = lower(v_group->>'proposed_parent_name')
       LIMIT 1;

      IF v_existing_id IS NOT NULL THEN
        v_new_parent_id := v_existing_id;
      ELSE
        INSERT INTO employers (employer_name, is_active)
        VALUES (v_group->>'proposed_parent_name', true)
        RETURNING employer_id INTO v_new_parent_id;
        v_parents_created := v_parents_created + 1;
      END IF;
    ELSE
      v_new_parent_id := (v_group->>'existing_parent_id')::INT;
    END IF;

    FOR v_member_id IN
      SELECT (value)::INT
        FROM jsonb_array_elements_text(v_group->'member_employer_ids')
    LOOP
      IF v_member_id != v_new_parent_id THEN
        UPDATE employers
           SET parent_employer_id = v_new_parent_id,
               updated_at        = now()
         WHERE employer_id = v_member_id;
        v_employers_updated := v_employers_updated + 1;
      END IF;
    END LOOP;
  END LOOP;

  -- Phase 3: Category updates
  FOR v_update IN
    SELECT value FROM jsonb_array_elements(
      COALESCE(payload->'category_updates', '[]'::JSONB)
    )
  LOOP
    UPDATE employers
       SET employer_category = (v_update->>'proposed_category')::VARCHAR,
           updated_at        = now()
     WHERE employer_id = (v_update->>'employer_id')::INT;
    v_employers_updated := v_employers_updated + 1;
  END LOOP;

  -- Phase 4: Worksite PE updates
  FOR v_update IN
    SELECT value FROM jsonb_array_elements(
      COALESCE(payload->'worksite_updates', '[]'::JSONB)
    )
  LOOP
    UPDATE worksites
       SET principal_employer_id = (v_update->>'principal_employer_id')::INT,
           updated_at            = now()
     WHERE worksite_id = (v_update->>'worksite_id')::INT;
    v_worksites_updated := v_worksites_updated + 1;
  END LOOP;

  -- Phase 5: Audit log
  INSERT INTO import_logs (
    file_name, import_type, records_created, records_updated,
    errors, imported_by, imported_at
  ) VALUES (
    'Employer Connection Wizard',
    'employer_wizard',
    v_parents_created,
    v_employers_updated + v_worksites_updated,
    NULL,
    v_admin_user_id,
    now()
  );

  RETURN jsonb_build_object(
    'success',           true,
    'parents_created',   v_parents_created,
    'employers_updated', v_employers_updated,
    'worksites_updated', v_worksites_updated
  );
END;
$$;


ALTER FUNCTION "public"."apply_employer_wizard_changes"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_participation_import"("p_activity_id" integer, "p_rows" "jsonb", "p_source" character varying DEFAULT 'an_report_import'::character varying, "p_rating_phase" character varying DEFAULT 'actual'::character varying, "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_import_batch_id" integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  r RECORD;
  v_count INT := 0;
BEGIN
  FOR r IN
    SELECT * FROM jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb))
      AS x(worker_id INT, rating INT, binary_value TEXT, notes TEXT)
  LOOP
    IF r.worker_id IS NULL THEN
      CONTINUE;
    END IF;
    PERFORM record_assessment_event(
      p_activity_id := p_activity_id,
      p_worker_id := r.worker_id,
      p_rating := r.rating,
      p_binary_value := r.binary_value,
      p_rating_phase := p_rating_phase,
      p_event_id := NULL,
      p_source := p_source,
      p_notes := r.notes,
      p_actor_id := p_actor_id,
      p_import_batch_id := p_import_batch_id
    );
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."apply_participation_import"("p_activity_id" integer, "p_rows" "jsonb", "p_source" character varying, "p_rating_phase" character varying, "p_actor_id" "uuid", "p_import_batch_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_old_import_logs"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_archived_count INTEGER;
  v_threshold_days INTEGER := 90;
BEGIN
  -- Archive logs older than threshold (single statement: insert + mark archived)
  WITH logs_to_move AS (
    SELECT il.import_id,
      il.file_name,
      il.import_type,
      il.records_created,
      il.records_updated,
      il.errors,
      il.imported_by,
      il.imported_at,
      to_jsonb(il) AS data
    FROM import_logs il
    WHERE il.imported_at < NOW() - (v_threshold_days || ' days')::INTERVAL
      AND il.is_archived = FALSE
      AND il.archived_at IS NULL
      AND il.deleted_at IS NULL
  ),
  ins AS (
    INSERT INTO import_logs_archive (
      import_id, file_name, import_type, records_created,
      records_updated, errors, imported_by, imported_at,
      data
    )
    SELECT import_id, file_name, import_type, records_created,
      records_updated, errors, imported_by, imported_at,
      data
    FROM logs_to_move
    RETURNING import_id
  )
  UPDATE import_logs il
  SET archived_at = NOW(),
      is_archived = TRUE
  FROM ins
  WHERE il.import_id = ins.import_id;

  GET DIAGNOSTICS v_archived_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'archived_count', v_archived_count,
    'threshold_days', v_threshold_days,
    'archived_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."archive_old_import_logs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_sms_number"("p_number_id" integer, "p_purpose" character varying, "p_organiser_id" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'assign_sms_number: admin role required';
  END IF;
  IF p_purpose NOT IN ('organiser', 'relay', 'survey', 'spare') THEN
    RAISE EXCEPTION 'assign_sms_number: invalid purpose %', p_purpose;
  END IF;
  IF p_purpose = 'organiser' AND p_organiser_id IS NULL THEN
    RAISE EXCEPTION 'assign_sms_number: organiser purpose requires an organiser_id';
  END IF;
  -- Row lock serialises concurrent reassignments; retired numbers
  -- are not assignable.
  PERFORM 1 FROM sms_numbers WHERE number_id = p_number_id AND status = 'active' FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'assign_sms_number: number % not found or retired', p_number_id;
  END IF;

  UPDATE sms_number_assignments
  SET unassigned_at = now()
  WHERE number_id = p_number_id AND unassigned_at IS NULL;

  INSERT INTO sms_number_assignments (number_id, purpose, organiser_id)
  VALUES (
    p_number_id,
    p_purpose,
    CASE WHEN p_purpose = 'organiser' THEN p_organiser_id ELSE NULL END
  );

  UPDATE sms_numbers
  SET purpose = p_purpose,
      organiser_id = CASE WHEN p_purpose = 'organiser' THEN p_organiser_id ELSE NULL END
  WHERE number_id = p_number_id;
END;
$$;


ALTER FUNCTION "public"."assign_sms_number"("p_number_id" integer, "p_purpose" character varying, "p_organiser_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_sms_number"("p_number_id" integer, "p_purpose" character varying, "p_organiser_id" integer) IS 'Admin-only reassignment of a dedicated SMS number: closes the open sms_number_assignments row, opens a new one, updates sms_numbers.';



CREATE OR REPLACE FUNCTION "public"."auto_add_soc_capacity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    soc_option_id INTEGER;
BEGIN
    SELECT option_id INTO soc_option_id
    FROM capacity_options
    WHERE stage_number = NEW.stage_number
      AND option_text  = 'Structured Organising Conversation'
      AND is_active    = TRUE
    LIMIT 1;

    IF soc_option_id IS NULL THEN
        RETURN NEW;
    END IF;

    IF EXISTS (
        SELECT 1 FROM plan_capacities
        WHERE plan_id = NEW.plan_id
          AND capacity_option_id = soc_option_id
    ) THEN
        RETURN NEW;
    END IF;

    INSERT INTO plan_capacities (plan_id, capacity_option_id, status, sort_order)
    VALUES (
        NEW.plan_id,
        soc_option_id,
        'needed',
        COALESCE((SELECT MAX(sort_order) + 1 FROM plan_capacities WHERE plan_id = NEW.plan_id), 0)
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_add_soc_capacity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_bargaining_phase"("p_campaign_id" integer, "p_bargaining_commenced_at" "date", "p_carryforward_ambition_ids" integer[], "p_carryforward_situation_analysis_id" integer, "p_claim_summary" "text", "p_pia_seed_pack" "text", "p_situation_overrides" "jsonb", "p_setup_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_stage7_plan_id  INT;
  v_plan_id         INT;
  v_ambition_id     INT;
  v_new_sa_id       INT;
  v_new_version     INT;
  v_existing_phase  TEXT;
BEGIN
  -- ── 1. Authorisation ──────────────────────────────────────────────────
  IF get_user_role() NOT IN ('admin', 'user') THEN
    RAISE EXCEPTION 'begin_bargaining_phase: permission denied (role=%)', get_user_role();
  END IF;

  -- ── 2. Guard: already in bargaining_to_win ──────────────────────────────────
  SELECT current_phase::TEXT
    INTO v_existing_phase
    FROM campaigns
   WHERE campaign_id = p_campaign_id;

  IF v_existing_phase = 'bargaining_to_win' THEN
    RAISE EXCEPTION 'begin_bargaining_phase: campaign % is already in bargaining_to_win phase', p_campaign_id;
  END IF;

  -- ── 3. Create campaign_stage_plans for stages 7–11 ────────────────────────
  -- Stage 7 is active; 8–11 are draft.
  INSERT INTO campaign_stage_plans (
    campaign_id,
    stage_number,
    stage_name,
    status,
    phase
  ) VALUES
    (p_campaign_id, 7,  'Bargaining Commences',             'active',  'bargaining_to_win'::campaign_phase_enum),
    (p_campaign_id, 8,  'Testing the Employer',             'draft',   'bargaining_to_win'::campaign_phase_enum),
    (p_campaign_id, 9,  'Strength Assessment & Decision',   'draft',   'bargaining_to_win'::campaign_phase_enum),
    (p_campaign_id, 10, 'Protected Industrial Action',      'draft',   'bargaining_to_win'::campaign_phase_enum),
    (p_campaign_id, 11, 'Settlement & Ratification',        'draft',   'bargaining_to_win'::campaign_phase_enum)
  RETURNING plan_id INTO v_stage7_plan_id;

  -- Capture the stage 7 plan_id (the INSERT…RETURNING above only returns the
  -- last inserted row — fetch it explicitly to be safe).
  SELECT plan_id
    INTO v_stage7_plan_id
    FROM campaign_stage_plans
   WHERE campaign_id = p_campaign_id
     AND stage_number = 7;

  -- ── 4. Carry-forward ambitions into stage 7 plan_ambitions ────────────────────
  IF p_carryforward_ambition_ids IS NOT NULL AND array_length(p_carryforward_ambition_ids, 1) > 0 THEN
    INSERT INTO plan_ambitions (
      plan_id,
      custom_text,
      sort_order
    )
    SELECT
      v_stage7_plan_id,
      ca.label,
      ca.sort_order
    FROM campaign_ambitions ca
    WHERE ca.campaign_ambition_id = ANY(p_carryforward_ambition_ids)
      AND ca.campaign_id = p_campaign_id;
  END IF;

  -- ── 5. Clone situation analysis + apply overrides ───────────────────────────
  IF p_carryforward_situation_analysis_id IS NOT NULL THEN
    -- Determine next version number for this campaign
    SELECT COALESCE(MAX(version), 0) + 1
      INTO v_new_version
      FROM campaign_situation_analyses
     WHERE campaign_id = p_campaign_id;

    -- Mark existing current row as not-current
    UPDATE campaign_situation_analyses
       SET is_current = FALSE
     WHERE campaign_id = p_campaign_id
       AND is_current = TRUE;

    -- Insert cloned row with overrides merged in
    INSERT INTO campaign_situation_analyses (
      campaign_id,
      version,
      is_current,
      employer_interaction_state,
      employer_state_notes,
      balloted_count,
      top_issues,
      upcoming_workforce_changes,
      employer_relationships,
      hr_posture,
      union_history,
      strategic_context_summary,
      company_playbook,
      workforce_populations,
      leverage_and_maths,
      information_gaps,
      ai_generated,
      ai_model,
      ai_prompt_snapshot
    )
    SELECT
      campaign_id,
      v_new_version,
      TRUE,
      -- Apply scalar overrides from p_situation_overrides JSONB if provided
      COALESCE(
        p_situation_overrides->>'employer_interaction_state',
        employer_interaction_state
      ),
      COALESCE(
        p_situation_overrides->>'employer_state_notes',
        employer_state_notes
      ),
      COALESCE(
        (p_situation_overrides->>'balloted_count')::INT,
        balloted_count
      ),
      CASE WHEN p_situation_overrides ? 'top_issues'
           THEN p_situation_overrides->'top_issues'
           ELSE top_issues END,
      CASE WHEN p_situation_overrides ? 'upcoming_workforce_changes'
           THEN p_situation_overrides->'upcoming_workforce_changes'
           ELSE upcoming_workforce_changes END,
      CASE WHEN p_situation_overrides ? 'employer_relationships'
           THEN p_situation_overrides->'employer_relationships'
           ELSE employer_relationships END,
      CASE WHEN p_situation_overrides ? 'hr_posture'
           THEN p_situation_overrides->'hr_posture'
           ELSE hr_posture END,
      CASE WHEN p_situation_overrides ? 'union_history'
           THEN p_situation_overrides->'union_history'
           ELSE union_history END,
      COALESCE(
        p_situation_overrides->>'strategic_context_summary',
        strategic_context_summary
      ),
      CASE WHEN p_situation_overrides ? 'company_playbook'
           THEN p_situation_overrides->'company_playbook'
           ELSE company_playbook END,
      CASE WHEN p_situation_overrides ? 'workforce_populations'
           THEN p_situation_overrides->'workforce_populations'
           ELSE workforce_populations END,
      CASE WHEN p_situation_overrides ? 'leverage_and_maths'
           THEN p_situation_overrides->'leverage_and_maths'
           ELSE leverage_and_maths END,
      CASE WHEN p_situation_overrides ? 'information_gaps'
           THEN p_situation_overrides->'information_gaps'
           ELSE information_gaps END,
      ai_generated,
      ai_model,
      ai_prompt_snapshot
    FROM campaign_situation_analyses
    WHERE situation_id = p_carryforward_situation_analysis_id
      AND campaign_id = p_campaign_id
    RETURNING situation_id INTO v_new_sa_id;
  END IF;

  -- ── 6. Insert intractable_bargaining_tracker row ─────────────────────────────
  INSERT INTO intractable_bargaining_tracker (
    campaign_id,
    bargaining_commenced_at,
    state
  ) VALUES (
    p_campaign_id,
    p_bargaining_commenced_at,
    'safe'
  );

  -- ── 7. Seed PIA pack (if function exists) ────────────────────────────────────
  IF p_pia_seed_pack = 'offshore_standard' THEN
    IF EXISTS (
      SELECT 1 FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE p.proname = 'seed_pia_pack_offshore_standard'
        AND n.nspname = 'public'
    ) THEN
      BEGIN
        PERFORM seed_pia_pack_offshore_standard(p_campaign_id);
      EXCEPTION WHEN undefined_function THEN
        NULL; -- function was dropped between check and call — ignore
      END;
    END IF;
  ELSIF p_pia_seed_pack = 'shore_based_standard' THEN
    IF EXISTS (
      SELECT 1 FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE p.proname = 'seed_pia_pack_shore_based_standard'
        AND n.nspname = 'public'
    ) THEN
      BEGIN
        PERFORM seed_pia_pack_shore_based_standard(p_campaign_id);
      EXCEPTION WHEN undefined_function THEN
        NULL;
      END;
    END IF;
  END IF;

  -- ── 8. Seed bargaining gate definitions ────────────────────────────────────
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE p.proname = 'seed_bargaining_gates'
      AND n.nspname = 'public'
  ) THEN
    BEGIN
      PERFORM seed_bargaining_gates(p_campaign_id);
    EXCEPTION WHEN undefined_function THEN
      NULL;
    END;
  END IF;

  -- ── 9. Update campaigns ─────────────────────────────────────────────────────
  UPDATE campaigns
     SET current_phase           = 'bargaining_to_win'::campaign_phase_enum,
         bargaining_commenced_at = p_bargaining_commenced_at
   WHERE campaign_id = p_campaign_id;

  -- ── 10. Seed WOC meeting activity template (Phase 8) ───────────────────────────
  PERFORM seed_bargaining_woc_template(p_campaign_id);

  -- ── 11. Return summary ───────────────────────────────────────────────────────
  RETURN jsonb_build_object(
    'success',          TRUE,
    'campaign_id',      p_campaign_id,
    'stage_7_plan_id',  v_stage7_plan_id,
    'setup_mode',       p_setup_mode,
    'new_sa_version',   v_new_version
  );
END;
$$;


ALTER FUNCTION "public"."begin_bargaining_phase"("p_campaign_id" integer, "p_bargaining_commenced_at" "date", "p_carryforward_ambition_ids" integer[], "p_carryforward_situation_analysis_id" integer, "p_claim_summary" "text", "p_pia_seed_pack" "text", "p_situation_overrides" "jsonb", "p_setup_mode" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."begin_bargaining_phase"("p_campaign_id" integer, "p_bargaining_commenced_at" "date", "p_carryforward_ambition_ids" integer[], "p_carryforward_situation_analysis_id" integer, "p_claim_summary" "text", "p_pia_seed_pack" "text", "p_situation_overrides" "jsonb", "p_setup_mode" "text") IS 'Atomically begins the Bargaining to Win phase for a campaign. Creates stage plans 7-11, carries forward ambitions, clones the situation analysis with overrides, seeds the intractable tracker, PIA pack, and WOC meeting activity template. Returns summary JSONB with stage_7_plan_id. (Phase 8: added WOC template seed step.)';



CREATE OR REPLACE FUNCTION "public"."cache_ai_response"("p_prompt" "text", "p_response" "jsonb", "p_model_name" "text", "p_model_version" "text" DEFAULT NULL::"text", "p_tokens_used" integer DEFAULT NULL::integer, "p_cost_usd" numeric DEFAULT NULL::numeric, "p_ttl_hours" integer DEFAULT NULL::integer) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_cache_key TEXT;
  v_cache_id BIGINT;
  v_expires_at TIMESTAMPTZ;
BEGIN
  v_cache_key := generate_ai_cache_key(p_prompt, p_model_name);
  IF p_ttl_hours IS NOT NULL THEN
    v_expires_at := NOW() + (p_ttl_hours || ' hours')::INTERVAL;
  END IF;
  INSERT INTO ai_response_cache (
    cache_key,
    prompt_hash,
    prompt,
    response,
    model_name,
    model_version,
    tokens_used,
    cost_usd,
    expires_at
  ) VALUES (
    v_cache_key,
    encode(digest(p_prompt || p_model_name, 'sha256'), 'hex'),
    p_prompt,
    p_response,
    p_model_name,
    p_model_version,
    p_tokens_used,
    p_cost_usd,
    v_expires_at
  )
  ON CONFLICT (cache_key) DO UPDATE SET
    response = EXCLUDED.response,
    tokens_used = EXCLUDED.tokens_used,
    cost_usd = EXCLUDED.cost_usd,
    last_accessed_at = NOW(),
    access_count = ai_response_cache.access_count + 1,
    expires_at = EXCLUDED.expires_at
  RETURNING cache_id INTO v_cache_id;
  INSERT INTO ai_cache_audit_log (cache_id, operation, metadata)
  VALUES (v_cache_id, 'store', '{"model_name": "' || p_model_name || '"}');
  RETURN v_cache_id;
END;
$$;


ALTER FUNCTION "public"."cache_ai_response"("p_prompt" "text", "p_response" "jsonb", "p_model_name" "text", "p_model_version" "text", "p_tokens_used" integer, "p_cost_usd" numeric, "p_ttl_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_active_wocs"("p_agreement_id" integer) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM campaign_wocs cw
  JOIN campaign_timelines ct ON ct.campaign_id = cw.campaign_id
  WHERE ct.agreement_id = p_agreement_id
    AND cw.status = 'active';
  RETURN COALESCE(v_count, 0);
END;
$$;


ALTER FUNCTION "public"."calculate_active_wocs"("p_agreement_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_contact_details_verified"("p_agreement_id" integer) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_total_workers NUMERIC;
  v_verified_count NUMERIC;
  v_percentage NUMERIC;
BEGIN
  -- Count workers on agreement scope
  SELECT COUNT(DISTINCT w.worker_id)
  INTO v_total_workers
  FROM workers w
  JOIN agreement_worksites aw ON aw.worksite_id = w.worksite_id
  WHERE aw.agreement_id = p_agreement_id
    AND w.is_active = true;

  IF v_total_workers = 0 THEN
    RETURN NULL;
  END IF;

  -- Count workers with both phone and email
  SELECT COUNT(DISTINCT w.worker_id)
  INTO v_verified_count
  FROM workers w
  JOIN agreement_worksites aw ON aw.worksite_id = w.worksite_id
  WHERE aw.agreement_id = p_agreement_id
    AND w.is_active = true
    AND w.phone IS NOT NULL
    AND w.email IS NOT NULL
    AND w.phone != ''
    AND w.email != '';

  IF v_total_workers = 0 THEN
    RETURN NULL;
  END IF;

  v_percentage := ROUND((v_verified_count / v_total_workers) * 100, 2);

  RETURN v_percentage;
END;
$$;


ALTER FUNCTION "public"."calculate_contact_details_verified"("p_agreement_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_membership_density"("p_agreement_id" integer) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_member_count NUMERIC;
  v_total_workers NUMERIC;
  v_density NUMERIC;
BEGIN
  -- Count workers with agreements on this agreement
  SELECT COUNT(DISTINCT wa.worker_id)
  INTO v_member_count
  FROM worker_agreements wa
  JOIN workers w ON w.worker_id = wa.worker_id
  JOIN agreements a ON a.agreement_id = wa.agreement_id
  WHERE a.agreement_id = p_agreement_id
    AND w.is_active = true;

  -- Count total workers on agreement scope (via agreement_worksites)
  -- For now, estimate using workers linked to worksites covered by this agreement
  SELECT COUNT(DISTINCT w.worker_id)
  INTO v_total_workers
  FROM workers w
  JOIN agreement_worksites aw ON aw.worksite_id = w.worksite_id
  WHERE aw.agreement_id = p_agreement_id
    AND w.is_active = true;

  IF v_total_workers = 0 THEN
    RETURN NULL;
  END IF;

  v_density := ROUND((v_member_count / v_total_workers) * 100, 2);

  RETURN v_density;
END;
$$;


ALTER FUNCTION "public"."calculate_membership_density"("p_agreement_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."campaign_fact_enum_values"("p_options" "jsonb") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_vals TEXT[] := ARRAY[]::TEXT[];
  v_el JSONB;
BEGIN
  IF p_options IS NULL OR jsonb_typeof(p_options) <> 'array' THEN
    RETURN v_vals;
  END IF;
  FOR v_el IN SELECT jsonb_array_elements(p_options)
  LOOP
    IF jsonb_typeof(v_el) = 'string' THEN
      v_vals := array_append(v_vals, v_el #>> '{}');
    ELSIF jsonb_typeof(v_el) = 'object' AND v_el ? 'value' THEN
      v_vals := array_append(v_vals, v_el->>'value');
    END IF;
  END LOOP;
  RETURN v_vals;
END;
$$;


ALTER FUNCTION "public"."campaign_fact_enum_values"("p_options" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_write_to_campaign"("p_campaign_id" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT
    (EXISTS (
      SELECT 1 FROM campaigns
      WHERE campaign_id = p_campaign_id
        AND is_standing = TRUE
    ) AND auth.uid() IS NOT NULL)
    OR is_admin()
    OR is_campaign_creator(p_campaign_id)
    OR is_lead_organiser_for_campaign(p_campaign_id)
    OR is_assigned_to_campaign(p_campaign_id)
    OR has_campaign_edit_permission(p_campaign_id);
$$;


