CREATE OR REPLACE FUNCTION "public"."check_gate_change_against_overlap"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  cid   INT;
  gnum  INT;
  -- For phase 1 gates (1–5): gate N sits between stage N and stage N+1.
  -- For phase 2 gates (6–10): gate N sits between stage N+1 and stage N+2.
  -- Formula: left_stage = gate_number (phase 1) or gate_number + 1 (phase 2).
  left_stage  INT;
  right_stage INT;
  stage_a RECORD;
  stage_b RECORD;
BEGIN
  IF NEW.enforcement_type IS DISTINCT FROM 'hard' OR NEW.is_active IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  cid  := NEW.campaign_id;
  gnum := NEW.gate_number;

  -- Determine which two stages this gate sits between.
  IF gnum BETWEEN 1 AND 5 THEN
    -- Phase 1 gates: gate N is between stage N and stage N+1.
    left_stage  := gnum;
    right_stage := gnum + 1;
  ELSIF gnum BETWEEN 6 AND 10 THEN
    -- Phase 2 gates: gate N is between stage N+1 and stage N+2.
    -- e.g. gate 6 sits between stages 7 and 8.
    left_stage  := gnum + 1;
    right_stage := gnum + 2;
  ELSE
    -- Unknown gate number — allow (defensive).
    RETURN NEW;
  END IF;

  SELECT planned_start_date, planned_end_date
    INTO stage_a
    FROM campaign_stage_plans
   WHERE campaign_id = cid AND stage_number = left_stage;
  SELECT planned_start_date, planned_end_date
    INTO stage_b
    FROM campaign_stage_plans
   WHERE campaign_id = cid AND stage_number = right_stage;

  IF stage_a.planned_end_date IS NOT NULL
     AND stage_b.planned_start_date IS NOT NULL
     AND stage_b.planned_start_date < stage_a.planned_end_date THEN
    RAISE EXCEPTION
      'Cannot make gate % a hard active gate: stages % and % currently overlap (% to %, % to %). Resolve the overlap first.',
      gnum,
      left_stage, right_stage,
      stage_a.planned_start_date, stage_a.planned_end_date,
      stage_b.planned_start_date, stage_b.planned_end_date
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_gate_change_against_overlap"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_gate_change_against_overlap"() IS 'B2W Phase 1 (replaces Phase-6 version): prevents flipping a gate to hard + active when the adjoining stages already overlap. Phase-aware: gate_number 1–5 sit between stages 1–6 (Phase 1); gate_number 6–10 will sit between stages 7–11 (Phase 2).';



CREATE OR REPLACE FUNCTION "public"."check_no_worker_on_group_container"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_is_container BOOLEAN;
BEGIN
  SELECT is_group_container INTO v_is_container
  FROM campaign_organising_units
  WHERE ou_id = NEW.ou_id;

  IF v_is_container = TRUE THEN
    RAISE EXCEPTION
      'Cannot assign workers directly to group container OU %. '
      'Assign workers to the individual units within the group instead.',
      NEW.ou_id;
  END IF;

  RETURN NEW;
END;
$$;


