CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_endpoint" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_config RECORD;
  v_minute_count INTEGER;
  v_hour_count INTEGER;
  v_day_count INTEGER;
  v_is_limited BOOLEAN := false;
  v_limit_reason TEXT := NULL;
BEGIN
  SELECT * INTO v_config
  FROM rate_limit_config
  WHERE user_id = p_user_id;

  IF NOT FOUND OR v_config.is_exempt THEN
    RETURN jsonb_build_object(
      'allowed', true,
      'limit', NULL,
      'remaining', NULL,
      'reset_at', NULL
    );
  END IF;

  SELECT COUNT(*) INTO v_minute_count
  FROM rate_limit_usage
  WHERE user_id = p_user_id
    AND requested_at > NOW() - INTERVAL '1 minute';

  SELECT COUNT(*) INTO v_hour_count
  FROM rate_limit_usage
  WHERE user_id = p_user_id
    AND requested_at > NOW() - INTERVAL '1 hour';

  SELECT COUNT(*) INTO v_day_count
  FROM rate_limit_usage
  WHERE user_id = p_user_id
    AND requested_at > NOW() - INTERVAL '1 day';

  IF v_config.requests_per_minute IS NOT NULL AND v_minute_count >= v_config.requests_per_minute THEN
    v_is_limited := true;
    v_limit_reason := 'Rate limit exceeded: ' || v_minute_count || ' requests per minute (limit: ' || v_config.requests_per_minute || ')';
    RETURN jsonb_build_object(
      'allowed', false,
      'limit', v_config.requests_per_minute,
      'remaining', 0,
      'reset_at', EXTRACT(EPOCH FROM (NOW() + INTERVAL '1 minute')),
      'reason', v_limit_reason,
      'window', 'minute'
    );
  END IF;

  IF v_config.requests_per_hour IS NOT NULL AND v_hour_count >= v_config.requests_per_hour THEN
    v_is_limited := true;
    v_limit_reason := 'Rate limit exceeded: ' || v_hour_count || ' requests per hour (limit: ' || v_config.requests_per_hour || ')';
    RETURN jsonb_build_object(
      'allowed', false,
      'limit', v_config.requests_per_hour,
      'remaining', 0,
      'reset_at', EXTRACT(EPOCH FROM (NOW() + INTERVAL '1 hour')),
      'reason', v_limit_reason,
      'window', 'hour'
    );
  END IF;

  IF v_config.requests_per_day IS NOT NULL AND v_day_count >= v_config.requests_per_day THEN
    v_is_limited := true;
    v_limit_reason := 'Rate limit exceeded: ' || v_day_count || ' requests per day (limit: ' || v_config.requests_per_day || ')';
    RETURN jsonb_build_object(
      'allowed', false,
      'limit', v_config.requests_per_day,
      'remaining', 0,
      'reset_at', EXTRACT(EPOCH FROM (DATE_TRUNC('day', NOW() + INTERVAL '1 day'))),
      'reason', v_limit_reason,
      'window', 'day'
    );
  END IF;

  v_limit_reason := NULL;
  RETURN jsonb_build_object(
    'allowed', true,
    'remaining_per_minute', CASE
      WHEN v_config.requests_per_minute IS NOT NULL THEN v_config.requests_per_minute - v_minute_count
      ELSE NULL
    END,
    'remaining_per_hour', CASE
      WHEN v_config.requests_per_hour IS NOT NULL THEN v_config.requests_per_hour - v_hour_count
      ELSE NULL
    END,
    'remaining_per_day', CASE
      WHEN v_config.requests_per_day IS NOT NULL THEN v_config.requests_per_day - v_day_count
      ELSE NULL
    END
  );
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_endpoint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_worker_ou_group_exclusivity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_new_ou_group_id INT;
  v_new_ou_type     VARCHAR(30);
  v_new_campaign_id INT;
  v_conflict_count  INT;
BEGIN
  SELECT ou_group_id, ou_type, campaign_id
    INTO v_new_ou_group_id, v_new_ou_type, v_new_campaign_id
  FROM campaign_organising_units
  WHERE ou_id = NEW.ou_id;

  IF v_new_ou_group_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*) INTO v_conflict_count
  FROM campaign_worker_ou cwo
  JOIN campaign_organising_units cou ON cou.ou_id = cwo.ou_id
  WHERE cwo.worker_id = NEW.worker_id
    AND cwo.ou_id    <> NEW.ou_id
    AND cou.campaign_id  = v_new_campaign_id
    AND cou.ou_group_id IS NOT NULL
    AND cou.ou_group_id <> v_new_ou_group_id
    AND cou.ou_type      = v_new_ou_type;

  IF v_conflict_count > 0 THEN
    RAISE EXCEPTION
      'Worker % is already assigned to a unit in a different % group within this campaign. '
      'Workers can only belong to one group of any given type per campaign. '
      'Remove the worker from their existing % group before reassigning.',
      NEW.worker_id, v_new_ou_type, v_new_ou_type;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_worker_ou_group_exclusivity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_next_call_list_item"("p_list_id" integer, "p_session_label" "text", "p_session_worker_id" integer DEFAULT NULL::integer, "p_claim_ttl_seconds" integer DEFAULT 900, "p_share_token_id" integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_item_id INTEGER;
BEGIN
  WITH parent_list AS (
    SELECT list_id, priority_strategy
    FROM call_lists
    WHERE list_id = p_list_id
  ),
  candidate AS (
    SELECT cli.item_id
    FROM call_list_items cli
    JOIN parent_list pl ON pl.list_id = cli.list_id
    WHERE cli.list_id = p_list_id
      AND (
        cli.status = 'pending'
        OR (
          cli.status = 'in_progress'
          AND cli.claimed_at IS NOT NULL
          AND cli.claimed_at < now() - make_interval(secs => GREATEST(p_claim_ttl_seconds, 1))
        )
        OR (
          cli.status = 'deferred'
          AND cli.next_call_at IS NOT NULL
          AND cli.next_call_at <= now()
        )
      )
    ORDER BY
      CASE WHEN pl.priority_strategy = 'priority_score' THEN cli.priority_score END DESC NULLS LAST,
      CASE WHEN pl.priority_strategy = 'least_recently_contacted' THEN cli.last_attempt_at END ASC NULLS FIRST,
      cli.sort_order ASC,
      cli.item_id ASC
    LIMIT 1
    FOR UPDATE OF cli SKIP LOCKED
  )
  UPDATE call_list_items cli
  SET
    status = 'in_progress',
    claimed_at = now(),
    claimed_by_session_label = LEFT(p_session_label, 80),
    claimed_by_worker_id = p_session_worker_id,
    claimed_by_share_token_id = p_share_token_id,
    updated_at = now()
  FROM candidate
  WHERE cli.item_id = candidate.item_id
  RETURNING cli.item_id INTO v_item_id;

  RETURN v_item_id;
END;
$$;


ALTER FUNCTION "public"."claim_next_call_list_item"("p_list_id" integer, "p_session_label" "text", "p_session_worker_id" integer, "p_claim_ttl_seconds" integer, "p_share_token_id" integer) OWNER TO "postgres";


