ALTER FUNCTION "public"."claim_next_call_list_item_for_share"("p_list_id" integer, "p_session_label" "text", "p_session_worker_id" integer, "p_claim_ttl_seconds" integer, "p_share_token_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_sms_conversation"("p_conversation_id" integer, "p_ttl_minutes" integer DEFAULT 5) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN false;
  END IF;

  UPDATE sms_conversations
  SET claim_user_id = v_uid,
      claimed_until = now() + make_interval(mins => GREATEST(p_ttl_minutes, 1))
  WHERE conversation_id = p_conversation_id
    AND (
      claim_user_id IS NULL
      OR claim_user_id = v_uid
      OR claimed_until IS NULL
      OR claimed_until < now()
    );

  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."claim_sms_conversation"("p_conversation_id" integer, "p_ttl_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_sms_conversation"("p_conversation_id" integer, "p_ttl_minutes" integer) IS 'Soft-claims an SMS conversation for the caller (TTL minutes). Returns true when the claim was set/renewed; false when another user holds an unexpired claim.';



CREATE OR REPLACE FUNCTION "public"."cleanup_old_rate_limit_usage"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_deleted_count INTEGER;
BEGIN
  DELETE FROM rate_limit_usage
  WHERE requested_at < NOW() - INTERVAL '90 days';

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  RETURN v_deleted_count;
END;
$$;


