CREATE TABLE IF NOT EXISTS "public"."upcoming_project_employers" (
    "id" bigint NOT NULL,
    "upcoming_project_id" bigint NOT NULL,
    "employer_id" integer,
    "role_type" character varying(30) DEFAULT 'Operator'::character varying NOT NULL,
    "is_primary" boolean DEFAULT true NOT NULL,
    "match_status" "text" NOT NULL,
    "match_score" numeric(4,3),
    "match_method" "text",
    "candidate_proposals" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "confirmed_by" "uuid",
    "confirmed_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "upcoming_project_employers_match_method_check" CHECK (("match_method" = ANY (ARRAY['exact'::"text", 'fuzzy'::"text", 'manual'::"text", 'created'::"text"]))),
    CONSTRAINT "upcoming_project_employers_match_status_check" CHECK (("match_status" = ANY (ARRAY['auto'::"text", 'needs_review'::"text", 'confirmed'::"text", 'overridden'::"text", 'rejected'::"text", 'unmatched'::"text"]))),
    CONSTRAINT "upcoming_project_employers_role_type_check" CHECK ((("role_type")::"text" = ANY ((ARRAY['Owner'::character varying, 'Operator'::character varying, 'Principal_Contractor'::character varying, 'Subcontractor'::character varying, 'Labour_Hire'::character varying, 'Catering'::character varying, 'Maintenance'::character varying, 'Drilling'::character varying, 'ROV'::character varying, 'Inspection'::character varying, 'Transport'::character varying, 'Decommissioning'::character varying, 'Aviation'::character varying, 'Other'::character varying])::"text"[])))
);


ALTER TABLE "public"."upcoming_project_employers" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_upcoming_project_match"("payload" "jsonb") RETURNS "public"."upcoming_project_employers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id           BIGINT;
  v_action       TEXT;
  v_employer_id  INT;
  v_notes        TEXT;
  v_row          upcoming_project_employers;
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Only admins may confirm upcoming-project matches';
  END IF;

  v_id          := (payload->>'id')::BIGINT;
  v_action      := payload->>'action';
  v_employer_id := NULLIF(payload->>'employer_id', '')::INT;
  v_notes       := payload->>'notes';

  IF v_id IS NULL OR v_action IS NULL THEN
    RAISE EXCEPTION 'payload must include id and action';
  END IF;

  IF v_action NOT IN ('confirm', 'override', 'create_link', 'reject', 'reopen') THEN
    RAISE EXCEPTION 'unsupported action: %', v_action;
  END IF;

  -- confirm = accept the auto/needs_review candidate as-is or specified employer
  -- override = admin chose a different existing employer (manual pick)
  -- create_link = a brand-new employer was created via apply_employer_wizard_changes
  --                and we now link it (match_method='created')
  -- reject = mark as unmatchable
  -- reopen = clear admin decision, return to needs_review

  IF v_action = 'confirm' THEN
    UPDATE upcoming_project_employers
       SET employer_id   = COALESCE(v_employer_id, employer_id),
           match_status  = 'confirmed',
           match_method  = COALESCE(match_method, 'fuzzy'),
           confirmed_by  = auth.uid(),
           confirmed_at  = now(),
           notes         = v_notes
     WHERE id = v_id
     RETURNING * INTO v_row;

  ELSIF v_action = 'override' THEN
    IF v_employer_id IS NULL THEN
      RAISE EXCEPTION 'override requires employer_id';
    END IF;
    UPDATE upcoming_project_employers
       SET employer_id   = v_employer_id,
           match_status  = 'overridden',
           match_method  = 'manual',
           match_score   = NULL,
           confirmed_by  = auth.uid(),
           confirmed_at  = now(),
           notes         = v_notes
     WHERE id = v_id
     RETURNING * INTO v_row;

  ELSIF v_action = 'create_link' THEN
    IF v_employer_id IS NULL THEN
      RAISE EXCEPTION 'create_link requires employer_id of newly created employer';
    END IF;
    UPDATE upcoming_project_employers
       SET employer_id   = v_employer_id,
           match_status  = 'confirmed',
           match_method  = 'created',
           match_score   = NULL,
           confirmed_by  = auth.uid(),
           confirmed_at  = now(),
           notes         = v_notes
     WHERE id = v_id
     RETURNING * INTO v_row;

  ELSIF v_action = 'reject' THEN
    UPDATE upcoming_project_employers
       SET employer_id   = NULL,
           match_status  = 'rejected',
           match_method  = NULL,
           match_score   = NULL,
           confirmed_by  = auth.uid(),
           confirmed_at  = now(),
           notes         = v_notes
     WHERE id = v_id
     RETURNING * INTO v_row;

  ELSIF v_action = 'reopen' THEN
    UPDATE upcoming_project_employers
       SET match_status  = CASE
                              WHEN candidate_proposals = '[]'::jsonb THEN 'unmatched'
                              ELSE 'needs_review'
                            END,
           confirmed_by  = NULL,
           confirmed_at  = NULL
     WHERE id = v_id
     RETURNING * INTO v_row;
  END IF;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'upcoming_project_employers row % not found', v_id;
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."confirm_upcoming_project_match"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cou_enforce_group_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- A dangling ou_group_id (group set, no parent) is only reachable while a
  -- parent group is being deleted. Clear it rather than rejecting the delete.
  IF NEW.ou_group_id IS NOT NULL AND NEW.parent_ou_id IS NULL THEN
    NEW.ou_group_id := NULL;
  END IF;

  IF NEW.ou_group_id IS NOT NULL
     AND NEW.parent_ou_id IS NOT NULL
     AND NEW.ou_group_id <> NEW.parent_ou_id THEN
    RAISE EXCEPTION
      'campaign_organising_units: ou_group_id (%) must equal parent_ou_id (%) when both are set',
      NEW.ou_group_id, NEW.parent_ou_id;
  END IF;

  IF NEW.is_group_container = TRUE AND NEW.ou_group_id IS NOT NULL THEN
    RAISE EXCEPTION
      'campaign_organising_units: a group container (ou_id %) cannot also be a group member',
      NEW.ou_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."cou_enforce_group_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cou_enforce_hierarchy_invariants"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_parent_id       INT;
  v_parent_campaign INT;
  v_parent_is_cont  BOOLEAN;
  v_gp_id           INT;
  v_gp_is_cont      BOOLEAN;
BEGIN
  IF NEW.parent_ou_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT parent_ou_id, campaign_id, is_group_container
    INTO v_parent_id, v_parent_campaign, v_parent_is_cont
  FROM campaign_organising_units
  WHERE ou_id = NEW.parent_ou_id;

  IF v_parent_campaign IS NULL THEN
    RAISE EXCEPTION
      'campaign_organising_units.parent_ou_id % does not exist', NEW.parent_ou_id;
  END IF;

  IF v_parent_campaign <> NEW.campaign_id THEN
    RAISE EXCEPTION
      'sub-unit (campaign_id=%) cannot reference a parent OU from a different campaign (campaign_id=%)',
      NEW.campaign_id, v_parent_campaign;
  END IF;

  -- Depth-1: parent is top-level -> always allowed.
  IF v_parent_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Depth-2: parent is itself a child. Only allow when the grandparent is a group container.
  SELECT parent_ou_id, is_group_container
    INTO v_gp_id, v_gp_is_cont
  FROM campaign_organising_units
  WHERE ou_id = v_parent_id;

  IF v_gp_id IS NOT NULL THEN
    RAISE EXCEPTION
      'campaign_organising_units only supports three levels of nesting (grandparent % is itself a sub-unit)',
      v_parent_id;
  END IF;

  IF NOT v_gp_is_cont THEN
    RAISE EXCEPTION
      'A sub-unit of a sub-unit is only permitted when the top-level ancestor is a group container (OU % is not a group container)', v_parent_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."cou_enforce_hierarchy_invariants"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cou_enforce_hierarchy_invariants"() IS 'Enforces OU hierarchy invariants on INSERT/UPDATE. Allows two levels (parent -> child) for any top-level unit. Allows three levels (container -> unit -> sub-unit) when the top-level unit is a group container (is_group_container = TRUE). Prevents cross-campaign references.';



CREATE OR REPLACE FUNCTION "public"."create_call_list_from_activity"("p_activity_id" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_act    campaign_activities%ROWTYPE;
  v_list_id INTEGER;
BEGIN
  SELECT * INTO v_act
  FROM campaign_activities
  WHERE activity_id = p_activity_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Activity % not found', p_activity_id;
  END IF;

  IF v_act.activity_kind <> 'phone_call_list' THEN
    RAISE EXCEPTION
      'Activity % has kind %, expected phone_call_list',
      p_activity_id, v_act.activity_kind;
  END IF;

  INSERT INTO call_lists (
    campaign_id,
    section_plan_id,
    name,
    description,
    status
  )
  VALUES (
    v_act.campaign_id,
    v_act.section_plan_id,
    COALESCE(v_act.title, 'Call list — section activity ' || p_activity_id),
    v_act.description,
    'draft'
  )
  RETURNING list_id INTO v_list_id;

  RETURN v_list_id;
END;
$$;


ALTER FUNCTION "public"."create_call_list_from_activity"("p_activity_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_campaign"("p_campaign_id" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF NOT (public.is_admin() OR public.is_lead_organiser_for_campaign(p_campaign_id)) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM campaigns WHERE campaign_id = p_campaign_id) THEN
    RAISE EXCEPTION 'campaign_not_found';
  END IF;

  DELETE FROM campaign_stage_workplan_tasks WHERE campaign_id = p_campaign_id;

  DELETE FROM gate_assessments ga
  USING gate_definitions gd
  WHERE ga.gate_id = gd.gate_id AND gd.campaign_id = p_campaign_id;

  DELETE FROM gate_definitions WHERE campaign_id = p_campaign_id;

  DELETE FROM campaign_stage_plans WHERE campaign_id = p_campaign_id;

  DELETE FROM reporting_snapshots WHERE campaign_id = p_campaign_id;

  DELETE FROM campaign_timelines WHERE campaign_id = p_campaign_id;

  DELETE FROM campaigns WHERE campaign_id = p_campaign_id;
END;
$$;


ALTER FUNCTION "public"."delete_campaign"("p_campaign_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_campaign"("p_campaign_id" integer) IS 'Deletes a campaign and dependent planning data. Allowed for admins and lead organisers only.';



CREATE OR REPLACE FUNCTION "public"."delete_old_import_logs"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_deleted_count INTEGER := 0;
  v_n INTEGER;
  v_retention_days INTEGER := 365; -- 1 year
BEGIN
  -- Delete archived logs older than retention period
  DELETE FROM import_logs_archive
  WHERE archived_at < NOW() - (v_retention_days || ' days')::INTERVAL
  AND archived_at IS NOT NULL;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_deleted_count := v_deleted_count + v_n;

  -- Also permanently delete from main table (if they're marked archived and old enough)
  DELETE FROM import_logs
  WHERE archived_at IS NOT NULL
  AND archived_at < NOW() - (v_retention_days || ' days')::INTERVAL
  AND is_archived = TRUE;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_deleted_count := v_deleted_count + v_n;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count,
    'retention_days', v_retention_days,
    'deleted_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."delete_old_import_logs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deny_campaign_edit_permission"("p_request_id" integer, "p_response_reason" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_can_approve BOOLEAN;
BEGIN
  -- Check if user can approve/deny
  SELECT is_admin() OR is_lead_organiser_for_campaign(
    (SELECT campaign_id FROM campaign_permission_requests WHERE request_id = p_request_id)
  )
  INTO v_can_approve;

  IF NOT v_can_approve THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'You do not have permission to process this request'
    );
  END IF;

  -- Update the request
  UPDATE campaign_permission_requests
  SET status = 'denied',
      reviewed_by = auth.uid(),
      reviewed_at = NOW(),
      response_reason = p_response_reason
  WHERE request_id = p_request_id AND status = 'pending';

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."deny_campaign_edit_permission"("p_request_id" integer, "p_response_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_au_mobile_e164"("p_raw" "text") RETURNS character varying
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
  SELECT CASE
    WHEN d ~ '^04\d{8}$' THEN '+61' || substr(d, 2)
    WHEN d ~ '^614\d{8}$' THEN '+' || d
    WHEN d ~ '^4\d{8}$' THEN '+61' || d
    WHEN d ~ '^6104\d{8}$' THEN '+61' || substr(d, 4)
    ELSE NULL
  END
  FROM (SELECT regexp_replace(COALESCE(p_raw, ''), '\D', '', 'g') AS d) x;
$_$;


ALTER FUNCTION "public"."derive_au_mobile_e164"("p_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_stage_overlap_with_hard_gates"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  cid    INT;
  stage_n INT;
  prev_row RECORD;
  next_row RECORD;
  gate_row RECORD;
BEGIN
  cid     := NEW.campaign_id;
  stage_n := NEW.stage_number;

  -- Standalone bucket has no sequential gate neighbours.
  IF stage_n = 0 THEN
    RETURN NEW;
  END IF;

  IF NEW.planned_start_date IS NULL OR NEW.planned_end_date IS NULL THEN
    RETURN NEW;
  END IF;

  IF stage_n > 1 AND stage_n <> 7 THEN
    SELECT planned_start_date, planned_end_date
      INTO prev_row
      FROM campaign_stage_plans
     WHERE campaign_id = cid AND stage_number = stage_n - 1;

    IF FOUND
       AND prev_row.planned_start_date IS NOT NULL
       AND prev_row.planned_end_date IS NOT NULL THEN

      SELECT enforcement_type, is_active
        INTO gate_row
        FROM gate_definitions
       WHERE campaign_id = cid AND gate_number = stage_n - 1;

      IF FOUND
         AND gate_row.enforcement_type = 'hard'
         AND gate_row.is_active = TRUE
         AND NEW.planned_start_date < prev_row.planned_end_date THEN
        RAISE EXCEPTION
          'Stage % cannot start (%) before stage % ends (%) — gate % is configured as a hard active gate (campaign %).',
          stage_n,
          NEW.planned_start_date,
          stage_n - 1,
          prev_row.planned_end_date,
          stage_n - 1,
          cid
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  IF stage_n < 11 AND stage_n <> 6 THEN
    SELECT planned_start_date, planned_end_date
      INTO next_row
      FROM campaign_stage_plans
     WHERE campaign_id = cid AND stage_number = stage_n + 1;

    IF FOUND
       AND next_row.planned_start_date IS NOT NULL
       AND next_row.planned_end_date IS NOT NULL THEN

      SELECT enforcement_type, is_active
        INTO gate_row
        FROM gate_definitions
       WHERE campaign_id = cid AND gate_number = stage_n;

      IF FOUND
         AND gate_row.enforcement_type = 'hard'
         AND gate_row.is_active = TRUE
         AND next_row.planned_start_date < NEW.planned_end_date THEN
        RAISE EXCEPTION
          'Stage % cannot end (%) after stage % starts (%) — gate % is configured as a hard active gate (campaign %).',
          stage_n,
          NEW.planned_end_date,
          stage_n + 1,
          next_row.planned_start_date,
          stage_n,
          cid
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_stage_overlap_with_hard_gates"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_stage_overlap_with_hard_gates"() IS 'B2W Phase 1 (replaces Phase-6 version): prevents overlap between adjoining stages when the gate between them is hard + active. Phase-boundary stages (6 and 7) are exempt from cross-phase checking — only within-phase adjacency is enforced.';



CREATE OR REPLACE FUNCTION "public"."enforce_stage_phase_invariant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.stage_number = 0 THEN
    IF NEW.phase IS DISTINCT FROM 'standalone_activities' THEN
      RAISE EXCEPTION
        'campaign_stage_plans invariant violated: stage_number 0 must have phase = standalone_activities, got %.',
        NEW.phase
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.phase := 'standalone_activities';
    RETURN NEW;
  END IF;

  IF NEW.stage_number BETWEEN 1 AND 6 THEN
    IF NEW.phase <> 'preparing_to_bargain' THEN
      RAISE EXCEPTION
        'campaign_stage_plans invariant violated: stage_number % (1–6) must have phase = preparing_to_bargain, got %.',
        NEW.stage_number, NEW.phase
        USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.stage_number BETWEEN 7 AND 11 THEN
    IF NEW.phase <> 'bargaining_to_win' THEN
      RAISE EXCEPTION
        'campaign_stage_plans invariant violated: stage_number % (7–11) must have phase = bargaining_to_win, got %.',
        NEW.stage_number, NEW.phase
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.stage_number BETWEEN 1 AND 6 THEN
    NEW.phase := 'preparing_to_bargain';
  ELSIF NEW.stage_number BETWEEN 7 AND 11 THEN
    NEW.phase := 'bargaining_to_win';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_stage_phase_invariant"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_stage_phase_invariant"() IS 'Ensures campaign_stage_plans.phase matches stage_number. Stage 0 = standalone_activities; 1–6 = preparing_to_bargain; 7–11 = bargaining_to_win.';



