CREATE OR REPLACE FUNCTION "public"."fn_auto_rate_promote_task_list_leader"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_existing_role INT;
  v_activist_id   INT;
  v_delegate_id   INT;
BEGIN
  IF NEW.status IS DISTINCT FROM 'active' OR NEW.leader_worker_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT role_type_id INTO v_activist_id
    FROM member_role_types WHERE role_name ILIKE 'activist' LIMIT 1;
  SELECT role_type_id INTO v_delegate_id
    FROM member_role_types WHERE role_name ILIKE 'delegate' LIMIT 1;

  IF NEW.activity_id IS NOT NULL THEN
    INSERT INTO campaign_activity_ratings
      (activity_id, worker_id, rating, rating_phase, event_id,
       source, notes, rated_at)
    VALUES
      (NEW.activity_id, NEW.leader_worker_id, 1, 'expected', NULL,
       'task_take', 'Auto-set from task list leader assignment', now())
    ON CONFLICT ON CONSTRAINT car_worker_phase_event_uq DO NOTHING;
  END IF;

  IF v_activist_id IS NOT NULL THEN
    SELECT member_role_type_id INTO v_existing_role
      FROM workers WHERE worker_id = NEW.leader_worker_id;

    IF v_existing_role IS NULL
       OR (v_existing_role <> v_activist_id
           AND (v_delegate_id IS NULL OR v_existing_role <> v_delegate_id)) THEN
      UPDATE workers
         SET member_role_type_id = v_activist_id,
             updated_at = now()
       WHERE worker_id = NEW.leader_worker_id;
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_rate_promote_task_list_leader"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_rate_workplan_task_worker"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_scope VARCHAR(20);
  v_activity_id INT;
BEGIN
  IF NEW.assigned_worker_id IS NULL OR NEW.plan_ambition_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ambition_scope INTO v_scope
  FROM plan_ambitions
  WHERE ambition_id = NEW.plan_ambition_id;

  IF v_scope IS DISTINCT FROM 'worker_assessable' THEN
    RETURN NEW;
  END IF;

  SELECT aa.activity_id INTO v_activity_id
  FROM activity_ambitions aa
  WHERE aa.plan_ambition_id = NEW.plan_ambition_id
  ORDER BY aa.is_primary DESC, aa.id ASC
  LIMIT 1;

  IF v_activity_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM record_assessment_event(
    p_activity_id := v_activity_id,
    p_worker_id := NEW.assigned_worker_id,
    p_rating := 1,
    p_binary_value := NULL,
    p_rating_phase := 'actual',
    p_event_id := NULL,
    p_source := 'task_take',
    p_notes := NULL,
    p_actor_id := NULL
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


