COMMENT ON FUNCTION "public"."fn_csa_sync_bargaining_phase_state"() IS 'BEFORE INSERT OR UPDATE trigger on campaign_situation_analyses. When employer_interaction_state is set and bargaining_phase_state IS NULL, auto-fills bargaining_phase_state from employer_state_bargaining_phase_map. Does not overwrite an explicitly supplied bargaining_phase_state.';



CREATE OR REPLACE FUNCTION "public"."fn_email_cta_to_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_rating INT;
  v_binary VARCHAR;
BEGIN
  IF NEW.activity_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.email_event NOT IN ('clicked', 'replied', 'form_submitted') THEN
    RETURN NEW;
  END IF;

  v_rating := NEW.maps_to_rating;
  v_binary := NEW.maps_to_binary;

  IF v_rating IS NULL AND v_binary IS NULL AND NEW.cta_response IS NOT NULL THEN
    v_binary := NEW.cta_response;
  END IF;

  IF v_rating IS NULL AND v_binary IS NULL THEN
    v_rating := 2;
  END IF;

  PERFORM record_assessment_event(
    p_activity_id := NEW.activity_id,
    p_worker_id := NEW.worker_id,
    p_rating := v_rating,
    p_binary_value := v_binary,
    p_rating_phase := 'actual',
    p_event_id := NULL,
    p_source := 'email',
    p_notes := NEW.notes,
    p_actor_id := NEW.created_by
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


