  v_source := CASE
    WHEN NEW.rating_origin = 'inbound_keyword' THEN 'sms_inbound'
    ELSE 'sms_survey'
  END;

  PERFORM record_assessment_event(
    p_activity_id := NEW.activity_id,
    p_worker_id := NEW.worker_id,
    p_rating := v_rating,
    p_binary_value := v_binary,
    p_rating_phase := 'actual',
    p_event_id := NULL,
    p_source := v_source,
    p_notes := NEW.notes,
    p_actor_id := NEW.created_by
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sms_to_rating"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_task_list_item_side_effects"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign_id INT;
  v_leader_id   INT;
BEGIN
  IF NEW.worker_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT campaign_id, leader_worker_id
    INTO v_campaign_id, v_leader_id
  FROM campaign_task_lists
  WHERE task_list_id = NEW.task_list_id;

  IF v_campaign_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO campaign_worker_membership (campaign_id, worker_id)
  VALUES (v_campaign_id, NEW.worker_id)
  ON CONFLICT (campaign_id, worker_id) DO NOTHING;

  IF v_leader_id IS NOT NULL AND v_leader_id <> NEW.worker_id THEN
    INSERT INTO campaign_leader_worker_links
      (campaign_id, leader_worker_id, follower_worker_id, notes)
    VALUES
      (v_campaign_id, v_leader_id, NEW.worker_id, 'Auto-linked via task list')
    ON CONFLICT ON CONSTRAINT uniq_campaign_leader_follower DO NOTHING;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


