CREATE OR REPLACE FUNCTION "public"."fn_worker_campaign_fact_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    INSERT INTO worker_campaign_fact_history (
      fact_id, campaign_id, worker_id, field_id,
      value_bool, value_int, value_text, value_enum, value_json,
      collected_at, source, source_ref, notes, recorded_by, replaced_at
    ) VALUES (
      OLD.fact_id, OLD.campaign_id, OLD.worker_id, OLD.field_id,
      OLD.value_bool, OLD.value_int, OLD.value_text, OLD.value_enum, OLD.value_json,
      OLD.collected_at, OLD.source, OLD.source_ref, OLD.notes, OLD.recorded_by, now()
    );
    RETURN NEW;
  END IF;
  INSERT INTO worker_campaign_fact_history (
    fact_id, campaign_id, worker_id, field_id,
    value_bool, value_int, value_text, value_enum, value_json,
    collected_at, source, source_ref, notes, recorded_by, replaced_at
  ) VALUES (
    OLD.fact_id, OLD.campaign_id, OLD.worker_id, OLD.field_id,
    OLD.value_bool, OLD.value_int, OLD.value_text, OLD.value_enum, OLD.value_json,
    OLD.collected_at, OLD.source, OLD.source_ref, OLD.notes, OLD.recorded_by, now()
  );
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."fn_worker_campaign_fact_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."force_release_claims_for_token"("p_token_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_released_count INTEGER := 0;
BEGIN
  IF p_token_id IS NULL THEN
    RETURN jsonb_build_object('released_count', 0);
  END IF;

  WITH released AS (
    UPDATE call_list_items
    SET
      status = 'pending',
      claimed_at = NULL,
      claimed_by_session_label = NULL,
      claimed_by_worker_id = NULL,
      claimed_by_share_token_id = NULL,
      updated_at = now()
    WHERE status = 'in_progress'
      AND claimed_by_share_token_id = p_token_id
    RETURNING item_id
  )
  SELECT COUNT(*) INTO v_released_count FROM released;

  RETURN jsonb_build_object('released_count', v_released_count);
END;
$$;


ALTER FUNCTION "public"."force_release_claims_for_token"("p_token_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_ai_cache_key"("p_prompt" "text", "p_model_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_prompt_hash TEXT;
BEGIN
  v_prompt_hash := encode(digest(p_prompt || p_model_name, 'sha256'), 'hex');
  return 'ai:' || p_model_name || ':' || v_prompt_hash;
END;
$$;


ALTER FUNCTION "public"."generate_ai_cache_key"("p_prompt" "text", "p_model_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ai_cache_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_stats JSONB;
BEGIN
  SELECT jsonb_build_object(
    'total_entries', COUNT(*),
    'active_entries', COUNT(*) FILTER (WHERE is_active = true),
    'expired_entries', COUNT(*) FILTER (WHERE is_active = true AND expires_at < NOW()),
    'total_tokens', SUM(tokens_used),
    'total_cost', SUM(cost_usd),
    'avg_access_count', AVG(access_count),
    'cache_hits', (SELECT COUNT(*) FROM ai_cache_audit_log WHERE operation = 'hit'),
    'cache_misses', (SELECT COUNT(*) FROM ai_cache_audit_log WHERE operation = 'miss')
  ) INTO v_stats
  FROM ai_response_cache;
  RETURN v_stats;
END;
$$;


ALTER FUNCTION "public"."get_ai_cache_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cached_ai_response"("p_prompt" "text", "p_model_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_cache_key TEXT;
  v_cached_response ai_response_cache%ROWTYPE;
BEGIN
  v_cache_key := generate_ai_cache_key(p_prompt, p_model_name);
  SELECT * INTO v_cached_response
  FROM ai_response_cache
  WHERE cache_key = v_cache_key
    AND is_active = true
    AND (expires_at IS NULL OR expires_at > NOW());
  IF FOUND THEN
    UPDATE ai_response_cache
    SET last_accessed_at = NOW(),
        access_count = access_count + 1
    WHERE cache_id = v_cached_response.cache_id;
    INSERT INTO ai_cache_audit_log (cache_id, operation, metadata)
    VALUES (v_cached_response.cache_id, 'hit', '{"model_name": "' || p_model_name || '"}');
    RETURN v_cached_response.response;
  END IF;
  INSERT INTO ai_cache_audit_log (cache_id, operation, metadata)
  VALUES (NULL, 'miss', '{"prompt_length": ' || length(p_prompt) || ', "model_name": "' || p_model_name || '"}');
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."get_cached_ai_response"("p_prompt" "text", "p_model_name" "text") OWNER TO "postgres";


