  v_row vw_campaign_worker_call_status%ROWTYPE;
BEGIN
  SELECT *
  INTO v_row
  FROM vw_campaign_worker_call_status
  WHERE campaign_id = p_campaign_id
    AND worker_id = p_worker_id
