CREATE OR REPLACE FUNCTION "public"."get_import_log_retention_status"() RETURNS TABLE("metric_name" "text", "metric_value" bigint, "metric_details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  -- Count active logs (not archived)
  SELECT
    'active_logs'::TEXT,
    COUNT(*)::BIGINT,
    jsonb_build_object('description', 'Import logs not yet archived')
  FROM import_logs
  WHERE is_archived = FALSE AND archived_at IS NULL AND deleted_at IS NULL

  UNION ALL

  -- Count archived logs
  SELECT
    'archived_logs'::TEXT,
    COUNT(*)::BIGINT,
    jsonb_build_object('description', 'Import logs in cold storage')
  FROM import_logs
  WHERE is_archived = TRUE AND deleted_at IS NULL

  UNION ALL

  -- Count archive table size
  SELECT
    'archive_table_count'::TEXT,
    COUNT(*)::BIGINT,
    jsonb_build_object('description', 'Total records in archive table')
  FROM import_logs_archive

  UNION ALL

  -- Logs ready for archival (>90 days, not yet archived)
  SELECT
    'pending_archival'::TEXT,
    COUNT(*)::BIGINT,
    jsonb_build_object(
      'description', 'Logs older than 90 days pending archival',
      'threshold', '90 days'
    )
  FROM import_logs
  WHERE imported_at < NOW() - '90 days'::INTERVAL
  AND is_archived = FALSE AND archived_at IS NULL AND deleted_at IS NULL

  UNION ALL

  -- Logs ready for deletion (>1 year, already archived)
  SELECT
    'pending_deletion'::TEXT,
    COUNT(*)::BIGINT,
    jsonb_build_object(
      'description', 'Archived logs older than 1 year pending deletion',
      'threshold', '1 year'
    )
  FROM import_logs
  WHERE archived_at IS NOT NULL
  AND archived_at < NOW() - '1 year'::INTERVAL
  AND deleted_at IS NULL;
END;
$$;


ALTER FUNCTION "public"."get_import_log_retention_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_campaign_permissions"() RETURNS TABLE("campaign_id" integer, "campaign_name" "text", "access_type" "text", "granted_by_name" "text", "granted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.campaign_id,
    c.name AS campaign_name,
    'permission' AS access_type,
    COALESCE(org.organiser_name, up.display_name, 'System') AS granted_by_name,
    cep.granted_at
  FROM campaign_edit_permissions cep
  JOIN campaigns c ON c.campaign_id = cep.campaign_id
  LEFT JOIN user_profiles up ON up.user_id = cep.granted_by
  LEFT JOIN organisers org ON org.organiser_id = up.organiser_id
  WHERE cep.granted_to = auth.uid()
  AND cep.status = 'active'

  UNION ALL

  -- Campaigns user created
  SELECT
    c.campaign_id,
    c.name,
    'creator' AS access_type,
    'You' AS granted_by_name,
    c.created_at::TIMESTAMPTZ
  FROM campaigns c
  WHERE c.created_by = auth.uid()

  UNION ALL

  -- Campaigns user is assigned to via agreement_organisers
  SELECT DISTINCT
    ct.campaign_id,
    c.name,
    'assigned' AS access_type,
    'Agreement Assignment' AS granted_by_name,
    NOW() AS granted_at
  FROM organisers o
  JOIN user_profiles up ON up.organiser_id = o.organiser_id
  JOIN agreement_organisers ao ON ao.organiser_id = o.organiser_id
  JOIN campaign_timelines ct ON ct.agreement_id = ao.agreement_id
  JOIN campaigns c ON c.campaign_id = ct.campaign_id
  WHERE up.user_id = auth.uid()

  ORDER BY granted_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_my_campaign_permissions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_p2w_completion_by_plan_ids"("p_plan_ids" integer[]) RETURNS TABLE("plan_id" integer, "ambitions" boolean, "where_to_play" boolean, "theory" boolean, "capacities" boolean, "management" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH requested_plan_ids AS (
    SELECT DISTINCT unnest(COALESCE(p_plan_ids, ARRAY[]::integer[])) AS plan_id
  )
  SELECT
    r.plan_id,
    EXISTS (
      SELECT 1
      FROM plan_ambitions pa
      WHERE pa.plan_id = r.plan_id
    ) AS ambitions,
    EXISTS (
      SELECT 1
      FROM plan_where_to_play pwtp
      WHERE pwtp.plan_id = r.plan_id
    ) AS where_to_play,
    EXISTS (
      SELECT 1
      FROM plan_theory_of_winning ptow
      WHERE ptow.plan_id = r.plan_id
    ) AS theory,
    EXISTS (
      SELECT 1
      FROM plan_capacities pc
      WHERE pc.plan_id = r.plan_id
    ) AS capacities,
    EXISTS (
      SELECT 1
      FROM plan_management_systems pms
      WHERE pms.plan_id = r.plan_id
    ) AS management
  FROM requested_plan_ids r
  ORDER BY r.plan_id;
$$;


ALTER FUNCTION "public"."get_p2w_completion_by_plan_ids"("p_plan_ids" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_permission_requests"() RETURNS TABLE("request_id" integer, "campaign_id" integer, "campaign_name" "text", "requested_by_name" "text", "requested_by_email" "text", "reason" "text", "requested_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pr.request_id,
    pr.campaign_id,
    c.name AS campaign_name,
    COALESCE(org.organiser_name, up.display_name, 'Unknown') AS requested_by_name,
    COALESCE(org.email, au.email) AS requested_by_email,
    pr.reason,
    pr.requested_at
  FROM campaign_permission_requests pr
  JOIN campaigns c ON c.campaign_id = pr.campaign_id
  LEFT JOIN user_profiles up ON up.user_id = pr.requested_by
  LEFT JOIN organisers org ON org.organiser_id = up.organiser_id
  LEFT JOIN auth.users au ON au.id = pr.requested_by
  WHERE pr.status = 'pending'
  AND (
    -- User is admin
    is_admin()
    OR
    -- User is a lead/coordinator for this campaign
    is_lead_organiser_for_campaign(pr.campaign_id)
  )
  ORDER BY pr.requested_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_pending_permission_requests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_rate_limit_stats"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_config RECORD;
  v_minute_count INTEGER;
  v_hour_count INTEGER;
  v_day_count INTEGER;
  v_total_cost DECIMAL(10, 4);
BEGIN
  SELECT * INTO v_config
  FROM rate_limit_config
  WHERE user_id = p_user_id;

  SELECT COUNT(*) INTO v_minute_count
  FROM rate_limit_usage
  WHERE user_id = p_user_id
    AND requested_at > NOW() - INTERVAL '1 minute';

  SELECT COUNT(*) INTO v_hour_count
  FROM rate_limit_usage
  WHERE user_id = p_user_id
    AND requested_at > NOW() - INTERVAL '1 hour';

  SELECT COUNT(*) INTO v_day_count
  FROM rate_limit_usage
  WHERE user_id = p_user_id
    AND requested_at > NOW() - INTERVAL '1 day';

  SELECT COALESCE(SUM(estimated_cost), 0) INTO v_total_cost
  FROM rate_limit_usage
  WHERE user_id = p_user_id
    AND requested_at > NOW() - INTERVAL '30 days';

  RETURN jsonb_build_object(
    'config', CASE
      WHEN v_config.user_id IS NOT NULL THEN jsonb_build_object(
        'requests_per_minute', v_config.requests_per_minute,
        'requests_per_hour', v_config.requests_per_hour,
        'requests_per_day', v_config.requests_per_day,
        'is_exempt', v_config.is_exempt,
        'cost_per_request', v_config.cost_per_request
      )
      ELSE NULL
    END,
    'usage', jsonb_build_object(
      'requests_last_minute', v_minute_count,
      'requests_last_hour', v_hour_count,
      'requests_last_day', v_day_count
    ),
    'total_cost_30days', v_total_cost
  );
END;
$$;


ALTER FUNCTION "public"."get_user_rate_limit_stats"("p_user_id" "uuid") OWNER TO "postgres";


