CREATE OR REPLACE FUNCTION "public"."get_workload_dashboard_data"("p_filter_organiser" "uuid" DEFAULT NULL::"uuid", "p_filter_status" character varying DEFAULT NULL::character varying, "p_filter_days" integer DEFAULT NULL::integer) RETURNS TABLE("campaign_id" integer, "campaign_name" character varying, "campaign_status" character varying, "campaign_type" character varying, "created_by" "uuid", "current_stage_number" integer, "current_stage_name" character varying, "stage_display_status" "text", "is_overdue" boolean, "is_due_soon" boolean, "overall_progress_percentage" numeric, "total_criteria" integer, "met_criteria" integer, "pending_assessments" integer, "worksite_count" integer, "employer_count" integer, "worker_count" integer, "leader_count" integer, "total_activities_underway" integer, "in_progress_actions" integer, "pending_gate_assessments" integer, "active_stage_plans" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        wds.campaign_id,
        wds.campaign_name,
        wds.campaign_status,
        wds.campaign_type,
        wds.created_by,
        wds.current_stage_number,
        wds.current_stage_name,
        wds.stage_display_status,
        wds.is_overdue,
        wds.is_due_soon,
        wds.overall_progress_percentage,
        wds.total_criteria::integer,
        wds.met_criteria::integer,
        wds.pending_assessments::integer,
        wds.worksite_count::integer,
        wds.employer_count::integer,
        wds.worker_count::integer,
        wds.leader_count::integer,
        wds.total_activities_underway::integer,
        wds.in_progress_actions::integer,
        wds.pending_gate_assessments::integer,
        wds.active_stage_plans::integer
    FROM workload_dashboard_summary wds
    WHERE
        (p_filter_organiser IS NULL OR wds.created_by = p_filter_organiser)
        AND (p_filter_status IS NULL OR wds.campaign_status = p_filter_status)
        AND (p_filter_days IS NULL OR wds.created_at >= CURRENT_DATE - (p_filter_days || ' days')::INTERVAL)
    ORDER BY
        wds.is_overdue DESC,
        wds.is_due_soon DESC,
        wds.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_workload_dashboard_data"("p_filter_organiser" "uuid", "p_filter_status" character varying, "p_filter_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_campaign_edit_permission"("p_request_id" integer, "p_response_reason" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_request RECORD;
  v_permission_id INTEGER;
  v_can_approve BOOLEAN;
BEGIN
  -- Get the request
  SELECT * INTO v_request
  FROM campaign_permission_requests
  WHERE request_id = p_request_id AND status = 'pending';

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Request not found or already processed'
    );
  END IF;

  -- Check if user can approve (admin, coordinator, or campaign owner's lead)
  SELECT is_admin() OR is_lead_organiser_for_campaign(v_request.campaign_id)
  INTO v_can_approve;

  IF NOT v_can_approve THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'You do not have permission to approve this request'
    );
  END IF;

  -- Create the permission
  INSERT INTO campaign_edit_permissions (
    campaign_id, granted_by, granted_to, reason
  )
  VALUES (
    v_request.campaign_id, auth.uid(), v_request.requested_by, v_request.reason
  )
  RETURNING permission_id INTO v_permission_id;

  -- Update the request
  UPDATE campaign_permission_requests
  SET status = 'approved',
      reviewed_by = auth.uid(),
      reviewed_at = NOW(),
      response_reason = p_response_reason,
      approved_permission_id = v_permission_id
  WHERE request_id = p_request_id;

  RETURN jsonb_build_object(
    'success', true,
    'permission_id', v_permission_id,
    'campaign_id', v_request.campaign_id
  );
END;
$$;


ALTER FUNCTION "public"."grant_campaign_edit_permission"("p_request_id" integer, "p_response_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.user_profiles (user_id, role, display_name)
  VALUES (
    NEW.id,
    'viewer',
    COALESCE(NEW.raw_user_meta_data->>'display_name', split_part(NEW.email, '@', 1))
  )
  ON CONFLICT (user_id) DO NOTHING;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Log the error but don't block the auth signup
  RAISE WARNING 'handle_new_user failed for %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_campaign_edit_permission"("p_campaign_id" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM campaign_edit_permissions
    WHERE campaign_id = p_campaign_id
    AND granted_to = auth.uid()
    AND status = 'active'
  );
$$;


ALTER FUNCTION "public"."has_campaign_edit_permission"("p_campaign_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_email_click_count"("p_send_id" bigint, "p_occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE email_send_log
  SET click_count = click_count + 1,
      first_click_at = COALESCE(first_click_at, p_occurred_at)
  WHERE send_id = p_send_id;
$$;


