CREATE OR REPLACE FUNCTION "public"."invalidate_ai_cache"("p_cache_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_cache_id BIGINT;
BEGIN
  UPDATE ai_response_cache
  SET is_active = false
  WHERE cache_key = p_cache_key
  RETURNING cache_id INTO v_cache_id;
  IF FOUND THEN
    INSERT INTO ai_cache_audit_log (cache_id, operation)
    VALUES (v_cache_id, 'invalidate');
    RETURN true;
  END IF;
  RETURN false;
END;
$$;


ALTER FUNCTION "public"."invalidate_ai_cache"("p_cache_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_profiles
    WHERE user_id = auth.uid() AND role = 'admin'
  );
$$;


ALTER FUNCTION "public"."is_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_assigned_to_campaign"("p_campaign_id" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  -- Original: agreement-level assignment via campaign_timelines
  SELECT EXISTS (
    SELECT 1 FROM user_profiles up
    JOIN organisers o ON o.organiser_id = up.organiser_id
    JOIN agreement_organisers ao ON ao.organiser_id = o.organiser_id
    JOIN campaign_timelines ct ON ct.agreement_id = ao.agreement_id
    WHERE ct.campaign_id = p_campaign_id
    AND up.user_id = auth.uid()
  )
  OR
  -- New: direct campaign-level team membership (any campaign_role)
  EXISTS (
    SELECT 1 FROM campaign_organisers co
    JOIN organisers o ON o.organiser_id = co.organiser_id
    JOIN user_profiles up ON up.organiser_id = o.organiser_id
    WHERE co.campaign_id = p_campaign_id
    AND up.user_id = auth.uid()
  );
$$;


ALTER FUNCTION "public"."is_assigned_to_campaign"("p_campaign_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_campaign_creator"("p_campaign_id" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM campaigns c
    WHERE c.campaign_id = p_campaign_id
    AND c.created_by = auth.uid()
  );
$$;


ALTER FUNCTION "public"."is_campaign_creator"("p_campaign_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_coordinator_or_lead"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_profiles
    WHERE user_id = auth.uid()
    AND (
      role = 'admin'
      OR work_role = 'lead_organiser'
      OR work_role = 'coordinator'
      OR work_role = 'industrial_coordinator'
    )
  );
$$;


ALTER FUNCTION "public"."is_coordinator_or_lead"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_lead_organiser_for_campaign"("p_campaign_id" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  -- Arm 1: primary lead via campaigns.organiser_id (user's organiser matches campaign lead)
  SELECT EXISTS (
    SELECT 1 FROM user_profiles up
    JOIN organisers o ON o.organiser_id = up.organiser_id
    JOIN campaigns c ON c.organiser_id = o.organiser_id
    WHERE c.campaign_id = p_campaign_id
    AND up.user_id = auth.uid()
    AND up.work_role IN ('lead_organiser', 'coordinator', 'industrial_coordinator')
  )
  OR
  -- Arm 2: campaign-level team entry with 'lead' role
  EXISTS (
    SELECT 1 FROM campaign_organisers co
    JOIN organisers o ON o.organiser_id = co.organiser_id
    JOIN user_profiles up ON up.organiser_id = o.organiser_id
    WHERE co.campaign_id = p_campaign_id
    AND co.campaign_role = 'lead'
    AND up.user_id = auth.uid()
  )
  OR
  -- Arm 3: user is a coordinator/lead whose organiser is named as the campaign-specific "reports to"
  --         for at least one member of the campaign team
  EXISTS (
    SELECT 1 FROM user_profiles up
    JOIN organisers o ON o.organiser_id = up.organiser_id
    JOIN campaign_organisers co ON co.reports_to_organiser_id = o.organiser_id
    WHERE co.campaign_id = p_campaign_id
    AND up.user_id = auth.uid()
    AND up.work_role IN ('lead_organiser', 'coordinator', 'industrial_coordinator')
  )
  OR
  -- Arm 4: legacy global reports_to chain — campaign's assigned organiser globally reports to this user
  EXISTS (
    SELECT 1 FROM user_profiles up
    JOIN campaigns c ON c.campaign_id = p_campaign_id
    JOIN organisers o ON o.organiser_id = c.organiser_id
    JOIN user_profiles organiser_profile ON organiser_profile.organiser_id = o.organiser_id
    WHERE up.user_id = auth.uid()
    AND organiser_profile.reports_to = up.user_id
    AND up.work_role IN ('lead_organiser', 'coordinator', 'industrial_coordinator')
  );
$$;


ALTER FUNCTION "public"."is_lead_organiser_for_campaign"("p_campaign_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_rate_limit_request"("p_user_id" "uuid", "p_endpoint" "text", "p_method" "text", "p_status_code" integer, "p_ip_address" "inet" DEFAULT NULL::"inet", "p_user_agent" "text" DEFAULT NULL::"text", "p_request_path" "text" DEFAULT NULL::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_usage_id BIGINT;
  v_config RECORD;
BEGIN
  SELECT * INTO v_config
  FROM rate_limit_config
  WHERE user_id = p_user_id;

  INSERT INTO rate_limit_usage (
    user_id,
    endpoint,
    method,
    status_code,
    ip_address,
    user_agent,
    request_path,
    estimated_cost
  ) VALUES (
    p_user_id,
    p_endpoint,
    p_method,
    p_status_code,
    p_ip_address,
    p_user_agent,
    p_request_path,
    COALESCE(v_config.cost_per_request, 0)
  )
  RETURNING usage_id INTO v_usage_id;

  RETURN v_usage_id;
END;
$$;


ALTER FUNCTION "public"."log_rate_limit_request"("p_user_id" "uuid", "p_endpoint" "text", "p_method" "text", "p_status_code" integer, "p_ip_address" "inet", "p_user_agent" "text", "p_request_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manually_archive_import_logs"("p_days_ago" integer DEFAULT 90) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_archived_count INTEGER;
BEGIN
  WITH logs_to_move AS (
    SELECT il.import_id,
      il.file_name,
      il.import_type,
      il.records_created,
      il.records_updated,
      il.errors,
      il.imported_by,
      il.imported_at,
      to_jsonb(il) AS data
    FROM import_logs il
    WHERE il.imported_at < NOW() - (p_days_ago || ' days')::INTERVAL
      AND il.is_archived = FALSE
      AND il.archived_at IS NULL
      AND il.deleted_at IS NULL
  ),
  ins AS (
    INSERT INTO import_logs_archive (
      import_id, file_name, import_type, records_created,
      records_updated, errors, imported_by, imported_at,
      data
    )
    SELECT import_id, file_name, import_type, records_created,
      records_updated, errors, imported_by, imported_at,
      data
    FROM logs_to_move
    RETURNING import_id
  )
  UPDATE import_logs il
  SET archived_at = NOW(),
      is_archived = TRUE
  FROM ins
  WHERE il.import_id = ins.import_id;

  GET DIAGNOSTICS v_archived_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'archived_count', v_archived_count,
    'days_ago', p_days_ago,
    'archived_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."manually_archive_import_logs"("p_days_ago" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_workers_for_import"("p_emails" "text"[] DEFAULT '{}'::"text"[], "p_phones" "text"[] DEFAULT '{}'::"text"[], "p_name_keys" "text"[] DEFAULT '{}'::"text"[], "p_last_names" "text"[] DEFAULT '{}'::"text"[]) RETURNS TABLE("worker_id" integer, "first_name" character varying, "last_name" character varying, "preferred_name" character varying, "email" character varying, "phone" character varying)
    LANGUAGE "sql" STABLE
    AS $$
  WITH name_norm AS (
    SELECT
      w.worker_id,
      regexp_replace(lower(btrim(w.first_name)), '\s+', ' ', 'g') || '||' ||
        regexp_replace(lower(btrim(w.last_name)), '\s+', ' ', 'g') AS name_key,
      CASE WHEN w.preferred_name IS NOT NULL AND btrim(w.preferred_name) <> '' THEN
        regexp_replace(lower(btrim(w.preferred_name)), '\s+', ' ', 'g') || '||' ||
          regexp_replace(lower(btrim(w.last_name)), '\s+', ' ', 'g')
      END AS preferred_key,
      regexp_replace(lower(btrim(w.last_name)), '\s+', ' ', 'g') AS last_key
    FROM workers w
  )
  SELECT DISTINCT w.worker_id, w.first_name, w.last_name, w.preferred_name, w.email, w.phone
  FROM workers w
  LEFT JOIN name_norm n ON n.worker_id = w.worker_id
  WHERE
    (cardinality(p_emails) > 0 AND lower(btrim(coalesce(w.email, ''))) = ANY (p_emails))
    OR (cardinality(p_phones) > 0 AND normalise_phone_au(w.phone) = ANY (p_phones))
    OR (cardinality(p_name_keys) > 0 AND (
      n.name_key = ANY (p_name_keys)
      OR n.preferred_key = ANY (p_name_keys)
    ))
  UNION
  -- Surname-only candidates, capped so common surnames can't flood the
  -- response. These are suggestions for user confirmation, never
  -- auto-matches.
  SELECT s.worker_id, s.first_name, s.last_name, s.preferred_name, s.email, s.phone
  FROM (
    SELECT w.worker_id, w.first_name, w.last_name, w.preferred_name, w.email, w.phone
    FROM workers w
    JOIN name_norm n ON n.worker_id = w.worker_id
    WHERE cardinality(p_last_names) > 0 AND n.last_key = ANY (p_last_names)
    LIMIT 500
  ) s;
$$;


ALTER FUNCTION "public"."match_workers_for_import"("p_emails" "text"[], "p_phones" "text"[], "p_name_keys" "text"[], "p_last_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materialise_sequence_run"("p_run_id" bigint) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_step       activity_sequence_steps%ROWTYPE;
  v_seq        activity_sequences%ROWTYPE;
  v_section    section_plans%ROWTYPE;
  v_source     campaign_activities%ROWTYPE;
  v_run        activity_sequence_runs%ROWTYPE;
  v_title      TEXT;
  v_new_id     INT;
  v_list_id    INT;
BEGIN
  SELECT * INTO v_run FROM activity_sequence_runs WHERE run_id = p_run_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'run % not found', p_run_id; END IF;
  IF v_run.state <> 'queued' THEN
    RAISE EXCEPTION 'run % not in queued state (state=%)', p_run_id, v_run.state;
  END IF;

  SELECT * INTO v_step FROM activity_sequence_steps WHERE step_id = v_run.step_id;
  SELECT * INTO v_seq  FROM activity_sequences      WHERE sequence_id = v_step.sequence_id;
  SELECT * INTO v_section FROM section_plans        WHERE section_plan_id = v_seq.section_plan_id;

  IF v_step.source_activity_id IS NOT NULL THEN
    SELECT * INTO v_source FROM campaign_activities WHERE activity_id = v_step.source_activity_id;
  END IF;

  v_title := COALESCE(
    v_step.target_payload ->> 'title',
    CASE
      WHEN v_source.title IS NOT NULL
      THEN v_source.title || ' — follow-up (' || v_step.target_activity_kind || ')'
      ELSE 'Sequence step (' || v_step.target_activity_kind || ')'
    END
  );

  INSERT INTO campaign_activities (
    campaign_id, section_plan_id, title, description,
    template_key, activity_kind, is_custom
  )
  VALUES (
    v_section.campaign_id, v_section.section_plan_id, v_title,
    COALESCE(v_step.target_payload ->> 'description', NULL),
    v_step.target_activity_template_key,
    v_step.target_activity_kind,
    TRUE
  )
  RETURNING activity_id INTO v_new_id;

  IF v_step.target_activity_kind = 'phone_call_list' THEN
    BEGIN
      v_list_id := create_call_list_from_activity(v_new_id);
    EXCEPTION WHEN OTHERS THEN
      UPDATE activity_sequence_runs
         SET notes = COALESCE(notes, '') || E'\nWarning: call_list creation failed: ' || SQLERRM
       WHERE run_id = p_run_id;
    END;
  END IF;

  UPDATE activity_sequence_runs
     SET state = 'materialised',
         materialised_activity_id = v_new_id,
         notes = COALESCE(notes, '') || 'Materialised at ' || now()::TEXT
           || CASE WHEN v_list_id IS NOT NULL
                   THEN ' (call_list_id=' || v_list_id || ')'
                   ELSE '' END
   WHERE run_id = p_run_id;

  RETURN v_new_id;
EXCEPTION WHEN OTHERS THEN
  UPDATE activity_sequence_runs
     SET state = 'failed', notes = COALESCE(notes, '') || E'\nError: ' || SQLERRM
   WHERE run_id = p_run_id;
  RAISE;
END;
$$;


ALTER FUNCTION "public"."materialise_sequence_run"("p_run_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_employers"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_survivor_id         INT;
  v_victim_ids          INT[];
  v_canonical           TEXT;
  v_extra_aliases       TEXT[];
  v_alias_names         TEXT[];
  v_expected_ts         TIMESTAMPTZ;
  v_admin_user_id       UUID;
  v_actual_ts           TIMESTAMPTZ;
  v_cur                 INT;
  v_victim_count        INT;
  v_workers_updated     INT := 0;
  v_agreements_updated  INT := 0;
  v_aliases_inserted    INT := 0;
  v_warnings            JSONB := '[]'::JSONB;
  v_name                TEXT;
  v_trading             TEXT;
  v_rec                 RECORD;
  v_merged_ids          INT[];
BEGIN
  v_survivor_id := (payload->>'survivor_employer_id')::INT;
  v_admin_user_id := NULLIF(payload->>'admin_user_id', '')::UUID;

  SELECT COALESCE(
    ARRAY(
      SELECT DISTINCT j::INT
      FROM jsonb_array_elements_text(COALESCE(payload->'victim_employer_ids', '[]'::JSONB)) AS e(j)
      WHERE j ~ '^\d+$'
      ORDER BY 1
    ),
    ARRAY[]::INT[]
  )
  INTO v_victim_ids;

  IF v_survivor_id IS NULL OR v_victim_ids IS NULL OR cardinality(v_victim_ids) < 1 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'invalid_input',
      'message', 'survivor_employer_id and at least one victim_employer_ids entry are required.'
    );
  END IF;

  IF v_survivor_id = ANY(v_victim_ids) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'invalid_input',
      'message', 'Survivor cannot be included in victim_employer_ids.'
    );
  END IF;

  SELECT COUNT(*) INTO v_victim_count FROM employers e WHERE e.employer_id = ANY(v_victim_ids);
  IF v_victim_count <> cardinality(v_victim_ids) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'not_found',
      'message', 'One or more victim employer IDs do not exist.'
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM employers WHERE employer_id = v_survivor_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'not_found',
      'message', 'Survivor employer does not exist.'
    );
  END IF;

  -- Ancestor guard: no victim may appear on the parent chain from survivor
  v_cur := (SELECT parent_employer_id FROM employers WHERE employer_id = v_survivor_id);
  WHILE v_cur IS NOT NULL LOOP
    IF v_cur = ANY(v_victim_ids) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'parent_child_conflict',
        'message', 'One of the employers being merged is an ancestor (parent/grandparent) of the chosen survivor via the parent company field. To resolve: open the survivor employer''s detail card and clear its Parent Company field (or choose a different survivor). The merge can then proceed.'
      );
    END IF;
    v_cur := (SELECT parent_employer_id FROM employers WHERE employer_id = v_cur);
  END LOOP;

  IF payload->>'expected_survivor_updated_at' IS NOT NULL THEN
    v_expected_ts := (payload->>'expected_survivor_updated_at')::TIMESTAMPTZ;
    SELECT updated_at INTO v_actual_ts FROM employers WHERE employer_id = v_survivor_id;
    IF v_actual_ts IS NOT NULL AND v_expected_ts IS NOT NULL AND v_actual_ts <> v_expected_ts THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'stale_data',
        'message', 'Survivor employer was modified since loaded. Refresh and try again.',
        'expected', v_expected_ts,
        'actual', v_actual_ts
      );
    END IF;
  END IF;

  v_merged_ids := ARRAY[v_survivor_id] || v_victim_ids;

  -- Canonical name
  IF payload ? 'canonical_employer_name' AND NULLIF(trim(payload->>'canonical_employer_name'), '') IS NOT NULL THEN
    v_canonical := trim(payload->>'canonical_employer_name');
  ELSE
    SELECT employer_name INTO v_canonical FROM employers WHERE employer_id = v_survivor_id;
  END IF;

  IF v_canonical IS NULL OR length(v_canonical) = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'invalid_input',
      'message', 'canonical_employer_name is empty.'
    );
  END IF;

  -- Alias list: explicit from UI, or build from merged rows + extra_aliases
  IF jsonb_typeof(payload->'alias_names') = 'array'
     AND jsonb_array_length(COALESCE(payload->'alias_names', '[]'::JSONB)) > 0 THEN
    SELECT COALESCE(
      ARRAY(
        SELECT trim(both FROM e.elem)
        FROM jsonb_array_elements_text(payload->'alias_names') AS e(elem)
        WHERE length(trim(both FROM e.elem)) > 0
      ),
      ARRAY[]::TEXT[]
    )
    INTO v_alias_names;
  ELSE
    v_alias_names := ARRAY[]::TEXT[];
    FOR v_rec IN
      SELECT employer_id, employer_name, trading_name
      FROM employers
      WHERE employer_id = ANY(v_merged_ids)
      ORDER BY CASE WHEN employer_id = v_survivor_id THEN 0 ELSE 1 END, employer_id
    LOOP
      IF lower(trim(v_rec.employer_name)) <> lower(trim(v_canonical)) THEN
        v_alias_names := array_append(v_alias_names, trim(v_rec.employer_name));
      END IF;
      IF v_rec.trading_name IS NOT NULL AND length(trim(v_rec.trading_name)) > 0 THEN
        v_alias_names := array_append(v_alias_names, trim(v_rec.trading_name));
      END IF;
    END LOOP;
    IF jsonb_typeof(payload->'extra_aliases') = 'array' THEN
      FOR v_name IN
        SELECT trim(both FROM ex.elem)
        FROM jsonb_array_elements_text(payload->'extra_aliases') AS ex(elem)
      LOOP
        IF length(v_name) > 0 THEN
          v_alias_names := array_append(v_alias_names, v_name);
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- Repoint survivor.parent if it points at a victim
  UPDATE employers s
  SET parent_employer_id = p.parent_employer_id,
      updated_at = now()
  FROM employers p
  WHERE s.employer_id = v_survivor_id
    AND s.parent_employer_id = p.employer_id
    AND p.employer_id = ANY(v_victim_ids);

  -- Other employers that pointed at victims now point at survivor
  UPDATE employers
  SET parent_employer_id = v_survivor_id,
      updated_at = now()
  WHERE parent_employer_id = ANY(v_victim_ids)
    AND employer_id <> v_survivor_id;

  UPDATE worksites
  SET operator_id = v_survivor_id,
      updated_at = now()
  WHERE operator_id = ANY(v_victim_ids);

  UPDATE worksites
  SET principal_employer_id = v_survivor_id,
      updated_at = now()
  WHERE principal_employer_id = ANY(v_victim_ids);

  UPDATE agreements
  SET employer_id = v_survivor_id,
      updated_at = now()
  WHERE employer_id = ANY(v_victim_ids);
  GET DIAGNOSTICS v_agreements_updated = ROW_COUNT;

  UPDATE workers
  SET employer_id = v_survivor_id,
      updated_at = now()
  WHERE employer_id = ANY(v_victim_ids);
  GET DIAGNOSTICS v_workers_updated = ROW_COUNT;

  UPDATE documents
  SET employer_id = v_survivor_id
  WHERE employer_id = ANY(v_victim_ids);

  UPDATE worksite_scopes
  SET employer_id = v_survivor_id
  WHERE employer_id = ANY(v_victim_ids);

  UPDATE employer_scopes
  SET employer_id = v_survivor_id
  WHERE employer_id = ANY(v_victim_ids);

  UPDATE agreement_employers
  SET employer_id = v_survivor_id
  WHERE employer_id = ANY(v_victim_ids);

  -- Delete victim worksite_roles that would conflict with an existing survivor row
  -- on UNIQUE (employer_id, worksite_id, role_type) before repointing.
  DELETE FROM employer_worksite_roles ewr
  WHERE ewr.employer_id = ANY(v_victim_ids)
    AND EXISTS (
      SELECT 1 FROM employer_worksite_roles s
      WHERE s.employer_id = v_survivor_id
        AND s.worksite_id = ewr.worksite_id
        AND s.role_type = ewr.role_type
    );

  UPDATE employer_worksite_roles
  SET employer_id = v_survivor_id
  WHERE employer_id = ANY(v_victim_ids);

  UPDATE employer_sectors
  SET employer_id = v_survivor_id
  WHERE employer_id = ANY(v_victim_ids);

  UPDATE employer_tags
  SET employer_id = v_survivor_id
  WHERE employer_id = ANY(v_victim_ids);

  UPDATE project_employers
  SET employer_id = v_survivor_id
  WHERE employer_id = ANY(v_victim_ids);

  UPDATE campaign_employers
  SET employer_id = v_survivor_id
  WHERE employer_id = ANY(v_victim_ids);

  -- Dedupe agreement_employers
  UPDATE agreement_employers ae
  SET is_primary = s.mx
  FROM (
    SELECT agreement_id, BOOL_OR(is_primary) AS mx
    FROM agreement_employers
    WHERE employer_id = v_survivor_id
    GROUP BY agreement_id
  ) s
  WHERE ae.employer_id = v_survivor_id
    AND ae.agreement_id = s.agreement_id;

  DELETE FROM agreement_employers ae
  WHERE ae.employer_id = v_survivor_id
    AND ae.id IN (
      SELECT id
      FROM (
        SELECT id,
               ROW_NUMBER() OVER (
                 PARTITION BY agreement_id, employer_id
                 ORDER BY is_primary DESC, id
               ) AS rn
        FROM agreement_employers
        WHERE employer_id = v_survivor_id
      ) x
      WHERE rn > 1
    );

  -- employer_sectors
  DELETE FROM employer_sectors es
  WHERE es.id IN (
    SELECT id FROM (
      SELECT id,
             ROW_NUMBER() OVER (
               PARTITION BY employer_id, sector_id
               ORDER BY id
             ) AS rn
      FROM employer_sectors
      WHERE employer_id = v_survivor_id
    ) x WHERE rn > 1
  );

  -- employer_tags
  DELETE FROM employer_tags et
  WHERE et.id IN (
    SELECT id FROM (
      SELECT id,
             ROW_NUMBER() OVER (
               PARTITION BY employer_id, tag_id
               ORDER BY id
             ) AS rn
      FROM employer_tags
      WHERE employer_id = v_survivor_id
    ) x WHERE rn > 1
  );

  -- project_employers
  DELETE FROM project_employers pe
  WHERE pe.id IN (
    SELECT id FROM (
      SELECT id,
             ROW_NUMBER() OVER (
               PARTITION BY employer_id, project_id
               ORDER BY id
             ) AS rn
      FROM project_employers
      WHERE employer_id = v_survivor_id
    ) x WHERE rn > 1
  );

  -- worksite_scopes
  DELETE FROM worksite_scopes ws
  WHERE ws.id IN (
    SELECT id FROM (
      SELECT id,
             ROW_NUMBER() OVER (
               PARTITION BY employer_id, worksite_id
               ORDER BY id
             ) AS rn
      FROM worksite_scopes
      WHERE employer_id = v_survivor_id
    ) x WHERE rn > 1
  );

  -- employer_worksite_roles: dedupe on actual constraint (employer_id, worksite_id, role_type)
  DELETE FROM employer_worksite_roles ewr
  WHERE ewr.id IN (
    SELECT id FROM (
      SELECT id,
             ROW_NUMBER() OVER (
               PARTITION BY employer_id, worksite_id, role_type
               ORDER BY CASE WHEN is_current THEN 0 ELSE 1 END,
                        length(COALESCE(notes, '')),
                        id
             ) AS rn
      FROM employer_worksite_roles
      WHERE employer_id = v_survivor_id
    ) x WHERE rn > 1
  );

  -- Fill null scalar fields on survivor from victims (ascending victim id)
  FOREACH v_cur IN ARRAY v_victim_ids
  LOOP
    UPDATE employers surv
    SET
      trading_name = COALESCE(surv.trading_name, v.trading_name),
      abn = COALESCE(surv.abn, v.abn),
      employer_category = COALESCE(surv.employer_category, v.employer_category),
      parent_company = COALESCE(surv.parent_company, v.parent_company),
      website = COALESCE(surv.website, v.website),
      phone = COALESCE(surv.phone, v.phone),
      email = COALESCE(surv.email, v.email),
      address = COALESCE(surv.address, v.address),
      state = COALESCE(surv.state, v.state),
      postcode = COALESCE(surv.postcode, v.postcode),
      updated_at = now()
    FROM employers v
    WHERE surv.employer_id = v_survivor_id
      AND v.employer_id = v_cur;
  END LOOP;

  UPDATE employers
  SET employer_name = v_canonical,
      updated_at = now()
  WHERE employer_id = v_survivor_id;

  -- Insert aliases (dedupe case-insensitive, skip canonical)
  FOR v_rec IN
    SELECT DISTINCT ON (lower(trim(both FROM t.x))) trim(both FROM t.x) AS nm
    FROM unnest(v_alias_names) AS t(x)
    WHERE length(trim(both FROM t.x)) > 0
    ORDER BY lower(trim(both FROM t.x))
  LOOP
    v_name := v_rec.nm;
    IF lower(trim(v_name)) = lower(trim(v_canonical)) THEN
      CONTINUE;
    END IF;
    BEGIN
      INSERT INTO employer_name_aliases (employer_id, alias_name, source, created_by)
      VALUES (v_survivor_id, v_name, 'merge', v_admin_user_id);
      v_aliases_inserted := v_aliases_inserted + 1;
    EXCEPTION
      WHEN unique_violation THEN
        NULL;
    END;
  END LOOP;

  DELETE FROM employers WHERE employer_id = ANY(v_victim_ids);

  INSERT INTO employer_merge_events (
    survivor_employer_id,
    victim_employer_ids,
    performed_by,
    payload
  ) VALUES (
    v_survivor_id,
    v_victim_ids,
    v_admin_user_id,
    jsonb_build_object(
      'canonical_employer_name', v_canonical,
      'alias_names', to_jsonb(v_alias_names),
      'workers_updated', v_workers_updated
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'survivor_employer_id', v_survivor_id,
    'victims_merged', cardinality(v_victim_ids),
    'workers_updated', v_workers_updated,
    'agreement_rows_updated', v_agreements_updated,
    'aliases_inserted', v_aliases_inserted,
    'warnings', v_warnings
  );
END;
$_$;


ALTER FUNCTION "public"."merge_employers"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_employers"("payload" "jsonb") IS 'Admin-only via API: merge victim employers into survivor, repoint FKs, dedupe junctions, add aliases.';



CREATE OR REPLACE FUNCTION "public"."merge_workers"("p_survivor_id" integer, "p_victim_ids" integer[], "p_campaign_id" integer DEFAULT NULL::integer, "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_victim INT;
  v_from workers%ROWTYPE;
  v_to workers%ROWTYPE;
  v_merged INT := 0;
  v_note TEXT;
BEGIN
  IF p_survivor_id IS NULL OR p_victim_ids IS NULL OR cardinality(p_victim_ids) < 1 THEN
    RAISE EXCEPTION 'merge_workers: survivor and at least one duplicate are required';
  END IF;

  IF auth.uid() IS NULL THEN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
      RAISE EXCEPTION 'merge_workers: permission denied'
        USING ERRCODE = '42501';
    END IF;
  ELSIF NOT (
    is_admin() OR (p_campaign_id IS NOT NULL AND can_write_to_campaign(p_campaign_id))
  ) THEN
    RAISE EXCEPTION 'merge_workers: permission denied'
      USING ERRCODE = '42501';
  END IF;

  IF p_campaign_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM campaign_worker_membership
      WHERE campaign_id = p_campaign_id AND worker_id = p_survivor_id
    ) THEN
      RAISE EXCEPTION 'merge_workers: keep record % is not in this campaign', p_survivor_id;
    END IF;
    IF EXISTS (
      SELECT 1 FROM unnest(p_victim_ids) AS v(id)
      WHERE id <> p_survivor_id
        AND NOT EXISTS (
          SELECT 1 FROM campaign_worker_membership
          WHERE campaign_id = p_campaign_id AND worker_id = v.id
        )
    ) THEN
      RAISE EXCEPTION 'merge_workers: every duplicate must be in this campaign';
    END IF;
  END IF;

  SELECT * INTO v_to FROM workers WHERE worker_id = p_survivor_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'merge_workers: worker % not found', p_survivor_id;
  END IF;

  FOREACH v_victim IN ARRAY p_victim_ids
  LOOP
    IF v_victim = p_survivor_id THEN
      CONTINUE;
    END IF;
    SELECT * INTO v_from FROM workers WHERE worker_id = v_victim;
    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    UPDATE workers SET reference_id = NULL WHERE worker_id = v_victim;

    UPDATE workers SET
      email = COALESCE(NULLIF(btrim(email), ''), NULLIF(btrim(v_from.email), '')),
      phone = COALESCE(NULLIF(btrim(phone), ''), NULLIF(btrim(v_from.phone), '')),
      phone_e164 = COALESCE(phone_e164, v_from.phone_e164),
      preferred_name = COALESCE(NULLIF(btrim(preferred_name), ''), NULLIF(btrim(v_from.preferred_name), '')),
      address = COALESCE(NULLIF(btrim(address), ''), NULLIF(btrim(v_from.address), '')),
      suburb = COALESCE(NULLIF(btrim(suburb), ''), NULLIF(btrim(v_from.suburb), '')),
      state = COALESCE(NULLIF(btrim(state), ''), NULLIF(btrim(v_from.state), '')),
      postcode = COALESCE(NULLIF(btrim(postcode), ''), NULLIF(btrim(v_from.postcode), '')),
      date_of_birth = COALESCE(date_of_birth, v_from.date_of_birth),
      occupation = COALESCE(NULLIF(btrim(occupation), ''), NULLIF(btrim(v_from.occupation), '')),
      canonical_occupation_id = COALESCE(canonical_occupation_id, v_from.canonical_occupation_id),
      employer_id = COALESCE(employer_id, v_from.employer_id),
      worksite_id = COALESCE(worksite_id, v_from.worksite_id),
      member_role_type_id = COALESCE(member_role_type_id, v_from.member_role_type_id),
      union_membership_type_id = COALESCE(union_membership_type_id, v_from.union_membership_type_id),
      action_network_id = COALESCE(action_network_id, v_from.action_network_id),
      reference_id = COALESCE(reference_id, v_from.reference_id),
      is_hsr = COALESCE(is_hsr, false) OR COALESCE(v_from.is_hsr, false),
      is_bargaining_rep = COALESCE(is_bargaining_rep, false) OR COALESCE(v_from.is_bargaining_rep, false),
      notes = CASE
        WHEN notes IS NULL OR btrim(notes) = '' THEN v_from.notes
        WHEN v_from.notes IS NULL OR btrim(v_from.notes) = '' THEN notes
        ELSE notes || E'\n\n' || v_from.notes
      END
    WHERE worker_id = p_survivor_id;

    SELECT * INTO v_to FROM workers WHERE worker_id = p_survivor_id;

    PERFORM remap_worker_id(v_victim, p_survivor_id);
    DELETE FROM workers WHERE worker_id = v_victim;
    v_merged := v_merged + 1;
  END LOOP;

  IF v_merged = 0 THEN
    RETURN 0;
  END IF;

  v_note := format(
    'Merged duplicate worker record(s) %s into this worker.',
    array_to_string(p_victim_ids, ', ')
  );
  INSERT INTO worker_notes (worker_id, campaign_id, note_text, created_by)
  VALUES (
    p_survivor_id,
    p_campaign_id,
    v_note,
    COALESCE(p_actor_id, auth.uid())
  );

  RETURN v_merged;
END;
$$;


ALTER FUNCTION "public"."merge_workers"("p_survivor_id" integer, "p_victim_ids" integer[], "p_campaign_id" integer, "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_workers"("p_survivor_id" integer, "p_victim_ids" integer[], "p_campaign_id" integer, "p_actor_id" "uuid") IS 'Collapse duplicate workers into a survivor: remap FKs, copy blank identity fields, delete victims.';



CREATE OR REPLACE FUNCTION "public"."normalise_email_subject"("p_subject" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    AS $$
  SELECT NULLIF(lower(trim(regexp_replace(p_subject, '^(\s*((re|fw|fwd)\s*:\s*))+', '', 'i'))), '');
$$;


ALTER FUNCTION "public"."normalise_email_subject"("p_subject" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalise_phone_au"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN digits = '' THEN NULL
    WHEN length(digits) = 9 THEN '0' || digits
    WHEN length(digits) = 10 AND digits LIKE '0%' THEN digits
    WHEN length(digits) = 11 AND digits LIKE '61%' THEN '0' || substr(digits, 3)
    WHEN length(digits) = 12 AND digits LIKE '610%' THEN '0' || substr(digits, 4)
    ELSE digits
  END
  FROM (SELECT regexp_replace(coalesce(p, ''), '\D', '', 'g') AS digits) d;
$$;


ALTER FUNCTION "public"."normalise_phone_au"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_live_sms_episode_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.is_sms_episode THEN
    IF EXISTS (
      SELECT 1 FROM sms_lists
      WHERE campaign_id = OLD.campaign_id
        AND (
          (COALESCE(mode, 'blast') = 'blast' AND status IN ('queued', 'sending', 'paused'))
          OR (mode = 'p2p' AND status = 'draft' AND sent_items > 0)
        )
    ) OR EXISTS (
      SELECT 1 FROM sms_surveys
      WHERE campaign_id = OLD.campaign_id
        AND status IN ('open', 'paused')
    ) THEN
      RAISE EXCEPTION
        'Cannot delete a standalone SMS episode while an action is still live — cancel, close or end it first';
    END IF;
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."prevent_live_sms_episode_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."propagate_employer_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.employer_id IS NOT NULL THEN
    INSERT INTO employer_scopes (employer_id, scope_id, is_current, source)
    VALUES (NEW.employer_id, NEW.scope_id, true, 'auto')
    ON CONFLICT (employer_id, scope_id) DO UPDATE
    SET is_current = true;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."propagate_employer_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_assessment_event"("p_activity_id" integer, "p_worker_id" integer, "p_rating" integer DEFAULT NULL::integer, "p_binary_value" character varying DEFAULT NULL::character varying, "p_rating_phase" character varying DEFAULT 'actual'::character varying, "p_event_id" integer DEFAULT NULL::integer, "p_source" character varying DEFAULT 'staff'::character varying, "p_notes" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_import_batch_id" integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_rating_id INT;
BEGIN
  IF p_rating IS NULL AND p_binary_value IS NULL THEN
    RAISE EXCEPTION
      'record_assessment_event: at least one of p_rating or p_binary_value must be non-null';
  END IF;

  IF p_rating IS NOT NULL AND (p_rating < 1 OR p_rating > 5) THEN
    RAISE EXCEPTION
      'record_assessment_event: p_rating must be 1..5 (got %)', p_rating;
  END IF;

  IF p_rating_phase NOT IN ('expected', 'actual') THEN
    RAISE EXCEPTION
      'record_assessment_event: p_rating_phase must be expected or actual (got %)', p_rating_phase;
  END IF;

  INSERT INTO campaign_activity_ratings (
    activity_id, worker_id, rating, binary_value, notes,
    source, rated_at, rated_by_user_id, rating_phase, event_id,
    import_batch_id
  )
  VALUES (
    p_activity_id, p_worker_id, p_rating, p_binary_value, p_notes,
    p_source, now(), p_actor_id, p_rating_phase, p_event_id,
    p_import_batch_id
  )
  ON CONFLICT (activity_id, worker_id, rating_phase, event_id) DO UPDATE SET
    rating = COALESCE(EXCLUDED.rating, campaign_activity_ratings.rating),
    binary_value = COALESCE(EXCLUDED.binary_value, campaign_activity_ratings.binary_value),
    notes = COALESCE(EXCLUDED.notes, campaign_activity_ratings.notes),
    source = EXCLUDED.source,
    rated_at = EXCLUDED.rated_at,
    rated_by_user_id = COALESCE(EXCLUDED.rated_by_user_id, campaign_activity_ratings.rated_by_user_id),
    import_batch_id = COALESCE(EXCLUDED.import_batch_id, campaign_activity_ratings.import_batch_id)
  RETURNING rating_id INTO v_rating_id;

  RETURN v_rating_id;
END;
$$;


ALTER FUNCTION "public"."record_assessment_event"("p_activity_id" integer, "p_worker_id" integer, "p_rating" integer, "p_binary_value" character varying, "p_rating_phase" character varying, "p_event_id" integer, "p_source" character varying, "p_notes" "text", "p_actor_id" "uuid", "p_import_batch_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_assessment_event"("p_activity_id" integer, "p_worker_id" integer, "p_rating" integer, "p_binary_value" character varying, "p_rating_phase" character varying, "p_event_id" integer, "p_source" character varying, "p_notes" "text", "p_actor_id" "uuid", "p_import_batch_id" integer) IS 'Single upsert entry point for campaign_activity_ratings. Validates rating range and phase; returns the rating_id. Other sources (SMS, email, petition, meeting, staff UI, AN import) should funnel through this.';



CREATE OR REPLACE FUNCTION "public"."record_call_attempt"("p_list_item_id" integer, "p_script_id" integer, "p_caller_user_id" "uuid", "p_dial_disposition" character varying, "p_call_disposition" character varying DEFAULT NULL::character varying, "p_overall_notes" "text" DEFAULT NULL::"text", "p_callback_datetime" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_support_level" character varying DEFAULT NULL::character varying, "p_follow_up_action" "text" DEFAULT NULL::"text", "p_cta_response" character varying DEFAULT NULL::character varying, "p_duration_seconds" integer DEFAULT NULL::integer, "p_step_outcomes" "jsonb" DEFAULT '[]'::"jsonb", "p_objections" "jsonb" DEFAULT '[]'::"jsonb", "p_issues" "jsonb" DEFAULT '[]'::"jsonb", "p_cta_ratings" "jsonb" DEFAULT '[]'::"jsonb", "p_assessment_ratings" "jsonb" DEFAULT '[]'::"jsonb", "p_action_id" integer DEFAULT NULL::integer, "p_share_token_id" integer DEFAULT NULL::integer, "p_caller_leader_worker_id" integer DEFAULT NULL::integer, "p_caller_session_label" "text" DEFAULT NULL::"text", "p_caller_session_worker_id" integer DEFAULT NULL::integer, "p_outcome_classification" character varying DEFAULT NULL::character varying) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_attempt_id INTEGER;
  v_worker_id INTEGER;
  v_campaign_id INTEGER;
  v_list_id INTEGER;
  v_connection_id BIGINT;
  v_item_status VARCHAR(20);
  v_step JSONB;
  v_result JSONB;
  v_obj JSONB;
  v_iss JSONB;
  v_cta JSONB;
  v_ar JSONB;
  v_objections_inserted INTEGER := 0;
  v_issues_inserted INTEGER := 0;
  v_cta_ratings_inserted INTEGER := 0;
  v_assessment_ratings_inserted INTEGER := 0;
  v_ambition_id INTEGER;
  v_ambition_activity_id INTEGER;
  v_cta_rating SMALLINT;
  v_cta_binary VARCHAR(30);
  v_cta_notes TEXT;
  v_ar_activity_id INTEGER;
  v_ar_rating SMALLINT;
  v_ar_notes TEXT;
BEGIN
  SELECT cli.worker_id, cl.campaign_id, cli.list_id
  INTO v_worker_id, v_campaign_id, v_list_id
  FROM call_list_items cli
  JOIN call_lists cl ON cl.list_id = cli.list_id
  WHERE cli.item_id = p_list_item_id;

  IF v_worker_id IS NULL THEN
    RAISE EXCEPTION 'call_list_item % not found', p_list_item_id;
  END IF;

  INSERT INTO call_attempts (
    list_item_id, script_id, caller_user_id,
    dial_disposition, call_disposition,
    overall_notes, callback_datetime, support_level_assessed,
    follow_up_action, cta_response, duration_seconds,
    ended_at,
    share_token_id, caller_leader_worker_id,
    caller_session_label, caller_session_worker_id,
    outcome_classification
  ) VALUES (
    p_list_item_id, p_script_id, p_caller_user_id,
    p_dial_disposition, p_call_disposition,
    p_overall_notes, p_callback_datetime, p_support_level,
    p_follow_up_action, p_cta_response, p_duration_seconds,
    CASE WHEN p_duration_seconds IS NOT NULL THEN now() ELSE NULL END,
    p_share_token_id, p_caller_leader_worker_id,
    LEFT(p_caller_session_label, 80), p_caller_session_worker_id,
    p_outcome_classification
  )
  RETURNING attempt_id INTO v_attempt_id;

  FOR v_step IN SELECT * FROM jsonb_array_elements(p_step_outcomes)
  LOOP
    INSERT INTO call_step_outcomes (
      attempt_id, section_id, reached, outcome_value, notes, duration_seconds, sort_order
    ) VALUES (
      v_attempt_id,
      (v_step->>'section_id')::INTEGER,
      COALESCE((v_step->>'reached')::BOOLEAN, false),
      v_step->>'outcome_value',
      v_step->>'notes',
      (v_step->>'duration_seconds')::INTEGER,
      COALESCE((v_step->>'sort_order')::INTEGER, 0)
    );
  END LOOP;

  IF p_call_disposition IN ('removed_from_campaign', 'no_longer_in_universe') THEN
    v_item_status := 'completed';
  ELSIF p_dial_disposition = 'callback_requested' OR p_call_disposition = 'partial_asked_callback' THEN
    v_item_status := 'deferred';
  ELSIF p_dial_disposition = 'connected' AND p_call_disposition IS NOT NULL THEN
    v_item_status := 'completed';
  ELSIF p_dial_disposition IN ('disconnected', 'wrong_number', 'do_not_call') THEN
    v_item_status := 'completed';
  ELSE
    v_item_status := 'pending';
  END IF;

  UPDATE call_list_items SET
    status = v_item_status,
    attempts_count = attempts_count + 1,
    last_attempt_at = now(),
    best_disposition = COALESCE(p_call_disposition, p_dial_disposition),
    next_call_at = p_callback_datetime,
    claimed_at = NULL,
    claimed_by_session_label = NULL,
    claimed_by_worker_id = NULL,
    updated_at = now()
  WHERE item_id = p_list_item_id;

  UPDATE call_lists SET
    completed_items = (
      SELECT COUNT(*) FROM call_list_items
      WHERE list_id = v_list_id AND status IN ('completed', 'skipped')
    ),
    updated_at = now()
  WHERE list_id = v_list_id;

  SELECT connection_id INTO v_connection_id
  FROM worker_campaign_connections
  WHERE worker_id = v_worker_id AND campaign_id = v_campaign_id;

  IF v_connection_id IS NULL THEN
    INSERT INTO worker_campaign_connections (
      worker_id, campaign_id, connection_status,
      first_contacted_at, last_contacted_at, contact_count,
      preferred_contact_method, support_level, created_by
    ) VALUES (
      v_worker_id, v_campaign_id,
      CASE
        WHEN p_dial_disposition = 'connected' THEN 'contacted'
        ELSE 'potential'
      END,
      now(), now(), 1,
      'phone',
      p_support_level,
      p_caller_user_id
    )
    RETURNING connection_id INTO v_connection_id;
  ELSE
    UPDATE worker_campaign_connections SET
      connection_status = CASE
        WHEN p_dial_disposition = 'connected'
          AND connection_status IN ('potential', 'contacted') THEN 'engaged'
        WHEN p_dial_disposition = 'connected' THEN connection_status
        ELSE connection_status
      END,
      last_contacted_at = now(),
      contact_count = contact_count + 1,
      support_level = COALESCE(p_support_level, support_level),
      updated_at = now()
    WHERE connection_id = v_connection_id;
  END IF;

  INSERT INTO worker_activity_log (
    connection_id, activity_type, activity_date,
    description, outcome, contact_method,
    duration_minutes, logged_by, action_id
  ) VALUES (
    v_connection_id, 'contact', now(),
    COALESCE(p_overall_notes, 'Phone call attempt'),
    COALESCE(p_outcome_classification, p_call_disposition, p_dial_disposition),
    'phone',
    CASE WHEN p_duration_seconds IS NOT NULL
      THEN CEIL(p_duration_seconds / 60.0)::INTEGER
      ELSE NULL
    END,
    p_caller_user_id,
    p_action_id
  );

  FOR v_obj IN SELECT * FROM jsonb_array_elements(p_objections)
  LOOP
    INSERT INTO call_attempt_objections (
      attempt_id, worker_id, objection_id, custom_label, outcome, notes
    ) VALUES (
      v_attempt_id,
      v_worker_id,
      (v_obj->>'objection_id')::INTEGER,
      v_obj->>'custom_label',
      v_obj->>'outcome',
      v_obj->>'notes'
    );
    v_objections_inserted := v_objections_inserted + 1;
  END LOOP;

  FOR v_cta IN SELECT * FROM jsonb_array_elements(p_cta_ratings)
  LOOP
    v_ambition_id := (v_cta->>'cta_ambition_id')::INTEGER;
    IF v_ambition_id IS NULL THEN CONTINUE; END IF;

    SELECT activity_id INTO v_ambition_activity_id
    FROM call_script_cta_ambitions
    WHERE id = v_ambition_id;

    v_cta_rating := NULLIF(v_cta->>'rating', '')::SMALLINT;
    v_cta_binary := NULLIF(v_cta->>'binary_value', '');
    v_cta_notes  := NULLIF(v_cta->>'notes', '');

    IF v_cta_rating IS NULL AND v_cta_binary IS NULL THEN
      CONTINUE;
    END IF;

    INSERT INTO call_attempt_cta_ratings (
      attempt_id, cta_ambition_id, activity_id, worker_id,
      rating, binary_value, notes, created_by
    ) VALUES (
      v_attempt_id, v_ambition_id, v_ambition_activity_id, v_worker_id,
      v_cta_rating, v_cta_binary, v_cta_notes, p_caller_user_id
    )
    ON CONFLICT (attempt_id, cta_ambition_id) DO UPDATE SET
      rating       = EXCLUDED.rating,
      binary_value = EXCLUDED.binary_value,
      notes        = EXCLUDED.notes,
      activity_id  = EXCLUDED.activity_id,
      created_by   = EXCLUDED.created_by;

    v_cta_ratings_inserted := v_cta_ratings_inserted + 1;

    IF v_ambition_activity_id IS NOT NULL THEN
      PERFORM record_assessment_event(
        p_activity_id   := v_ambition_activity_id,
        p_worker_id     := v_worker_id,
        p_rating        := v_cta_rating,
        p_binary_value  := v_cta_binary,
        p_rating_phase  := 'actual',
        -- A call attempt is not an activity_events occurrence; the call ↔
        -- rating link lives in call_attempt_cta_ratings. NULL event_id =
        -- "rating against the activity in general" per the activity_events
        -- design, and avoids the car_event_id_fk FK violation.
        p_event_id      := NULL,
        p_source        := 'call_outcome',
        p_notes         := v_cta_notes,
        p_actor_id      := p_caller_user_id
      );
    END IF;
  END LOOP;

  FOR v_ar IN SELECT * FROM jsonb_array_elements(p_assessment_ratings)
  LOOP
    v_ar_activity_id := NULLIF(v_ar->>'activity_id', '')::INTEGER;
    IF v_ar_activity_id IS NULL THEN CONTINUE; END IF;

    v_ar_rating := NULLIF(v_ar->>'rating', '')::SMALLINT;
    v_ar_notes  := NULLIF(v_ar->>'notes', '');

    INSERT INTO call_attempt_assessment_ratings (
      attempt_id, activity_id, rating, notes
    ) VALUES (
      v_attempt_id, v_ar_activity_id, v_ar_rating, v_ar_notes
    )
    ON CONFLICT (attempt_id, activity_id) DO UPDATE SET
      rating = EXCLUDED.rating,
      notes  = EXCLUDED.notes;

    v_assessment_ratings_inserted := v_assessment_ratings_inserted + 1;

    IF v_ar_rating IS NOT NULL THEN
      PERFORM record_assessment_event(
        p_activity_id   := v_ar_activity_id,
        p_worker_id     := v_worker_id,
        p_rating        := v_ar_rating,
        p_binary_value  := NULL,
        p_rating_phase  := 'actual',
        -- See note above: NULL event_id, link preserved in
        -- call_attempt_assessment_ratings.
        p_event_id      := NULL,
        p_source        := 'call_outcome',
        p_notes         := v_ar_notes,
        p_actor_id      := p_caller_user_id
      );
    END IF;
  END LOOP;

  FOR v_iss IN SELECT * FROM jsonb_array_elements(p_issues)
  LOOP
    INSERT INTO call_issue_observations (
      attempt_id, worker_id, campaign_id, issue_label, heat, source_top_issue_index, notes
    ) VALUES (
      v_attempt_id,
      v_worker_id,
      v_campaign_id,
      v_iss->>'issue_label',
      (v_iss->>'heat')::SMALLINT,
      (v_iss->>'source_top_issue_index')::INTEGER,
      v_iss->>'notes'
    );
    v_issues_inserted := v_issues_inserted + 1;
  END LOOP;

  v_result := jsonb_build_object(
    'attempt_id', v_attempt_id,
    'item_status', v_item_status,
    'connection_id', v_connection_id,
    'worker_id', v_worker_id,
    'campaign_id', v_campaign_id,
    'outcome_classification', p_outcome_classification,
    'objections_inserted', v_objections_inserted,
    'issues_inserted', v_issues_inserted,
    'cta_ratings_inserted', v_cta_ratings_inserted,
    'assessment_ratings_inserted', v_assessment_ratings_inserted
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."record_call_attempt"("p_list_item_id" integer, "p_script_id" integer, "p_caller_user_id" "uuid", "p_dial_disposition" character varying, "p_call_disposition" character varying, "p_overall_notes" "text", "p_callback_datetime" timestamp with time zone, "p_support_level" character varying, "p_follow_up_action" "text", "p_cta_response" character varying, "p_duration_seconds" integer, "p_step_outcomes" "jsonb", "p_objections" "jsonb", "p_issues" "jsonb", "p_cta_ratings" "jsonb", "p_assessment_ratings" "jsonb", "p_action_id" integer, "p_share_token_id" integer, "p_caller_leader_worker_id" integer, "p_caller_session_label" "text", "p_caller_session_worker_id" integer, "p_outcome_classification" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_campaign_fact"("p_field_id" integer, "p_worker_id" integer, "p_campaign_id" integer, "p_value_bool" boolean DEFAULT NULL::boolean, "p_value_int" integer DEFAULT NULL::integer, "p_value_text" "text" DEFAULT NULL::"text", "p_value_enum" character varying DEFAULT NULL::character varying, "p_value_json" "jsonb" DEFAULT NULL::"jsonb", "p_source" character varying DEFAULT 'staff'::character varying, "p_source_ref" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_clear" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_field campaign_data_fields%ROWTYPE;
  v_fact_id INT;
  v_allowed TEXT[];
  v_json_el JSONB;
  v_enum TEXT;
  v_bool BOOLEAN := p_value_bool;
  v_int INT := p_value_int;
  v_text TEXT := p_value_text;
  v_enum_val VARCHAR := p_value_enum;
  v_json JSONB := p_value_json;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT (can_write_to_campaign(p_campaign_id) OR is_admin()) THEN
    RAISE EXCEPTION 'record_campaign_fact: permission denied for campaign %', p_campaign_id
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_field FROM campaign_data_fields WHERE field_id = p_field_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'record_campaign_fact: field % not found', p_field_id;
  END IF;
  IF v_field.campaign_id <> p_campaign_id THEN
    RAISE EXCEPTION 'record_campaign_fact: field % belongs to campaign %, not %',
      p_field_id, v_field.campaign_id, p_campaign_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM workers WHERE worker_id = p_worker_id) THEN
    RAISE EXCEPTION 'record_campaign_fact: worker % not found', p_worker_id;
  END IF;
  IF p_source IS NULL OR p_source NOT IN ('sms_survey', 'an_csv', 'email', 'phone', 'staff') THEN
    RAISE EXCEPTION 'record_campaign_fact: invalid source %', p_source;
  END IF;

  IF p_clear THEN
    DELETE FROM worker_campaign_facts
    WHERE campaign_id = p_campaign_id AND worker_id = p_worker_id AND field_id = p_field_id
    RETURNING fact_id INTO v_fact_id;
    RETURN COALESCE(v_fact_id, 0);
  END IF;

  IF v_field.value_type = 'boolean' THEN
    IF v_bool IS NULL THEN
      RAISE EXCEPTION 'record_campaign_fact: boolean field % requires value_bool', p_field_id;
    END IF;
    v_int := NULL; v_text := NULL; v_enum_val := NULL; v_json := NULL;
  ELSIF v_field.value_type IN ('integer', 'scale') THEN
    IF v_int IS NULL THEN
      RAISE EXCEPTION 'record_campaign_fact: % field % requires value_int', v_field.value_type, p_field_id;
    END IF;
    IF v_field.scale_min IS NOT NULL AND v_int < v_field.scale_min THEN
      RAISE EXCEPTION 'record_campaign_fact: value_int % below scale_min %', v_int, v_field.scale_min;
    END IF;
    IF v_field.scale_max IS NOT NULL AND v_int > v_field.scale_max THEN
      RAISE EXCEPTION 'record_campaign_fact: value_int % above scale_max %', v_int, v_field.scale_max;
    END IF;
    v_bool := NULL; v_text := NULL; v_enum_val := NULL; v_json := NULL;
  ELSIF v_field.value_type = 'text' THEN
    IF v_text IS NULL OR btrim(v_text) = '' THEN
      RAISE EXCEPTION 'record_campaign_fact: text field % requires value_text', p_field_id;
    END IF;
    v_text := left(v_text, 4000);
    v_bool := NULL; v_int := NULL; v_enum_val := NULL; v_json := NULL;
  ELSIF v_field.value_type = 'enum' THEN
    IF v_enum_val IS NULL OR btrim(v_enum_val) = '' THEN
      RAISE EXCEPTION 'record_campaign_fact: enum field % requires value_enum', p_field_id;
    END IF;
    v_allowed := campaign_fact_enum_values(v_field.enum_options);
    IF array_length(v_allowed, 1) IS NULL OR NOT (v_enum_val = ANY (v_allowed)) THEN
      RAISE EXCEPTION 'record_campaign_fact: % is not an allowed value for field %', v_enum_val, p_field_id;
    END IF;
    v_bool := NULL; v_int := NULL; v_text := NULL; v_json := NULL;
  ELSIF v_field.value_type = 'multi_enum' THEN
    IF v_json IS NULL OR jsonb_typeof(v_json) <> 'array' OR jsonb_array_length(v_json) = 0 THEN
      RAISE EXCEPTION 'record_campaign_fact: multi_enum field % requires a non-empty JSON array', p_field_id;
    END IF;
    v_allowed := campaign_fact_enum_values(v_field.enum_options);
    FOR v_json_el IN SELECT jsonb_array_elements(v_json)
    LOOP
      IF jsonb_typeof(v_json_el) <> 'string' THEN
        RAISE EXCEPTION 'record_campaign_fact: multi_enum values must be strings';
      END IF;
      v_enum := v_json_el #>> '{}';
      IF array_length(v_allowed, 1) IS NULL OR NOT (v_enum = ANY (v_allowed)) THEN
        RAISE EXCEPTION 'record_campaign_fact: % is not an allowed value for field %', v_enum, p_field_id;
      END IF;
    END LOOP;
    v_bool := NULL; v_int := NULL; v_text := NULL; v_enum_val := NULL;
  ELSE
    RAISE EXCEPTION 'record_campaign_fact: unknown value_type %', v_field.value_type;
  END IF;

  INSERT INTO worker_campaign_facts (
    campaign_id, worker_id, field_id,
    value_bool, value_int, value_text, value_enum, value_json,
    collected_at, source, source_ref, notes, recorded_by
  ) VALUES (
    p_campaign_id, p_worker_id, p_field_id,
    v_bool, v_int, v_text, v_enum_val, v_json,
    now(), p_source, p_source_ref, p_notes, COALESCE(p_actor_id, auth.uid())
  )
  ON CONFLICT (campaign_id, worker_id, field_id) DO UPDATE SET
    value_bool = EXCLUDED.value_bool,
    value_int = EXCLUDED.value_int,
    value_text = EXCLUDED.value_text,
    value_enum = EXCLUDED.value_enum,
    value_json = EXCLUDED.value_json,
    collected_at = EXCLUDED.collected_at,
    source = EXCLUDED.source,
    source_ref = EXCLUDED.source_ref,
    notes = COALESCE(EXCLUDED.notes, worker_campaign_facts.notes),
    recorded_by = COALESCE(EXCLUDED.recorded_by, worker_campaign_facts.recorded_by)
  RETURNING fact_id INTO v_fact_id;

  RETURN v_fact_id;
END;
$$;


ALTER FUNCTION "public"."record_campaign_fact"("p_field_id" integer, "p_worker_id" integer, "p_campaign_id" integer, "p_value_bool" boolean, "p_value_int" integer, "p_value_text" "text", "p_value_enum" character varying, "p_value_json" "jsonb", "p_source" character varying, "p_source_ref" "text", "p_notes" "text", "p_actor_id" "uuid", "p_clear" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_all_pending_gate_criteria"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_campaign RECORD;
  v_refreshed_campaigns INTEGER[] := '{}';
  v_failed_campaigns INTEGER[] := '{}';
  v_result JSONB;
BEGIN
  -- Refresh all active campaigns
  FOR v_campaign IN
    SELECT campaign_id
    FROM campaigns
    WHERE status = 'active'
  LOOP
    BEGIN
      -- Use a savepoint to continue on error
      BEGIN
        -- Refresh criteria for this campaign
        PERFORM refresh_gate_criteria_for_campaign(v_campaign.campaign_id);

        v_refreshed_campaigns := array_append(v_refreshed_campaigns, v_campaign.campaign_id);

      EXCEPTION WHEN OTHERS THEN
        -- Log error and continue
        v_failed_campaigns := array_append(v_failed_campaigns, v_campaign.campaign_id);
      END;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'refreshed_campaigns', v_refreshed_campaigns,
    'failed_campaigns', v_failed_campaigns,
    'total_campaigns', array_length(v_refreshed_campaigns) + array_length(v_failed_campaigns),
    'refreshed_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."refresh_all_pending_gate_criteria"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_email_conversation_from_message"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE email_conversations
  SET original_subject = COALESCE(original_subject, NULLIF(NEW.subject, '')),
      subject = COALESCE(NULLIF(NEW.subject, ''), subject),
      subject_normalized = COALESCE(normalise_email_subject(NULLIF(NEW.subject, '')), subject_normalized),
      last_message_preview = NULLIF(left(trim(regexp_replace(COALESCE(NULLIF(NEW.body_text, ''), regexp_replace(COALESCE(NEW.body_html, ''), '<[^>]+>', ' ', 'g')), '\s+', ' ', 'g')), 240), ''),
      last_rfc_message_id = COALESCE(NEW.rfc_message_id, last_rfc_message_id),
      rfc_references = COALESCE(NEW.rfc_references, rfc_references)
  WHERE conversation_id = NEW.conversation_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."refresh_email_conversation_from_message"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_gate_criteria_for_campaign"("p_campaign_id" integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_agreement_id INTEGER;
  v_criteria RECORD;
  v_new_value NUMERIC;
  v_updated_count INTEGER := 0;
  v_threshold_met BOOLEAN;
  v_target_value NUMERIC;
BEGIN
  -- Get the agreement_id for this campaign
  SELECT agreement_id INTO v_agreement_id
  FROM campaign_timelines
  WHERE campaign_id = p_campaign_id;

  IF v_agreement_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Campaign has no associated agreement',
      'campaign_id', p_campaign_id
    );
  END IF;

  -- Process each gate criterion
  FOR v_criteria IN
    SELECT gc.*
    FROM gate_criteria gc
    JOIN gate_definitions gd ON gd.gate_id = gc.gate_id
    WHERE gd.campaign_id = p_campaign_id
      AND gc.metric_type IN ('percentage', 'count')
  LOOP
    -- Calculate new value based on criterion name
    CASE v_criteria.criterion_name
      WHEN 'Membership Density' THEN
        v_new_value := calculate_membership_density(v_agreement_id);

      WHEN 'Contact Details Verified' THEN
        v_new_value := calculate_contact_details_verified(v_agreement_id);

      WHEN 'Active WOCs' THEN
        v_new_value := calculate_active_wocs(v_agreement_id);

      ELSE
        -- For other criteria, skip auto-calculation
        CONTINUE;
    END CASE;

    -- Skip if we couldn't calculate a value
    IF v_new_value IS NULL THEN
      CONTINUE;
    END IF;

    -- Parse target value (assuming numeric)
    v_target_value := (NULLIF(regexp_replace(v_criteria.target_value, '[^0-9.]', '', 'g'), ''))::numeric;

    IF v_target_value IS NULL THEN
      CONTINUE;
    END IF;

    -- Check if threshold is met
    IF v_criteria.metric_type = 'percentage' THEN
      v_threshold_met := v_new_value >= v_target_value;
    ELSIF v_criteria.metric_type = 'count' THEN
      v_threshold_met := v_new_value >= v_target_value;
    ELSE
      v_threshold_met := FALSE;
    END IF;

    -- Update the criterion
    UPDATE gate_criteria
    SET current_value = v_new_value::TEXT,
        is_met = v_threshold_met,
        last_calculated_at = NOW(),
        calculation_source = 'auto_refresh'
    WHERE criterion_id = v_criteria.criterion_id;

    v_updated_count := v_updated_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'campaign_id', p_campaign_id,
    'agreement_id', v_agreement_id,
    'updated_count', v_updated_count,
    'refreshed_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."refresh_gate_criteria_for_campaign"("p_campaign_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_intractable_state"("p_campaign_id" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_row    intractable_bargaining_tracker%ROWTYPE;
  v_months NUMERIC;
  v_state  TEXT;
BEGIN
  SELECT * INTO v_row
  FROM   intractable_bargaining_tracker
  WHERE  campaign_id = p_campaign_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Terminal states derived from milestone date columns (highest precedence).
  IF v_row.arbitration_outcome_recorded_at IS NOT NULL THEN
    v_state := 'arbitrated';
  ELSIF v_row.intractable_declaration_made_at IS NOT NULL THEN
    v_state := 'declared';
  ELSIF v_row.intractable_application_filed_at IS NOT NULL THEN
    v_state := 'applied';
  ELSE
    -- Time-based state: months since bargaining commenced.
    v_months := EXTRACT(
      EPOCH FROM (CURRENT_DATE - v_row.bargaining_commenced_at)
    ) / (30.4375 * 24 * 3600);  -- average days per month

    IF v_months >= 9 THEN
      v_state := 'eligible';
    ELSIF v_months >= 6 THEN
      v_state := 'approaching';
    ELSE
      v_state := 'safe';
    END IF;
  END IF;

  UPDATE intractable_bargaining_tracker
  SET    state           = v_state,
         last_reviewed_at = now(),
         updated_at      = now()
  WHERE  campaign_id = p_campaign_id;

  RETURN v_state;
END;
$$;


ALTER FUNCTION "public"."refresh_intractable_state"("p_campaign_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_intractable_state"("p_campaign_id" integer) IS 'Recomputes the intractable bargaining state for a campaign from its milestone dates. Call after editing bargaining_commenced_at or any of the application/declaration/outcome dates.';



