CREATE OR REPLACE FUNCTION "public"."release_call_list_item_claim"("p_item_id" integer, "p_session_label" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_released BOOLEAN := false;
BEGIN
  UPDATE call_list_items
  SET status = 'pending',
      claimed_at = NULL,
      claimed_by_session_label = NULL,
      claimed_by_worker_id = NULL,
      updated_at = now()
  WHERE item_id = p_item_id
    AND status = 'in_progress'
    AND claimed_by_session_label = p_session_label
  RETURNING true INTO v_released;

  RETURN COALESCE(v_released, false);
END;
$$;


