    AS $$
BEGIN
  UPDATE sms_conversations
  SET claim_user_id = NULL,
      claimed_until = NULL
  WHERE conversation_id = p_conversation_id
    AND claim_user_id = auth.uid();

  RETURN FOUND;
END;
