CREATE OR REPLACE FUNCTION "public"."remap_worker_id"("p_from" integer, "p_to" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  r RECORD;
  idx RECORD;
  other_cols TEXT[];
  join_pred TEXT;
  col TEXT;
  i INT;
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from = p_to THEN
    RETURN;
  END IF;

  FOR r IN
    SELECT n.nspname AS nsp, c.relname AS tbl, a.attname AS col
    FROM pg_constraint con
    JOIN pg_class c ON c.oid = con.conrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN unnest(con.conkey) WITH ORDINALITY AS ck(attnum, ord) ON true
    JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = ck.attnum
    WHERE con.confrelid = 'public.workers'::regclass
      AND con.contype = 'f'
      AND n.nspname = 'public'
  LOOP
    FOR idx IN
      SELECT array_agg(att.attname ORDER BY x.n) FILTER (WHERE x.attnum > 0) AS cols
      FROM pg_index ix
      JOIN pg_class t ON t.oid = ix.indrelid
      JOIN pg_namespace nsp ON nsp.oid = t.relnamespace
      JOIN LATERAL unnest(ix.indkey) WITH ORDINALITY AS x(attnum, n) ON true
      JOIN pg_attribute att ON att.attrelid = t.oid AND att.attnum = x.attnum
      WHERE nsp.nspname = r.nsp
        AND t.relname = r.tbl
        AND ix.indisunique
      GROUP BY ix.indexrelid
      HAVING bool_or(att.attname = r.col)
    LOOP
      IF idx.cols IS NULL THEN
        CONTINUE;
      END IF;
      other_cols := ARRAY(
        SELECT c FROM unnest(idx.cols) AS c WHERE c <> r.col
      );
      IF coalesce(array_length(other_cols, 1), 0) = 0 THEN
        EXECUTE format(
          'DELETE FROM %I.%I WHERE %I = $1 AND EXISTS (SELECT 1 FROM %I.%I s WHERE s.%I = $2)',
          r.nsp, r.tbl, r.col, r.nsp, r.tbl, r.col
        ) USING p_from, p_to;
      ELSE
        join_pred := '';
        i := 1;
        FOREACH col IN ARRAY other_cols
        LOOP
          IF i > 1 THEN
            join_pred := join_pred || ' AND ';
          END IF;
          join_pred := join_pred || format('v.%I IS NOT DISTINCT FROM s.%I', col, col);
          i := i + 1;
        END LOOP;
        EXECUTE format(
          'DELETE FROM %I.%I v USING %I.%I s WHERE v.%I = $1 AND s.%I = $2 AND %s',
          r.nsp, r.tbl, r.nsp, r.tbl, r.col, r.col, join_pred
        ) USING p_from, p_to;
      END IF;
    END LOOP;

    EXECUTE format(
      'UPDATE %I.%I SET %I = $2 WHERE %I = $1',
      r.nsp, r.tbl, r.col, r.col
    ) USING p_from, p_to;
  END LOOP;

  IF to_regclass('public.worker_campaign_fact_history') IS NOT NULL THEN
    UPDATE worker_campaign_fact_history
    SET worker_id = p_to
    WHERE worker_id = p_from;
  END IF;

  DELETE FROM campaign_leader_worker_links
  WHERE leader_worker_id = follower_worker_id;
END;
$_$;


ALTER FUNCTION "public"."remap_worker_id"("p_from" integer, "p_to" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."renew_call_list_item_claim"("p_item_id" integer, "p_session_label" "text", "p_claim_ttl_seconds" integer DEFAULT 900) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_claimed_at TIMESTAMPTZ;
BEGIN
  UPDATE call_list_items
  SET
    claimed_at = now(),
    updated_at = now()
  WHERE item_id = p_item_id
    AND status = 'in_progress'
    AND claimed_by_session_label = LEFT(p_session_label, 80)
    AND claimed_at IS NOT NULL
    AND claimed_at > now() - make_interval(secs => GREATEST(p_claim_ttl_seconds, 1))
  RETURNING claimed_at INTO v_claimed_at;

  RETURN jsonb_build_object(
    'renewed', v_claimed_at IS NOT NULL,
    'claimed_at', v_claimed_at
  );
END;
$$;


ALTER FUNCTION "public"."renew_call_list_item_claim"("p_item_id" integer, "p_session_label" "text", "p_claim_ttl_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_campaign_edit_permission"("p_campaign_id" integer, "p_reason" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_request_id INTEGER;
  v_campaign_name TEXT;
  v_owner_id UUID;
  v_leads UUID[];
BEGIN
  -- Check if user already has permission
  IF has_campaign_edit_permission(p_campaign_id) OR can_write_to_campaign(p_campaign_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'You already have access to this campaign'
    );
  END IF;

  -- Get campaign info
  SELECT name, created_by INTO v_campaign_name, v_owner_id
  FROM campaigns
  WHERE campaign_id = p_campaign_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Campaign not found'
    );
  END IF;

  -- Create the request
  INSERT INTO campaign_permission_requests (campaign_id, requested_by, reason)
  VALUES (p_campaign_id, auth.uid(), p_reason)
  RETURNING request_id INTO v_request_id;

  -- Get leads/coordinators to notify
  SELECT ARRAY_AGG(DISTINCT up.user_id)
  INTO v_leads
  FROM user_profiles up
  WHERE up.work_role IN ('lead_organiser', 'coordinator', 'industrial_coordinator')
  AND (
    up.user_id = v_owner_id
    OR EXISTS (
      SELECT 1 FROM organisers o
      JOIN campaigns c ON c.organiser_id = o.organiser_id
      JOIN user_profiles op ON op.organiser_id = o.organiser_id
      WHERE c.campaign_id = p_campaign_id
      AND op.reports_to = up.user_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'request_id', v_request_id,
    'campaign_name', v_campaign_name,
    'owner_id', v_owner_id,
    'leads_to_notify', v_leads
  );
END;
$$;


ALTER FUNCTION "public"."request_campaign_edit_permission"("p_campaign_id" integer, "p_reason" "text") OWNER TO "postgres";


