CREATE OR REPLACE FUNCTION "public"."revoke_campaign_edit_permission"("p_permission_id" integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_permission RECORD;
BEGIN
  SELECT * INTO v_permission
  FROM campaign_edit_permissions
  WHERE permission_id = p_permission_id AND status = 'active';

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Permission not found'
    );
  END IF;

  -- Only granters, admins, or the permission recipient can revoke
  IF NOT (
    is_admin()
    OR auth.uid() = v_permission.granted_by
    OR auth.uid() = v_permission.granted_to
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'You do not have permission to revoke this'
    );
  END IF;

  UPDATE campaign_edit_permissions
  SET status = 'revoked',
      revoked_at = NOW(),
      revoked_by = auth.uid()
  WHERE permission_id = p_permission_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."revoke_campaign_edit_permission"("p_permission_id" integer) OWNER TO "postgres";


