  v_delete_result JSONB;
BEGIN
  -- Run archive job
  SELECT archive_old_import_logs() INTO v_archive_result;

  -- Run delete job
  SELECT delete_old_import_logs() INTO v_delete_result;

  RETURN jsonb_build_object(
    'success', true,
    'archive', v_archive_result,
    'delete', v_delete_result,
    'run_at', NOW()
  );
END;
$$;


