CREATE TABLE IF NOT EXISTS "public"."section_plan_situation_snippets" (
    "snippet_id" bigint NOT NULL,
    "section_plan_id" bigint NOT NULL,
    "status_summary" "text",
    "key_event" "text",
    "agreement_expiry_override" "date",
    "strategic_context" "text",
    "workforce_summary" "text",
    "notes" "text",
    "derived_from_campaign_situation" boolean DEFAULT false NOT NULL,
    "ai_generated" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."section_plan_situation_snippets" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_section_situation_snippet"("p_section_plan_id" bigint) RETURNS "public"."section_plan_situation_snippets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign_id INT;
  v_csa RECORD;
  v_expiry DATE;
  v_workforce TEXT;
  v_status TEXT;
  v_key_event TEXT;
  v_strategic TEXT;
  v_result section_plan_situation_snippets;
BEGIN
  SELECT campaign_id INTO v_campaign_id FROM section_plans WHERE section_plan_id = p_section_plan_id;
  IF v_campaign_id IS NULL THEN RAISE EXCEPTION 'Section plan % not found', p_section_plan_id; END IF;

  SELECT employer_state_notes, strategic_context_summary, bargaining_phase_state, employer_ballot_intent, nerr_status, nerr_issued_at INTO v_csa
  FROM campaign_situation_analyses
  WHERE campaign_id = v_campaign_id AND COALESCE(is_current, true) = true
  ORDER BY version DESC NULLS LAST, created_at DESC LIMIT 1;

  v_status := COALESCE(NULLIF(v_csa.employer_state_notes, ''), '');
  v_strategic := COALESCE(NULLIF(v_csa.strategic_context_summary, ''), '');
  v_key_event := NULLIF(TRIM(BOTH ' · ' FROM CONCAT_WS(' · ',
      NULLIF(v_csa.bargaining_phase_state, ''),
      NULLIF(v_csa.employer_ballot_intent, ''),
      CASE WHEN v_csa.nerr_status IS NOT NULL AND v_csa.nerr_status <> '' THEN 'NERR: ' || v_csa.nerr_status || COALESCE(' (' || v_csa.nerr_issued_at::TEXT || ')', '') ELSE NULL END
    )), '');

  SELECT MAX(a.expiry_date) INTO v_expiry FROM campaign_agreements ca JOIN agreements a ON a.agreement_id = ca.agreement_id WHERE ca.campaign_id = v_campaign_id;

  SELECT FORMAT('%s workers in scope · %s allocated · %s with contact · %s rated · %s OUs missing leaders', universe_size, workers_allocated, workers_with_contact, workers_with_rating, ous_missing_leaders)
    INTO v_workforce FROM v_campaign_foundational_readiness WHERE campaign_id = v_campaign_id;

  INSERT INTO section_plan_situation_snippets (section_plan_id, status_summary, key_event, agreement_expiry_override, strategic_context, workforce_summary, derived_from_campaign_situation)
  VALUES (p_section_plan_id, v_status, v_key_event, NULL, v_strategic, v_workforce, TRUE)
  ON CONFLICT (section_plan_id) DO UPDATE
    SET status_summary = COALESCE(EXCLUDED.status_summary, section_plan_situation_snippets.status_summary),
        key_event = COALESCE(EXCLUDED.key_event, section_plan_situation_snippets.key_event),
        strategic_context = COALESCE(EXCLUDED.strategic_context, section_plan_situation_snippets.strategic_context),
        workforce_summary = COALESCE(EXCLUDED.workforce_summary, section_plan_situation_snippets.workforce_summary),
        derived_from_campaign_situation = TRUE, updated_at = now()
  RETURNING * INTO v_result;

  RETURN v_result;
END;
$$;


