CREATE OR REPLACE FUNCTION "public"."set_worker_union_membership_pending"("p_worker_id" integer, "p_source" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_pending_type_id    INTEGER;
  v_financial_type_id  INTEGER;
  v_current_type_id    INTEGER;
  v_campaign_id        INTEGER;
BEGIN
  SELECT union_membership_type_id INTO v_pending_type_id
    FROM union_membership_types WHERE type_name = 'member_pending' LIMIT 1;

  SELECT union_membership_type_id INTO v_financial_type_id
    FROM union_membership_types WHERE type_name = 'financial_member' LIMIT 1;

  SELECT union_membership_type_id INTO v_current_type_id
    FROM workers WHERE worker_id = p_worker_id;

  IF v_current_type_id = v_financial_type_id THEN
    RETURN jsonb_build_object('status', 'already_financial', 'worker_id', p_worker_id);
  END IF;

  IF v_current_type_id = v_pending_type_id THEN
    RETURN jsonb_build_object('status', 'already_pending', 'worker_id', p_worker_id);
  END IF;

  UPDATE workers
    SET union_membership_type_id = v_pending_type_id,
        join_date                = COALESCE(join_date, CURRENT_DATE),
        updated_at               = NOW()
    WHERE worker_id = p_worker_id;

  INSERT INTO worker_membership_transitions
    (worker_id, from_type_id, to_type_id, source, actor_id, context, occurred_at)
  VALUES
    (p_worker_id, v_current_type_id, v_pending_type_id, p_source, p_actor_id, p_context, NOW());

  v_campaign_id := (p_context->>'campaign_id')::INTEGER;
  IF v_campaign_id IS NOT NULL THEN
    UPDATE worker_campaign_connections
      SET joined_at = COALESCE(joined_at, NOW())
      WHERE worker_id = p_worker_id AND campaign_id = v_campaign_id;
  END IF;

  RETURN jsonb_build_object('status', 'updated', 'worker_id', p_worker_id);
END;
$$;


ALTER FUNCTION "public"."set_worker_union_membership_pending"("p_worker_id" integer, "p_source" "text", "p_actor_id" "uuid", "p_context" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_worker_union_membership_pending"("p_worker_id" integer, "p_source" "text", "p_actor_id" "uuid", "p_context" "jsonb") IS 'Channel-agnostic RPC: transitions a worker to member_pending if not already at that level or higher. Idempotent. Writes audit row to worker_membership_transitions.';



CREATE OR REPLACE FUNCTION "public"."skip_call_list_item_for_share"("p_item_id" integer, "p_list_id" integer, "p_session_label" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_max_sort INTEGER;
  v_updated  BOOLEAN;
BEGIN
  SELECT COALESCE(MAX(sort_order), 0)
  INTO   v_max_sort
  FROM   call_list_items
  WHERE  list_id = p_list_id;

  UPDATE call_list_items SET
    status                   = 'pending',
    claimed_at               = NULL,
    claimed_by_session_label = NULL,
    claimed_by_worker_id     = NULL,
    claimed_by_share_token_id = NULL,
    skip_count               = skip_count + 1,
    sort_order               = v_max_sort + 1,
    updated_at               = now()
  WHERE item_id  = p_item_id
    AND list_id  = p_list_id
    AND (
      (status = 'in_progress' AND claimed_by_session_label = p_session_label)
      OR
      status = 'pending'
    )
  RETURNING true
  INTO v_updated;

  RETURN COALESCE(v_updated, false);
END;
$$;


ALTER FUNCTION "public"."skip_call_list_item_for_share"("p_item_id" integer, "p_list_id" integer, "p_session_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."split_campaign_organising_unit"("p_parent_ou_id" integer, "p_sub_units" "jsonb", "p_assignments" "jsonb", "p_keep_in_parent" boolean DEFAULT true) RETURNS TABLE("sub_index" integer, "ou_id" integer)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_campaign_id      INT;
  v_parent_parent_id INT;
  v_gp_is_container  BOOLEAN;
  v_max_display      INT;
  v_record           JSONB;
  v_idx              INT;
  v_new_ou_id        INT;
  v_assigned_workers INT[] := ARRAY[]::INT[];
BEGIN
  SELECT cou.campaign_id, cou.parent_ou_id
    INTO v_campaign_id, v_parent_parent_id
  FROM campaign_organising_units AS cou
  WHERE cou.ou_id = p_parent_ou_id;

  IF v_campaign_id IS NULL THEN
    RAISE EXCEPTION 'parent OU % not found', p_parent_ou_id;
  END IF;

  IF v_parent_parent_id IS NOT NULL THEN
    SELECT is_group_container
      INTO v_gp_is_container
    FROM campaign_organising_units
    WHERE ou_id = v_parent_parent_id;

    IF NOT COALESCE(v_gp_is_container, FALSE) THEN
      RAISE EXCEPTION
        'cannot split OU % - it is a sub-unit of a non-container parent (%); only top-level OUs or units inside a group container may be split',
        p_parent_ou_id, v_parent_parent_id;
    END IF;
  END IF;

  IF jsonb_typeof(p_sub_units) <> 'array' OR jsonb_array_length(p_sub_units) = 0 THEN
    RAISE EXCEPTION 'p_sub_units must be a non-empty JSONB array';
  END IF;

  SELECT COALESCE(MAX(cou2.display_order), -1) + 1
    INTO v_max_display
  FROM campaign_organising_units AS cou2
  WHERE cou2.campaign_id = v_campaign_id;

  CREATE TEMP TABLE _split_result (sub_index INT, new_ou_id INT) ON COMMIT DROP;

  FOR v_idx IN 0 .. jsonb_array_length(p_sub_units) - 1 LOOP
    v_record := p_sub_units -> v_idx;
    IF v_record IS NULL OR (v_record ->> 'name') IS NULL THEN
      RAISE EXCEPTION 'p_sub_units[%] missing required "name" field', v_idx;
    END IF;

    INSERT INTO campaign_organising_units AS ins (
      campaign_id, parent_ou_id, ou_type, name,
      total_workers_estimated, unit_basis, display_order, source
    )
    VALUES (
      v_campaign_id,
      p_parent_ou_id,
      COALESCE(v_record ->> 'ou_type', 'custom'),
      v_record ->> 'name',
      NULLIF((v_record ->> 'total_workers_estimated'), '')::INT,
      COALESCE(v_record -> 'unit_basis', jsonb_build_object('parent_ou_id', p_parent_ou_id)),
      v_max_display + v_idx,
      'manual'
    )
    RETURNING ins.ou_id INTO v_new_ou_id;

    INSERT INTO _split_result (sub_index, new_ou_id) VALUES (v_idx, v_new_ou_id);
  END LOOP;

  IF jsonb_typeof(p_assignments) = 'array' AND jsonb_array_length(p_assignments) > 0 THEN
    INSERT INTO campaign_worker_ou (ou_id, worker_id, is_primary, assignment_source)
    SELECT sr.new_ou_id, (a ->> 'worker_id')::INT, false, 'manual'
    FROM jsonb_array_elements(p_assignments) AS a
    JOIN _split_result sr ON sr.sub_index = (a ->> 'sub_index')::INT
    ON CONFLICT (ou_id, worker_id) DO NOTHING;

    SELECT ARRAY_AGG(DISTINCT (a ->> 'worker_id')::INT)
      INTO v_assigned_workers
    FROM jsonb_array_elements(p_assignments) AS a;
  END IF;

  IF p_keep_in_parent = false AND v_assigned_workers IS NOT NULL THEN
    DELETE FROM campaign_worker_ou AS cwo
    WHERE cwo.ou_id = p_parent_ou_id
      AND cwo.worker_id = ANY(v_assigned_workers);
  END IF;

  RETURN QUERY SELECT sr.sub_index, sr.new_ou_id FROM _split_result sr ORDER BY sr.sub_index;
END;
$$;


ALTER FUNCTION "public"."split_campaign_organising_unit"("p_parent_ou_id" integer, "p_sub_units" "jsonb", "p_assignments" "jsonb", "p_keep_in_parent" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."split_campaign_organising_unit"("p_parent_ou_id" integer, "p_sub_units" "jsonb", "p_assignments" "jsonb", "p_keep_in_parent" boolean) IS 'Atomic split of a top-level OU (or a group-member unit) into N sub-units with optional bulk worker assignments. Sub-units are created with parent_ou_id pointing back to the parent. When keep_in_parent is false, any worker that ended up in at least one sub-unit is removed from the parent. p_sub_units shape: [{name, ou_type, unit_basis?, total_workers_estimated?}]. p_assignments shape: [{sub_index, worker_id}].';



CREATE OR REPLACE FUNCTION "public"."sync_agreement_expired_status_by_date"() RETURNS integer
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  WITH updated AS (
    UPDATE public.agreements
    SET status = 'Expired'
    WHERE expiry_date IS NOT NULL
      AND expiry_date < CURRENT_DATE
      AND status = 'Current'
    RETURNING agreement_id
  )
  SELECT count(*)::int FROM updated;
$$;


