CREATE OR REPLACE FUNCTION "public"."sync_call_list_current_script"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_current THEN
      UPDATE call_lists
      SET script_id = NULL
      WHERE list_id = OLD.list_id
        AND script_id = OLD.script_id;
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.is_current THEN
    -- Demote any other current rows for this list.
    UPDATE call_list_scripts
    SET is_current = false
    WHERE list_id = NEW.list_id
      AND script_id <> NEW.script_id
      AND is_current = true;

    UPDATE call_lists
    SET script_id = NEW.script_id
    WHERE list_id = NEW.list_id;
  ELSIF TG_OP = 'UPDATE' AND OLD.is_current AND NOT NEW.is_current THEN
    -- Row demoted; clear the pointer only if it still referenced this script.
    UPDATE call_lists
    SET script_id = NULL
    WHERE list_id = NEW.list_id
      AND script_id = NEW.script_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_call_list_current_script"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_campaign_replaced_agreement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  cid INT;
  primary_aid INT;
BEGIN
  cid := COALESCE(NEW.campaign_id, OLD.campaign_id);

  SELECT agreement_id INTO primary_aid
  FROM campaign_agreements
  WHERE campaign_id = cid
    AND relationship_type = 'replaced'
    AND is_primary = true
  LIMIT 1;

  UPDATE campaigns
  SET replaced_agreement_id = primary_aid
  WHERE campaign_id = cid
    AND replaced_agreement_id IS DISTINCT FROM primary_aid;

  RETURN COALESCE(NEW, OLD);
END;
$$;


