CREATE OR REPLACE FUNCTION "public"."tg_activity_event_evaluate_sequences"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  rec RECORD; v_match_count INT; v_total_for_activity INT; v_ratio NUMERIC;
BEGIN
  IF NEW.is_concluded IS NOT TRUE THEN RETURN NEW; END IF;
  FOR rec IN
    SELECT t.trigger_id, t.step_id, t.event_kind, t.outcome, t.threshold_kind, t.threshold_value, st.source_activity_id
    FROM activity_sequence_triggers t
    JOIN activity_sequence_steps st ON st.step_id = t.step_id
    JOIN activity_sequences s ON s.sequence_id = st.sequence_id
    WHERE s.is_active = TRUE AND st.source_activity_id = NEW.activity_id AND t.event_kind = NEW.event_kind
  LOOP
    IF EXISTS (SELECT 1 FROM activity_sequence_runs WHERE step_id = rec.step_id AND state IN ('queued','materialised')) THEN CONTINUE; END IF;
    IF rec.outcome IS NOT NULL AND rec.outcome <> '' THEN
      IF NOT (NEW.outcome ? rec.outcome OR (NEW.outcome ->> 'outcome') = rec.outcome OR (NEW.outcome ->> 'kind') = rec.outcome) THEN CONTINUE; END IF;
    END IF;
    IF rec.threshold_kind = 'any' THEN
      INSERT INTO activity_sequence_runs(step_id, state) VALUES (rec.step_id, 'queued'); CONTINUE;
    END IF;
    SELECT COUNT(*) INTO v_match_count FROM activity_events ev
      WHERE ev.activity_id = rec.source_activity_id AND ev.event_kind = rec.event_kind AND ev.is_concluded = TRUE
        AND (rec.outcome IS NULL OR rec.outcome = '' OR ev.outcome ? rec.outcome OR (ev.outcome ->> 'outcome') = rec.outcome OR (ev.outcome ->> 'kind') = rec.outcome);
    IF rec.threshold_kind = 'absolute_count' THEN
      IF v_match_count >= COALESCE(rec.threshold_value, 1) THEN INSERT INTO activity_sequence_runs(step_id, state) VALUES (rec.step_id, 'queued'); END IF;
    ELSIF rec.threshold_kind = 'percent_of_target' THEN
      SELECT COUNT(*) INTO v_total_for_activity FROM activity_events ev WHERE ev.activity_id = rec.source_activity_id;
      IF v_total_for_activity > 0 THEN
        v_ratio := v_match_count::NUMERIC / v_total_for_activity::NUMERIC;
        IF v_ratio >= COALESCE(rec.threshold_value, 1) / 100.0 THEN INSERT INTO activity_sequence_runs(step_id, state) VALUES (rec.step_id, 'queued'); END IF;
      END IF;
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tg_activity_event_evaluate_sequences"() OWNER TO "postgres";


