CREATE OR REPLACE FUNCTION "public"."transition_to_post_settlement"("p_campaign_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_phase  campaign_phase_enum;
  v_endorsement_ok BOOLEAN;
  v_transitioned_at TIMESTAMPTZ;
BEGIN
  -- 1. Verify campaign phase ──────────────────────────────────────────────────
  SELECT current_phase
    INTO v_current_phase
    FROM campaigns
   WHERE campaign_id = p_campaign_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success',     false,
      'error',       'campaign_not_found',
      'campaign_id', p_campaign_id
    );
  END IF;

  IF v_current_phase <> 'bargaining_to_win' THEN
    RETURN jsonb_build_object(
      'success',        false,
      'error',          'wrong_phase',
      'current_phase',  v_current_phase::text,
      'campaign_id',    p_campaign_id
    );
  END IF;

  -- 2. Verify final EBA endorsement ─────────────────────────────────────────
  SELECT EXISTS (
    SELECT 1
      FROM member_endorsement_votes
     WHERE campaign_id = p_campaign_id
       AND vote_kind   = 'final_eba'
       AND outcome     = 'yes'
  ) INTO v_endorsement_ok;

  IF NOT v_endorsement_ok THEN
    RETURN jsonb_build_object(
      'success',     false,
      'error',       'no_final_eba_endorsement',
      'campaign_id', p_campaign_id
    );
  END IF;

  -- 3. Transition campaign phase ─────────────────────────────────────────────
  v_transitioned_at := now();

  UPDATE campaigns
     SET current_phase = 'post_settlement'
   WHERE campaign_id = p_campaign_id;

  -- 4. Close open decision points ───────────────────────────────────────────
  UPDATE bargaining_decision_points
     SET resolution  = 'settled',
         resolved_at = v_transitioned_at,
         notes       = COALESCE(
                         NULLIF(notes, ''),
                         'Closed by post-settlement transition'
                       )
   WHERE campaign_id  = p_campaign_id
     AND (resolution IS NULL OR resolution = 'pending');

  -- 5. Return success ────────────────────────────────────────────────────────
  RETURN jsonb_build_object(
    'success',          true,
    'campaign_id',      p_campaign_id,
    'transitioned_at',  v_transitioned_at
  );
END;
$$;


ALTER FUNCTION "public"."transition_to_post_settlement"("p_campaign_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transition_to_post_settlement"("p_campaign_id" integer) IS 'Transitions a campaign from bargaining_to_win to post_settlement. Verifies phase and that a final_eba vote with outcome=yes exists. Closes any pending bargaining_decision_points and returns a JSONB result.';



