CREATE OR REPLACE FUNCTION "public"."trigger_refresh_gate_criteria_on_worker_agreement_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  PERFORM pg_notify(
    'gate_criteria_refresh',
    jsonb_build_object(
      'reason', 'worker_agreement_changed',
      'worker_id', NEW.worker_id,
      'agreement_id', NEW.agreement_id,
      'changed_at', NOW()
    )
  );
  RETURN NEW;
END;
$$;


