CREATE OR REPLACE VIEW "public"."agreements_view" AS
 SELECT "a"."agreement_id",
    "a"."decision_no",
    "a"."agreement_name",
    "a"."short_name",
    "a"."sector_id",
    "a"."employer_id",
    "a"."industry_classification",
    "a"."date_of_decision",
    "a"."commencement_date",
    "a"."expiry_date",
    "a"."status",
    "a"."is_greenfield",
    "a"."is_variation",
    "a"."fwc_link",
    "a"."supersedes_id",
    "a"."variation_of_id",
    "a"."notes",
    "a"."source_sheet",
    "a"."created_at",
    "a"."updated_at",
    "s"."sector_name",
    "e"."employer_name",
    "e"."trading_name" AS "employer_trading_name",
    ( SELECT "string_agg"(("u"."union_code")::"text", ', '::"text" ORDER BY "au"."is_primary" DESC, ("u"."union_code")::"text") AS "string_agg"
           FROM ("public"."agreement_unions" "au"
             JOIN "public"."unions" "u" ON (("u"."union_id" = "au"."union_id")))
          WHERE ("au"."agreement_id" = "a"."agreement_id")) AS "union_coverage",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."agreement_worksites" "aw"
          WHERE ("aw"."agreement_id" = "a"."agreement_id")) AS "worksite_count",
        CASE
            WHEN ("a"."expiry_date" IS NULL) THEN NULL::integer
            WHEN ("a"."expiry_date" < CURRENT_DATE) THEN 0
            ELSE ("a"."expiry_date" - CURRENT_DATE)
        END AS "days_until_expiry"
   FROM (("public"."agreements" "a"
     LEFT JOIN "public"."sectors" "s" ON (("s"."sector_id" = "a"."sector_id")))
