CREATE TABLE IF NOT EXISTS "public"."campaign_activity_ratings" (
    "rating_id" integer NOT NULL,
    "activity_id" integer NOT NULL,
    "worker_id" integer NOT NULL,
    "rating" integer,
    "binary_value" character varying(30),
    "notes" "text",
    "rated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source" character varying(20) DEFAULT 'staff'::character varying NOT NULL,
    "rated_by_user_id" "uuid",
    "rating_phase" character varying(10) DEFAULT 'actual'::character varying NOT NULL,
    "event_id" integer,
    "assessment_type_override" character varying(20),
    "import_batch_id" integer,
    CONSTRAINT "campaign_activity_ratings_rating_check" CHECK ((("rating" >= 1) AND ("rating" <= 5))),
    CONSTRAINT "campaign_activity_ratings_source_check" CHECK ((("source")::"text" = ANY ((ARRAY['call_outcome'::character varying, 'phone_call_live'::character varying, 'phone_call_share_link'::character varying, 'door_knock'::character varying, 'task_assignment'::character varying, 'task_completion'::character varying, 'task_take'::character varying, 'staff'::character varying, 'leader_form'::character varying, 'sms'::character varying, 'email'::character varying, 'petition'::character varying, 'meeting'::character varying, 'an_sync'::character varying, 'an_report_import'::character varying, 'sms_chat'::character varying, 'sms_survey'::character varying, 'sms_inbound'::character varying])::"text"[]))),
    CONSTRAINT "car_assessment_type_override_chk" CHECK ((("assessment_type_override" IS NULL) OR (("assessment_type_override")::"text" = ANY ((ARRAY['hard'::character varying, 'self_assessed'::character varying, 'organiser_assessed'::character varying, 'activist_assessed'::character varying])::"text"[])))),
    CONSTRAINT "car_rating_or_binary_chk" CHECK ((("rating" IS NOT NULL) OR ("binary_value" IS NOT NULL))),
    CONSTRAINT "car_rating_phase_chk" CHECK ((("rating_phase")::"text" = ANY ((ARRAY['expected'::character varying, 'actual'::character varying])::"text"[])))
);


ALTER TABLE "public"."campaign_activity_ratings" OWNER TO "postgres";


COMMENT ON COLUMN "public"."campaign_activity_ratings"."source" IS 'Which pathway recorded the rating. SMS is split three ways: ''sms_chat'' = staff tapped a chip in the inbox/chat sidebar, ''sms_survey'' = a survey answer mapped to a rating, ''sms_inbound'' = a keyword-mapped conversational reply. ''sms'' remains a legacy value for rows written before the split and is no longer emitted by any producer.';



COMMENT ON COLUMN "public"."campaign_activity_ratings"."rating_phase" IS 'expected = pre-event / soft rating (intention). actual = post-event / hard outcome. Defaults to actual for activities not bound to a scheduled event.';



COMMENT ON COLUMN "public"."campaign_activity_ratings"."event_id" IS 'Optional link to activity_events. NULL means the rating is against the activity in general, not a specific instance.';



COMMENT ON COLUMN "public"."campaign_activity_ratings"."assessment_type_override" IS 'Per-rating override of the activity-level assessment_type. The leader webform always sets this to ''activist_assessed'' regardless of the parent activity''s default. Reporting joins prefer override IS NOT NULL and fall back to campaign_activities.assessment_type otherwise.';



CREATE TABLE IF NOT EXISTS "public"."campaign_stage_plans" (
    "plan_id" integer NOT NULL,
    "campaign_id" integer NOT NULL,
    "stage_number" integer NOT NULL,
    "stage_name" character varying NOT NULL,
    "status" character varying DEFAULT 'draft'::character varying NOT NULL,
    "planned_start_date" "date",
    "planned_end_date" "date",
    "actual_start_date" "date",
    "actual_end_date" "date",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "workplan_status" character varying(20) DEFAULT 'not_started'::character varying,
    "step_overrides" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "phase" "public"."campaign_phase_enum" DEFAULT 'preparing_to_bargain'::"public"."campaign_phase_enum" NOT NULL,
    CONSTRAINT "campaign_stage_plans_stage_number_check" CHECK ((("stage_number" >= 0) AND ("stage_number" <= 11))),
    CONSTRAINT "campaign_stage_plans_workplan_status_check" CHECK ((("workplan_status")::"text" = ANY ((ARRAY['not_started'::character varying, 'in_progress'::character varying, 'completed'::character varying])::"text"[])))
);


ALTER TABLE "public"."campaign_stage_plans" OWNER TO "postgres";


COMMENT ON COLUMN "public"."campaign_stage_plans"."stage_number" IS '0 = Standalone activities (ad-hoc ambitions); 1–6 = P2W; 7–11 = B2W.';



COMMENT ON COLUMN "public"."campaign_stage_plans"."step_overrides" IS 'Per-stage map of P2W step id (ambitions / where-to-play / theory / capacities / management) to override (auto | force-complete | force-incomplete). Missing keys imply auto. Persists organiser overrides across browsers and users; replaces the prior localStorage-only useP2wStepOverrides hook.';



COMMENT ON COLUMN "public"."campaign_stage_plans"."phase" IS 'Which bargaining lifecycle phase this stage plan belongs to. Invariant: preparing_to_bargain IFF stage_number BETWEEN 1 AND 6; bargaining_to_win IFF stage_number BETWEEN 7 AND 11. Enforced by trigger in 20260510120000_stage_phase_invariants.sql.';



CREATE TABLE IF NOT EXISTS "public"."plan_ambitions" (
    "ambition_id" integer NOT NULL,
    "plan_id" integer,
    "ambition_option_id" integer,
