    "target_unit" character varying,
    "target_date" "date",
    "is_achieved" boolean DEFAULT false,
    "achieved_date" "date",
    "sort_order" integer DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "is_hard_gate" boolean DEFAULT false NOT NULL,
    "current_value" character varying,
    "evidence_notes" "text",
    "metric_type" character varying,
    "target_value_max" character varying,
    "target_date_user_overridden" boolean DEFAULT false NOT NULL,
    "is_system_default" boolean DEFAULT false NOT NULL,
    "ambition_scope" character varying(20) DEFAULT 'worker_assessable'::character varying NOT NULL,
    "current_value_overridden" boolean DEFAULT false NOT NULL,
    "current_value_override_reason" "text",
    "parent_campaign_ambition_id" integer,
    "section_plan_id" bigint,
    CONSTRAINT "plan_ambitions_owner_xor_chk" CHECK ((("plan_id" IS NOT NULL) <> ("section_plan_id" IS NOT NULL))),
    CONSTRAINT "plan_ambitions_scope_chk" CHECK ((("ambition_scope")::"text" = ANY ((ARRAY['campaign_setup'::character varying, 'worker_assessable'::character varying])::"text"[])))
);


ALTER TABLE "public"."plan_ambitions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."plan_ambitions"."metric_type" IS 'Override: percentage, count, boolean, date, range, text';



COMMENT ON COLUMN "public"."plan_ambitions"."target_value_max" IS 'Upper bound when metric_type is range';



COMMENT ON COLUMN "public"."plan_ambitions"."ambition_scope" IS 'campaign_setup = not tracked per worker (lists, unit identification, timelines). worker_assessable = aggregated from campaign_activity_ratings via activity_ambitions.';



COMMENT ON COLUMN "public"."plan_ambitions"."current_value_overridden" IS 'TRUE when staff have manually set current_value rather than relying on the derived value from ambition_progress. Requires current_value_override_reason to be set in the UI.';



COMMENT ON COLUMN "public"."plan_ambitions"."parent_campaign_ambition_id" IS 'Optional FK to campaign_ambitions: when set, this stage ambition contributes to the named campaign-wide goal and is included in campaign_ambition_progress.';



CREATE OR REPLACE VIEW "public"."ambition_activity_contribution" WITH ("security_invoker"='true') AS
 SELECT "sp"."campaign_id",
    "pa"."ambition_id",
    "car"."activity_id",
    "count"(*) AS "rating_count",
    "count"(*) FILTER (WHERE ("car"."rating" = ANY (ARRAY[1, 2]))) AS "supportive_count",
    "count"(*) FILTER (WHERE ("car"."rating" = ANY (ARRAY[4, 5]))) AS "opposed_count",
    "count"(DISTINCT "car"."worker_id") AS "unique_workers",
    "max"("car"."rated_at") AS "latest_rated_at",
    "round"("avg"("car"."rating"), 2) AS "avg_rating"
   FROM ((("public"."plan_ambitions" "pa"
     JOIN "public"."campaign_stage_plans" "sp" ON (("sp"."plan_id" = "pa"."plan_id")))
     JOIN "public"."activity_ambitions" "aa" ON (("aa"."plan_ambition_id" = "pa"."ambition_id")))
     JOIN "public"."campaign_activity_ratings" "car" ON (("car"."activity_id" = "aa"."activity_id")))
  WHERE (("pa"."ambition_scope")::"text" = 'worker_assessable'::"text")
  GROUP BY "sp"."campaign_id", "pa"."ambition_id", "car"."activity_id";


ALTER VIEW "public"."ambition_activity_contribution" OWNER TO "postgres";


COMMENT ON VIEW "public"."ambition_activity_contribution" IS 'Per (ambition, activity) cell: how many ratings the activity contributed to the ambition, their spread, and when. Used by UI to show which activities are driving progress on each ambition.';



