CREATE OR REPLACE VIEW "public"."worker_ambition_rating" WITH ("security_invoker"='true') AS
 WITH "ranked" AS (
         SELECT "sp"."campaign_id",
            "pa"."ambition_id" AS "plan_ambition_id",
            "car"."worker_id",
            "car"."rating",
            "car"."binary_value",
            "car"."rating_phase",
            "car"."event_id",
            "car"."rated_at",
            "car"."source",
            "car"."activity_id" AS "source_activity_id",
            "row_number"() OVER (PARTITION BY "sp"."campaign_id", "pa"."ambition_id", "car"."worker_id" ORDER BY
                CASE "car"."rating_phase"
                    WHEN 'actual'::"text" THEN 0
                    ELSE 1
                END, "car"."rated_at" DESC NULLS LAST) AS "rn"
           FROM ((("public"."campaign_activity_ratings" "car"
             JOIN "public"."activity_ambitions" "aa" ON (("aa"."activity_id" = "car"."activity_id")))
             JOIN "public"."plan_ambitions" "pa" ON (("pa"."ambition_id" = "aa"."plan_ambition_id")))
             JOIN "public"."campaign_stage_plans" "sp" ON (("sp"."plan_id" = "pa"."plan_id")))
          WHERE (("pa"."ambition_scope")::"text" = 'worker_assessable'::"text")
        )
 SELECT "campaign_id",
    "plan_ambition_id",
    "worker_id",
    "rating",
    "binary_value",
    "rating_phase",
    "event_id",
    "rated_at",
    "source",
    "source_activity_id"
   FROM "ranked"
  WHERE ("rn" = 1);


ALTER VIEW "public"."worker_ambition_rating" OWNER TO "postgres";


COMMENT ON VIEW "public"."worker_ambition_rating" IS 'Current resolved rating per (campaign, ambition, worker). Picks most recent actual rating across all linked activities, falling back to expected if no actual exists. Only returns rows for worker_assessable ambitions.';



CREATE OR REPLACE VIEW "public"."ambition_progress" WITH ("security_invoker"='true') AS
 WITH "members" AS (
         SELECT "sp"."campaign_id",
            "pa"."ambition_id",
            "cwm"."worker_id"
           FROM (("public"."plan_ambitions" "pa"
             JOIN "public"."campaign_stage_plans" "sp" ON (("sp"."plan_id" = "pa"."plan_id")))
             JOIN "public"."campaign_worker_membership" "cwm" ON (("cwm"."campaign_id" = "sp"."campaign_id")))
          WHERE (("pa"."ambition_scope")::"text" = 'worker_assessable'::"text")
        ), "joined" AS (
         SELECT "m"."campaign_id",
            "m"."ambition_id",
            "m"."worker_id",
            "war"."rating",
            "war"."binary_value",
            "war"."rated_at"
           FROM ("members" "m"
             LEFT JOIN "public"."worker_ambition_rating" "war" ON ((("war"."campaign_id" = "m"."campaign_id") AND ("war"."plan_ambition_id" = "m"."ambition_id") AND ("war"."worker_id" = "m"."worker_id"))))
        )
 SELECT "campaign_id",
    "ambition_id",
    "count"(*) AS "universe",
    "count"(*) FILTER (WHERE ("rating" = 1)) AS "rated_1",
    "count"(*) FILTER (WHERE ("rating" = 2)) AS "rated_2",
    "count"(*) FILTER (WHERE ("rating" = 3)) AS "rated_3",
    "count"(*) FILTER (WHERE ("rating" = 4)) AS "rated_4",
    "count"(*) FILTER (WHERE ("rating" = 5)) AS "rated_5",
    "count"(*) FILTER (WHERE (("rating" IS NULL) AND ("binary_value" IS NULL))) AS "unassessed",
    "count"(*) FILTER (WHERE ("rating" = ANY (ARRAY[1, 2]))) AS "supportive",
    "count"(*) FILTER (WHERE ("rating" = ANY (ARRAY[4, 5]))) AS "opposed",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((100.0 * ("count"(*) FILTER (WHERE ("rating" = ANY (ARRAY[1, 2]))))::numeric) / ("count"(*))::numeric), 1)
            ELSE (0)::numeric
        END AS "supportive_pct",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((100.0 * ("count"(*) FILTER (WHERE (("rating" IS NULL) AND ("binary_value" IS NULL))))::numeric) / ("count"(*))::numeric), 1)
            ELSE (0)::numeric
        END AS "unassessed_pct",
    "max"("rated_at") AS "last_rated_at"
   FROM "joined"
  GROUP BY "campaign_id", "ambition_id";


ALTER VIEW "public"."ambition_progress" OWNER TO "postgres";


COMMENT ON VIEW "public"."ambition_progress" IS 'Per ambition, counts by rating bucket (1..5 + unassessed), supportive (1+2) percentage, opposed (4+5) percentage, and last update time. Universe = campaign_worker_membership.';



