    "caller_session_worker_id" integer,
    "outcome_classification" character varying(40),
    CONSTRAINT "call_attempts_call_disposition_check" CHECK ((("call_disposition" IS NULL) OR (("call_disposition")::"text" = ANY ((ARRAY['completed_positive'::character varying, 'completed_neutral'::character varying, 'completed_negative'::character varying, 'partial_hung_up'::character varying, 'partial_asked_callback'::character varying, 'referred_to_other'::character varying, 'removed_from_campaign'::character varying, 'no_longer_in_universe'::character varying])::"text"[])))),
    CONSTRAINT "call_attempts_cta_response_check" CHECK ((("cta_response" IS NULL) OR (("cta_response")::"text" = ANY ((ARRAY['accepted'::character varying, 'considering'::character varying, 'declined'::character varying, 'not_reached'::character varying])::"text"[])))),
    CONSTRAINT "call_attempts_dial_disposition_check" CHECK ((("dial_disposition")::"text" = ANY ((ARRAY['connected'::character varying, 'no_answer'::character varying, 'voicemail_left'::character varying, 'voicemail_no_message'::character varying, 'busy'::character varying, 'disconnected'::character varying, 'wrong_number'::character varying, 'do_not_call'::character varying, 'callback_requested'::character varying])::"text"[]))),
    CONSTRAINT "call_attempts_outcome_classification_check" CHECK ((("outcome_classification" IS NULL) OR (("outcome_classification")::"text" = ANY ((ARRAY['agreed_to_join'::character varying, 'interested_undecided'::character varying, 'interested_callback'::character varying, 'not_interested'::character varying, 'declined_explicitly'::character varying, 'wrong_number'::character varying, 'do_not_call'::character varying, 'unable_to_reach'::character varying, 'callback_later'::character varying, 'voicemail_left'::character varying, 'referred_to_other_org'::character varying, 'existing_member_supportive'::character varying, 'existing_member_neutral'::character varying, 'other'::character varying])::"text"[])))),
    CONSTRAINT "call_attempts_support_level_assessed_check" CHECK ((("support_level_assessed" IS NULL) OR (("support_level_assessed")::"text" = ANY ((ARRAY['strong_supporter'::character varying, 'supporter'::character varying, 'neutral'::character varying, 'unsupportive'::character varying, 'hostile'::character varying])::"text"[]))))
);


