CREATE OR REPLACE VIEW "public"."call_campaign_summary" AS
 SELECT "cl"."campaign_id",
    "cl"."list_id",
    "cl"."name" AS "list_name",
    "cl"."status" AS "list_status",
    "cl"."total_items",
    "cl"."completed_items",
    "cl"."priority_strategy",
    "cs"."script_id",
    "cs"."title" AS "script_title",
    "count"(DISTINCT "ca"."attempt_id") AS "total_attempts",
    "count"(DISTINCT "cli"."worker_id") FILTER (WHERE ("ca"."attempt_id" IS NOT NULL)) AS "unique_contacts_attempted",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = 'connected'::"text")) AS "connected_count",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = 'no_answer'::"text")) AS "no_answer_count",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = ANY ((ARRAY['voicemail_left'::character varying, 'voicemail_no_message'::character varying])::"text"[]))) AS "voicemail_count",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = ANY ((ARRAY['disconnected'::character varying, 'wrong_number'::character varying])::"text"[]))) AS "bad_number_count",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = 'do_not_call'::"text")) AS "dnc_count",
        CASE
            WHEN ("count"("ca"."attempt_id") > 0) THEN "round"(((100.0 * ("count"("ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = 'connected'::"text")))::numeric) / ("count"("ca"."attempt_id"))::numeric), 1)
            ELSE (0)::numeric
        END AS "connect_rate_pct",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."cta_response")::"text" = 'accepted'::"text")) AS "cta_accepted",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."cta_response")::"text" = 'considering'::"text")) AS "cta_considering",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."cta_response")::"text" = 'declined'::"text")) AS "cta_declined",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."call_disposition")::"text" = 'completed_positive'::"text")) AS "positive_calls",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."call_disposition")::"text" = 'completed_neutral'::"text")) AS "neutral_calls",
    "count"("ca"."attempt_id") FILTER (WHERE (("ca"."call_disposition")::"text" = 'completed_negative'::"text")) AS "negative_calls",
    "round"("avg"("ca"."duration_seconds") FILTER (WHERE (("ca"."dial_disposition")::"text" = 'connected'::"text")), 0) AS "avg_call_duration_seconds",
    "count"("cli"."item_id") FILTER (WHERE (("cli"."status")::"text" = 'deferred'::"text")) AS "callbacks_pending"
   FROM ((("public"."call_lists" "cl"
     LEFT JOIN "public"."call_scripts" "cs" ON (("cs"."script_id" = "cl"."script_id")))
     LEFT JOIN "public"."call_list_items" "cli" ON (("cli"."list_id" = "cl"."list_id")))
     LEFT JOIN "public"."call_attempts" "ca" ON (("ca"."list_item_id" = "cli"."item_id")))
  GROUP BY "cl"."campaign_id", "cl"."list_id", "cl"."name", "cl"."status", "cl"."total_items", "cl"."completed_items", "cl"."priority_strategy", "cs"."script_id", "cs"."title";


