CREATE TABLE IF NOT EXISTS "public"."call_outcome_definitions" (
    "outcome_id" integer NOT NULL,
    "campaign_id" integer,
    "script_id" integer,
    "name" character varying(200) NOT NULL,
    "description" "text",
    "outcome_category" character varying(20) NOT NULL,
    "maps_to_ambition_id" integer,
    "is_positive" boolean DEFAULT false NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "activity_id" integer,
    "response_type" character varying(20) DEFAULT 'checkbox'::character varying NOT NULL,
    "response_options" "jsonb",
    "side_effect" character varying(40) DEFAULT 'none'::character varying NOT NULL,
    "side_effect_payload" "jsonb",
    "maps_to_rating_level" integer,
    "maps_to_binary_value" character varying(30),
    CONSTRAINT "call_outcome_definitions_maps_to_rating_level_check" CHECK ((("maps_to_rating_level" IS NULL) OR (("maps_to_rating_level" >= 1) AND ("maps_to_rating_level" <= 5)))),
    CONSTRAINT "call_outcome_definitions_outcome_category_check" CHECK ((("outcome_category")::"text" = ANY ((ARRAY['dial'::character varying, 'conversation'::character varying, 'cta'::character varying])::"text"[]))),
    CONSTRAINT "call_outcome_definitions_response_type_check" CHECK ((("response_type")::"text" = ANY ((ARRAY['checkbox'::character varying, 'text'::character varying, 'select'::character varying, 'number'::character varying])::"text"[]))),
    CONSTRAINT "call_outcome_definitions_side_effect_check" CHECK ((("side_effect")::"text" = ANY ((ARRAY['none'::character varying, 'set_membership_pending'::character varying])::"text"[])))
);


ALTER TABLE "public"."call_outcome_definitions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."call_outcome_definitions"."response_type" IS 'How the caller records this outcome: checkbox (yes/no), text (free text), select (pick from options), or number (numeric value)';



COMMENT ON COLUMN "public"."call_outcome_definitions"."response_options" IS 'For select type: JSON array of {value, label} option objects';



COMMENT ON COLUMN "public"."call_outcome_definitions"."side_effect" IS 'Domain effect when positively recorded: set_membership_pending sets workers to member_pending (not already financial_member).';



COMMENT ON COLUMN "public"."call_outcome_definitions"."side_effect_payload" IS 'Optional JSON e.g. {"select_truthy_values":["joined","yes"]} for membership side effect.';



COMMENT ON COLUMN "public"."call_outcome_definitions"."maps_to_rating_level" IS 'Explicit rating (1..5) produced when this outcome is recorded. Takes precedence over the legacy is_positive / outcome_category composite. NULL = use legacy composite.';



COMMENT ON COLUMN "public"."call_outcome_definitions"."maps_to_binary_value" IS 'Optional binary_value (e.g. yes/no/DNP) written to the rating alongside maps_to_rating_level. Used for outcome questions that record a structured response as well as a rating.';



