CREATE OR REPLACE VIEW "public"."call_outcome_summary" AS
 SELECT "cod"."outcome_id",
    "cod"."campaign_id",
    "cod"."script_id",
    "cod"."name",
    "cod"."outcome_category",
    "cod"."maps_to_ambition_id",
    "cod"."is_positive",
    "count"("cao"."attempt_id") AS "times_recorded",
    "count"(DISTINCT "ca"."list_item_id") AS "unique_contacts",
    "count"(DISTINCT "ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = 'connected'::"text")) AS "connected_attempts_with_outcome"
   FROM (("public"."call_outcome_definitions" "cod"
     LEFT JOIN "public"."call_attempt_outcomes" "cao" ON (("cao"."outcome_id" = "cod"."outcome_id")))
     LEFT JOIN "public"."call_attempts" "ca" ON (("ca"."attempt_id" = "cao"."attempt_id")))
  GROUP BY "cod"."outcome_id", "cod"."campaign_id", "cod"."script_id", "cod"."name", "cod"."outcome_category", "cod"."maps_to_ambition_id", "cod"."is_positive";


ALTER VIEW "public"."call_outcome_summary" OWNER TO "postgres";


