    CONSTRAINT "call_script_cta_ambitions_target_support_level_check" CHECK ((("target_support_level" IS NULL) OR (("target_support_level")::"text" = ANY ((ARRAY['strong_supporter'::character varying, 'supporter'::character varying, 'neutral'::character varying, 'unsupportive'::character varying, 'hostile'::character varying])::"text"[]))))
