CREATE OR REPLACE VIEW "public"."call_section_funnel" AS
 SELECT "cl"."campaign_id",
    "cl"."list_id",
    "cl"."section_plan_id",
    COALESCE("ca"."script_id", "cl"."script_id") AS "resolved_script_id",
    "css"."section_id",
    "css"."sort_order",
    "css"."section_type",
    "css"."title" AS "section_title",
    "count"(DISTINCT "ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = 'connected'::"text")) AS "total_connected_calls",
    "count"(DISTINCT "cso"."attempt_id") FILTER (WHERE ("cso"."reached" = true)) AS "reached_count",
        CASE
            WHEN ("count"(DISTINCT "ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = 'connected'::"text")) > 0) THEN "round"(((100.0 * ("count"(DISTINCT "cso"."attempt_id") FILTER (WHERE ("cso"."reached" = true)))::numeric) / ("count"(DISTINCT "ca"."attempt_id") FILTER (WHERE (("ca"."dial_disposition")::"text" = 'connected'::"text")))::numeric), 1)
            ELSE (0)::numeric
        END AS "reach_rate_pct"
   FROM (((("public"."call_lists" "cl"
     LEFT JOIN "public"."call_list_items" "cli" ON (("cli"."list_id" = "cl"."list_id")))
     LEFT JOIN "public"."call_attempts" "ca" ON (("ca"."list_item_id" = "cli"."item_id")))
     JOIN "public"."call_script_sections" "css" ON (("css"."script_id" = COALESCE("ca"."script_id", "cl"."script_id"))))
     LEFT JOIN "public"."call_step_outcomes" "cso" ON ((("cso"."attempt_id" = "ca"."attempt_id") AND ("cso"."section_id" = "css"."section_id"))))
  GROUP BY "cl"."campaign_id", "cl"."list_id", "cl"."section_plan_id", COALESCE("ca"."script_id", "cl"."script_id"), "css"."section_id", "css"."sort_order", "css"."section_type", "css"."title"
  ORDER BY "cl"."campaign_id", "cl"."list_id", "css"."sort_order";


ALTER VIEW "public"."call_section_funnel" OWNER TO "postgres";


COMMENT ON VIEW "public"."call_section_funnel" IS 'Section-level call progression rates. Uses COALESCE(attempt.script_id, list.script_id) for historical accuracy.';



