    CONSTRAINT "campaign_activities_an_resource_type_check" CHECK ((("an_resource_type")::"text" = ANY ((ARRAY['form'::character varying, 'survey'::character varying, 'petition'::character varying, 'event'::character varying])::"text"[]))),
