COMMENT ON COLUMN "public"."campaign_ambitions"."review_due_since" IS 'Phase 7: set when an industrial_outcomes ambition should be reviewed after a triggering event (log of claims yes vote, employer proposal no vote, or WOC counter-offer endorsement). Cleared when the organiser completes the review and a campaign_ambition_revisions row is written.';



CREATE OR REPLACE VIEW "public"."campaign_ambition_progress" WITH ("security_invoker"='true') AS
 SELECT "ca"."campaign_id",
    "ca"."campaign_ambition_id",
    "ca"."category",
    "ca"."subcategory",
    "ca"."label",
    "ca"."target_value",
    "ca"."target_value_max",
    "ca"."target_unit",
    "ca"."target_date",
    "ca"."current_value",
    "ca"."current_value_overridden",
    "count"("pa"."ambition_id") AS "linked_stage_ambition_count",
    "count"("pa"."ambition_id") FILTER (WHERE ("pa"."is_achieved" IS TRUE)) AS "linked_stage_ambition_achieved_count",
        CASE
            WHEN ("count"("pa"."ambition_id") > 0) THEN "round"(((100.0 * ("count"("pa"."ambition_id") FILTER (WHERE ("pa"."is_achieved" IS TRUE)))::numeric) / ("count"("pa"."ambition_id"))::numeric), 1)
            ELSE NULL::numeric
        END AS "linked_stage_achievement_pct"
   FROM ("public"."campaign_ambitions" "ca"
     LEFT JOIN "public"."plan_ambitions" "pa" ON (("pa"."parent_campaign_ambition_id" = "ca"."campaign_ambition_id")))
  GROUP BY "ca"."campaign_id", "ca"."campaign_ambition_id", "ca"."category", "ca"."subcategory", "ca"."label", "ca"."target_value", "ca"."target_value_max", "ca"."target_unit", "ca"."target_date", "ca"."current_value", "ca"."current_value_overridden";


ALTER VIEW "public"."campaign_ambition_progress" OWNER TO "postgres";


COMMENT ON VIEW "public"."campaign_ambition_progress" IS 'Per (campaign, campaign ambition) rollup: linked stage ambition counts and the share that have been marked is_achieved. Used by Phase 9 reporting to show cross-stage coherence.';



