    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "structured_script_id" integer,
    "entry_branch" character varying(30),
    "email_list_id" integer,
    "preheader" "text",
    "body_json" "jsonb",
    "sms_list_id" integer,
    "wrapper_id" integer,
    CONSTRAINT "campaign_comms_drafts_entry_branch_check" CHECK ((("entry_branch" IS NULL) OR (("entry_branch")::"text" = ANY ((ARRAY['ai_first'::character varying, 'paste_first'::character varying, 'ai_list_first'::character varying, 'paste_list_first'::character varying, 'build_list'::character varying])::"text"[])))),
    CONSTRAINT "campaign_comms_drafts_platform_check" CHECK ((("platform")::"text" = ANY ((ARRAY['email'::character varying, 'sms'::character varying, 'phone_script'::character varying])::"text"[]))),
    CONSTRAINT "campaign_comms_drafts_sent_via_check" CHECK ((("sent_via" IS NULL) OR (("sent_via")::"text" = ANY ((ARRAY['action_network'::character varying, 'yabbr'::character varying, 'manual'::character varying, 'mobile_message'::character varying, 'sendgrid'::character varying, 'outlook_direct'::character varying])::"text"[])))),
    CONSTRAINT "campaign_comms_drafts_stage_number_check" CHECK ((("stage_number" >= 0) AND ("stage_number" <= 11))),
    CONSTRAINT "campaign_comms_drafts_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['generating'::character varying, 'draft'::character varying, 'approved'::character varying, 'sent'::character varying, 'failed'::character varying])::"text"[])))
);


ALTER TABLE "public"."campaign_comms_drafts" OWNER TO "postgres";


COMMENT ON COLUMN "public"."campaign_comms_drafts"."stage_number" IS 'Campaign stage this draft belongs to, mirroring campaign_stage_plans.stage_number: 0 = standalone activities, 1–6 = preparing to bargain, 7–11 = bargaining to win.';



COMMENT ON COLUMN "public"."campaign_comms_drafts"."entry_branch" IS 'Tracks how the email orchestration was entered. Values: ai_first | paste_first | ai_list_first | paste_list_first | build_list. NULL for legacy/standalone drafts.';



COMMENT ON COLUMN "public"."campaign_comms_drafts"."email_list_id" IS 'Optional FK to email_lists. Set when the campaign-scoped flow attaches a persisted recipient list to the draft. NULL means filter-based recipients (legacy flow).';



COMMENT ON COLUMN "public"."campaign_comms_drafts"."preheader" IS 'Optional inbox preview text shown alongside the subject line. Resolved with the same {{var}} pipeline as body.';



COMMENT ON COLUMN "public"."campaign_comms_drafts"."body_json" IS 'TipTap (ProseMirror) document JSON for the email body. Source of truth for round-trip rich-text edits; body and body_html are derived views.';



COMMENT ON COLUMN "public"."campaign_comms_drafts"."sms_list_id" IS 'Optional FK to sms_lists. Set when a campaign-scoped SMS blast attaches a persisted recipient list to the draft.';



COMMENT ON COLUMN "public"."campaign_comms_drafts"."wrapper_id" IS 'Email wrapper applied at platform (SendGrid) send time. NULL = the default wrapper.';



