    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "password_hash" "text" NOT NULL,
    "password_algo" character varying(20) DEFAULT 'argon2id'::character varying NOT NULL,
    "failed_attempts" integer DEFAULT 0 NOT NULL,
    "locked_until" timestamp with time zone,
    "issued_by" "uuid"
);


ALTER TABLE "public"."campaign_leader_tokens" OWNER TO "postgres";


COMMENT ON COLUMN "public"."campaign_leader_tokens"."password_hash" IS 'argon2id (or bcrypt) hash of the issuer-supplied password. Pre-existing rows were created without passwords; they were auto-revoked by the Phase 1 migration and must be re-issued.';



COMMENT ON COLUMN "public"."campaign_leader_tokens"."password_algo" IS 'Algorithm used to compute password_hash. Defaults to argon2id.';



COMMENT ON COLUMN "public"."campaign_leader_tokens"."failed_attempts" IS 'Running count of failed password attempts. Reset on successful auth. Triggers a 15-minute lockout (locked_until) at the API layer when >= 5.';



COMMENT ON COLUMN "public"."campaign_leader_tokens"."locked_until" IS 'Timestamp until which password attempts are rejected without checking the hash. Set by the API layer after repeated failures.';



COMMENT ON COLUMN "public"."campaign_leader_tokens"."issued_by" IS 'auth.users.id of the staff member who issued the token. Used for progress dashboards and revocation provenance.';



