    "anchor_worker_id" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "commonality_logic" "text",
    "target_size" integer,
    "source" character varying(30) DEFAULT 'manual'::character varying,
    "display_order" integer DEFAULT 0 NOT NULL,
    "unit_basis" "jsonb",
    "parent_ou_id" integer,
    "is_group_container" boolean DEFAULT false NOT NULL,
    "ou_group_id" integer,
    "user_rating" smallint,
    CONSTRAINT "campaign_organising_units_ou_type_check" CHECK ((("ou_type")::"text" = ANY ((ARRAY['shift'::character varying, 'department'::character varying, 'network'::character varying, 'job_type'::character varying, 'worksite'::character varying, 'employer'::character varying, 'ethnic_community'::character varying, 'crew_rotation'::character varying, 'accommodation'::character varying, 'work_area'::character varying, 'custom'::character varying])::"text"[]))),
    CONSTRAINT "campaign_organising_units_parent_self_check" CHECK ((("parent_ou_id" IS NULL) OR ("parent_ou_id" <> "ou_id"))),
    CONSTRAINT "campaign_organising_units_source_check" CHECK ((("source")::"text" = ANY ((ARRAY['manual'::character varying, 'wtp_seeded'::character varying, 'generated'::character varying, 'field_discovery'::character varying])::"text"[]))),
    CONSTRAINT "campaign_organising_units_target_size_check" CHECK ((("target_size" IS NULL) OR ("target_size" >= 0))),
    CONSTRAINT "campaign_organising_units_total_workers_estimated_check" CHECK ((("total_workers_estimated" IS NULL) OR ("total_workers_estimated" >= 0))),
    CONSTRAINT "campaign_organising_units_user_rating_check" CHECK ((("user_rating" IS NULL) OR (("user_rating" >= 1) AND ("user_rating" <= 5))))
);


ALTER TABLE "public"."campaign_organising_units" OWNER TO "postgres";


COMMENT ON COLUMN "public"."campaign_organising_units"."unit_basis" IS 'Optional JSONB capturing the filter the unit was built from so it can be reproduced or audited. Common shapes: {"employer_id": <int>}, {"worksite_id": <int>}, {"canonical_occupation_id": <int>}, {"occupation_group_id": <int>}, {"custom": true}. Multi-key combinations are valid (e.g. {"employer_id": 12, "occupation_group_id": 4}).';



COMMENT ON COLUMN "public"."campaign_organising_units"."parent_ou_id" IS 'Optional FK to another OU in the SAME campaign that owns this row as a sub-unit.';



COMMENT ON COLUMN "public"."campaign_organising_units"."is_group_container" IS 'When TRUE this OU is a named group header. Workers cannot be assigned directly to it; they belong to the member units (rows with ou_group_id = this row''s ou_id). Created by the group creation flow in the campaign wizard.';



COMMENT ON COLUMN "public"."campaign_organising_units"."ou_group_id" IS 'FK to the group container OU that owns this member unit. Always equals parent_ou_id when set. Stored separately so group-membership queries are fast without distinguishing "group parent" from "arbitrary sub-unit". NULL for group containers themselves and for standalone units.';



COMMENT ON COLUMN "public"."campaign_organising_units"."user_rating" IS 'Subjective organiser rating of the unit: 1 (extremely strong) .. 5 (hostile). Independent of worker assessment ratings and of any sub-unit ratings.';



