CREATE TABLE IF NOT EXISTS "public"."campaigns" (
    "campaign_id" integer NOT NULL,
    "name" character varying(200) NOT NULL,
    "description" "text",
    "campaign_type" character varying(20) NOT NULL,
    "status" character varying(20) DEFAULT 'planning'::character varying NOT NULL,
    "start_date" "date",
    "end_date" "date",
    "organiser_id" integer,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "enterprise_agreement_subtype" character varying(30),
    "campaign_scope" character varying(40),
    "total_worker_estimate" integer,
    "sector_wide" boolean DEFAULT false NOT NULL,
    "created_by" "uuid",
    "replaced_agreement_id" integer,
    "msd_required" boolean DEFAULT false NOT NULL,
    "plan_timeframe_weeks" integer,
    "current_phase" "public"."campaign_phase_enum" DEFAULT 'preparing_to_bargain'::"public"."campaign_phase_enum" NOT NULL,
    "bargaining_commenced_at" "date",
    "wizard_bargaining_triage" "text",
    "is_standing" boolean DEFAULT false NOT NULL,
    "is_sms_episode" boolean DEFAULT false NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "campaigns_campaign_scope_check" CHECK ((("campaign_scope" IS NULL) OR (("campaign_scope")::"text" = ANY ((ARRAY['single_employer_single_site'::character varying, 'single_employer_multi_site'::character varying, 'multi_employer_single_site'::character varying, 'multi_employer_multi_site'::character varying])::"text"[])))),
    CONSTRAINT "campaigns_campaign_type_check" CHECK ((("campaign_type")::"text" = ANY ((ARRAY['bargaining'::character varying, 'organising'::character varying, 'mobilisation'::character varying, 'political'::character varying])::"text"[]))),
    CONSTRAINT "campaigns_enterprise_agreement_subtype_check" CHECK ((("enterprise_agreement_subtype" IS NULL) OR (("enterprise_agreement_subtype")::"text" = ANY ((ARRAY['new'::character varying, 'replacement'::character varying, 'boss_initiated'::character varying])::"text"[])))),
    CONSTRAINT "campaigns_plan_timeframe_weeks_check" CHECK ((("plan_timeframe_weeks" IS NULL) OR ("plan_timeframe_weeks" > 0))),
    CONSTRAINT "campaigns_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['planning'::character varying, 'active'::character varying, 'completed'::character varying, 'suspended'::character varying])::"text"[]))),
    CONSTRAINT "campaigns_total_worker_estimate_check" CHECK ((("total_worker_estimate" IS NULL) OR ("total_worker_estimate" >= 0))),
    CONSTRAINT "campaigns_wizard_bargaining_triage_check" CHECK (("wizard_bargaining_triage" = ANY (ARRAY['not_started'::"text", 'underway'::"text", 'advanced'::"text"])))
);


ALTER TABLE "public"."campaigns" OWNER TO "postgres";


COMMENT ON COLUMN "public"."campaigns"."replaced_agreement_id" IS 'For replacement EA bargaining campaigns: the existing enterprise agreement being superseded by this campaign.';



COMMENT ON COLUMN "public"."campaigns"."msd_required" IS 'Whether a Majority Support Determination is required for this bargaining campaign';



COMMENT ON COLUMN "public"."campaigns"."plan_timeframe_weeks" IS 'Campaign plan timeframe in weeks (replaces hard-coded end_date for bargaining campaigns where the real close depends on negotiation outcomes). When set, UI computes end_date as start_date + plan_timeframe_weeks * 7. NULL means: use campaigns.end_date as a hard custom date, or leave unbounded.';



COMMENT ON COLUMN "public"."campaigns"."current_phase" IS 'High-level phase of the bargaining lifecycle. preparing_to_bargain = Stages 1–6 (P2W); bargaining_to_win = Stages 7–11 (B2W); post_settlement = after agreement ratified. Backfilled from campaign_situation_analyses.employer_interaction_state.';



COMMENT ON COLUMN "public"."campaigns"."bargaining_commenced_at" IS 'Date bargaining formally commenced. Drives the 9-month intractable bargaining threshold. Backfilled from earliest situation analysis with employer_interaction_state=bargaining_underway, or from campaign_timelines.pabo_available_date - 30 days.';



COMMENT ON COLUMN "public"."campaigns"."is_standing" IS 'When TRUE this campaign acts as a shared container for phone operations not belonging to a specific active campaign. Exactly one standing campaign should exist per organisation.';



COMMENT ON COLUMN "public"."campaigns"."is_sms_episode" IS 'When TRUE this campaign is a hidden per-episode container for a standalone SMS blast, survey, or chat that is not part of a visible organising campaign. Hidden from the campaigns list and campaign chrome (assessments, wall chart, plan). Distinct from is_standing.';



COMMENT ON COLUMN "public"."campaigns"."archived_at" IS 'Used for hidden SMS episode campaigns (is_sms_episode). Standalone archive/unarchive keeps the episode in lockstep with its actions.';



