CREATE OR REPLACE VIEW "public"."campaign_ou_coverage_summary" WITH ("security_invoker"='true') AS
 SELECT "c"."campaign_id",
    "count"("ou"."ou_id") AS "total_ous",
    "count"("ou"."ou_id") FILTER (WHERE (("ou"."total_workers_estimated" >= 5) AND ("ou"."total_workers_estimated" <= 50))) AS "sized_ous",
    "count"(DISTINCT "ou"."ou_id") FILTER (WHERE (EXISTS ( SELECT 1
           FROM (("public"."campaign_worker_ou" "cwou"
             JOIN "public"."workers" "w" ON (("w"."worker_id" = "cwou"."worker_id")))
             JOIN "public"."member_role_types" "mrt" ON (("mrt"."role_type_id" = "w"."member_role_type_id")))
          WHERE (("cwou"."ou_id" = "ou"."ou_id") AND (("mrt"."role_name")::"text" = 'contact'::"text"))))) AS "ous_with_contact",
    "count"(DISTINCT "ou"."ou_id") FILTER (WHERE (EXISTS ( SELECT 1
           FROM (("public"."campaign_worker_ou" "cwou"
             JOIN "public"."workers" "w" ON (("w"."worker_id" = "cwou"."worker_id")))
             JOIN "public"."member_role_types" "mrt" ON (("mrt"."role_type_id" = "w"."member_role_type_id")))
          WHERE (("cwou"."ou_id" = "ou"."ou_id") AND (("mrt"."role_name")::"text" = 'Activist'::"text"))))) AS "ous_with_activist",
    "count"(DISTINCT "ou"."ou_id") FILTER (WHERE (EXISTS ( SELECT 1
           FROM (("public"."campaign_worker_ou" "cwou"
             JOIN "public"."workers" "w" ON (("w"."worker_id" = "cwou"."worker_id")))
             JOIN "public"."member_role_types" "mrt" ON (("mrt"."role_type_id" = "w"."member_role_type_id")))
          WHERE (("cwou"."ou_id" = "ou"."ou_id") AND (("mrt"."role_name")::"text" = 'delegate'::"text"))))) AS "ous_with_delegate",
    "count"(DISTINCT "ou"."ou_id") FILTER (WHERE ("ou"."anchor_worker_id" IS NOT NULL)) AS "ous_with_anchor",
    COALESCE("sum"("ou"."total_workers_estimated"), (0)::bigint) AS "total_estimated_workers",
    ( SELECT "count"(DISTINCT "cwou2"."worker_id") AS "count"
           FROM ("public"."campaign_worker_ou" "cwou2"
             JOIN "public"."campaign_organising_units" "ou2" ON (("ou2"."ou_id" = "cwou2"."ou_id")))
          WHERE ("ou2"."campaign_id" = "c"."campaign_id")) AS "total_assigned_workers"
   FROM ("public"."campaigns" "c"
     LEFT JOIN "public"."campaign_organising_units" "ou" ON (("ou"."campaign_id" = "c"."campaign_id")))
  GROUP BY "c"."campaign_id";


ALTER VIEW "public"."campaign_ou_coverage_summary" OWNER TO "postgres";


