CREATE OR REPLACE VIEW "public"."campaign_permissions_detail" AS
 SELECT "cep"."permission_id",
    "cep"."campaign_id",
    "c"."name" AS "campaign_name",
    "cep"."granted_by",
    "granter_profile"."organiser_id" AS "granted_by_organiser_id",
    "granter_org"."organiser_name" AS "granted_by_name",
    "cep"."granted_to",
    "grantee_profile"."organiser_id" AS "granted_to_organiser_id",
    "grantee_org"."organiser_name" AS "granted_to_name",
    "cep"."granted_at",
    "cep"."is_persistent",
    "cep"."reason",
    "cep"."status",
    "cep"."revoked_at",
    "cep"."revoked_by"
   FROM ((((((("public"."campaign_edit_permissions" "cep"
     JOIN "public"."campaigns" "c" ON (("c"."campaign_id" = "cep"."campaign_id")))
     LEFT JOIN "public"."user_profiles" "granter_profile" ON (("granter_profile"."user_id" = "cep"."granted_by")))
     LEFT JOIN "public"."organisers" "granter_org" ON (("granter_org"."organiser_id" = "granter_profile"."organiser_id")))
     LEFT JOIN "public"."user_profiles" "grantee_profile" ON (("grantee_profile"."user_id" = "cep"."granted_to")))
     LEFT JOIN "public"."organisers" "grantee_org" ON (("grantee_org"."organiser_id" = "grantee_profile"."organiser_id")))
     LEFT JOIN "auth"."users" "granter_auth" ON (("granter_auth"."id" = "cep"."granted_by")))
     LEFT JOIN "auth"."users" "grantee_auth" ON (("grantee_auth"."id" = "cep"."granted_to")));


