CREATE TABLE IF NOT EXISTS "public"."campaign_situation_analyses" (
    "situation_id" integer NOT NULL,
    "campaign_id" integer NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "is_current" boolean DEFAULT true NOT NULL,
    "employer_interaction_state" character varying(40),
    "employer_state_notes" "text",
    "balloted_count" integer,
    "top_issues" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "upcoming_workforce_changes" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "employer_relationships" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "hr_posture" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "union_history" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "strategic_context_summary" "text",
    "company_playbook" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "workforce_populations" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "leverage_and_maths" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "information_gaps" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "ai_generated" boolean DEFAULT false NOT NULL,
    "ai_model" character varying(80),
    "ai_prompt_snapshot" "jsonb",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "nerr_status" "text" DEFAULT 'unknown'::"text",
    "nerr_issued_at" "date",
    "bargaining_phase_state" "text",
    "employer_ballot_intent" "text",
    "prior_employer_ballots" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "key_disputes" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "worker_support_estimate" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "campaign_situation_analyses_bargaining_phase_state_check" CHECK (("bargaining_phase_state" = ANY (ARRAY['not_commenced'::"text", 'commenced'::"text", 'stalled'::"text", 'agreement_drafting'::"text", 'balloted'::"text", 'post_settlement'::"text", 'unknown'::"text"]))),
    CONSTRAINT "campaign_situation_analyses_employer_ballot_intent_check" CHECK (("employer_ballot_intent" = ANY (ARRAY['none'::"text", 'signalled'::"text", 'imminent'::"text", 'unknown'::"text"]))),
    CONSTRAINT "campaign_situation_analyses_employer_interaction_state_check" CHECK ((("employer_interaction_state")::"text" = ANY ((ARRAY['no_engagement'::character varying, 'preemptive_setup'::character varying, 'bargaining_underway'::character varying, 'agreement_balloted'::character varying, 'employer_delaying'::character varying, 'industrial_action_phase'::character varying, 'post_settlement'::character varying, 'other'::character varying])::"text"[]))),
    CONSTRAINT "campaign_situation_analyses_nerr_status_check" CHECK (("nerr_status" = ANY (ARRAY['not_issued'::"text", 'issued'::"text", 'superseded'::"text", 'unknown'::"text"])))
);


ALTER TABLE "public"."campaign_situation_analyses" OWNER TO "postgres";


COMMENT ON TABLE "public"."campaign_situation_analyses" IS 'Structured campaign situation analysis (SOC Field Guide §2 structure). One current row per campaign; older versions retained for history. Auto-injected into Theory of Winning + comms drafts so predicted employer moves become inoculation lines and top issues become agitation hooks.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."is_current" IS 'TRUE for the active version; older versions are kept for history. Enforced unique by partial index idx_csa_campaign_current.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."top_issues" IS 'JSONB array of {label, heat (1..5), notes?, oa_position?, employer_position?}. Heat is organiser-assessed. oa_position and employer_position are optional string fields added in Phase 3 to record negotiating positions for each issue, enabling top_issues rows with positions set to be carried forward as key_disputes in the Phase 2 Bargaining to Win wizard.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."company_playbook" IS 'Predicted employer moves [{move, why, disruption_point}]. Feeds inoculation copy in downstream comms drafts.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."information_gaps" IS 'AI guardrail output: facts the model declined to invent. Surface to the organiser for follow-up.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."nerr_status" IS 'Status of the Notice of Employee Representation Rights (NERR). One of: not_issued, issued, superseded, unknown.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."nerr_issued_at" IS 'Date the NERR was formally issued.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."bargaining_phase_state" IS 'Current stage within bargaining. Complements employer_interaction_state for campaigns in bargaining_underway.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."employer_ballot_intent" IS 'Organisers assessment of whether the employer intends to run a ballot. none / signalled / imminent / unknown.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."prior_employer_ballots" IS 'JSONB array of prior employer-run ballots. Each element: {ballot_kind, conducted_at, eligible_count, votes_yes, votes_no, outcome, source_of_evidence, notes}.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."key_disputes" IS 'JSONB array of active bargaining disputes. Each element: {topic, oa_position, employer_position, urgency (1..5), notes}.';



COMMENT ON COLUMN "public"."campaign_situation_analyses"."worker_support_estimate" IS 'JSONB object with organiser estimate of worker support: {percent_supportive_estimated, basis_of_estimate, notes}.';



