    CONSTRAINT "campaign_stage_workplan_tasks_task_type_check" CHECK ((("task_type")::"text" = ANY ((ARRAY['discovery'::character varying, 'outreach'::character varying, 'mapping'::character varying, 'engagement'::character varying, 'admin'::character varying, 'other'::character varying])::"text"[])))
);


ALTER TABLE "public"."campaign_stage_workplan_tasks" OWNER TO "postgres";


COMMENT ON COLUMN "public"."campaign_stage_workplan_tasks"."assigned_worker_id" IS 'Worker (leader, delegate, activist, contact) this task is assigned to. When combined with a worker_assessable plan_ambition_id, triggers an auto-rating of 1 (supportive leader) on the first activity linked to that ambition.';



CREATE OR REPLACE VIEW "public"."campaign_stage_workplan_progress" WITH ("security_invoker"='true') AS
 SELECT "campaign_id",
    "stage_number",
    "plan_ambition_id",
    "count"(*) AS "total_tasks",
    "count"(*) FILTER (WHERE (("status")::"text" = 'completed'::"text")) AS "completed_tasks",
    "count"(*) FILTER (WHERE (("status")::"text" = 'in_progress'::"text")) AS "in_progress_tasks",
    "count"(*) FILTER (WHERE (("status")::"text" = 'blocked'::"text")) AS "blocked_tasks",
    "count"(*) FILTER (WHERE (("status")::"text" = 'planned'::"text")) AS "planned_tasks",
    "count"(*) FILTER (WHERE (("status")::"text" = 'cancelled'::"text")) AS "cancelled_tasks",
        CASE
            WHEN ("count"(*) FILTER (WHERE (("status")::"text" <> 'cancelled'::"text")) > 0) THEN "round"(((100.0 * ("count"(*) FILTER (WHERE (("status")::"text" = 'completed'::"text")))::numeric) / ("count"(*) FILTER (WHERE (("status")::"text" <> 'cancelled'::"text")))::numeric), 1)
            ELSE (0)::numeric
        END AS "completion_pct"
   FROM "public"."campaign_stage_workplan_tasks" "t"
  GROUP BY "campaign_id", "stage_number", "plan_ambition_id";


