CREATE OR REPLACE VIEW "public"."campaign_unit_assignment_summary" WITH ("security_invoker"='true') AS
 WITH "membership" AS (
         SELECT "campaign_worker_membership"."campaign_id",
            "campaign_worker_membership"."worker_id"
           FROM "public"."campaign_worker_membership"
        ), "ou_assignments" AS (
         SELECT "cou"."campaign_id",
            "cou"."ou_id",
            "cou"."parent_ou_id",
            "cou"."ou_group_id",
            "cou"."is_group_container",
            "cou"."name" AS "ou_name",
            "cou"."ou_type",
            "cou"."total_workers_estimated",
            "cwo"."worker_id"
           FROM ("public"."campaign_organising_units" "cou"
             LEFT JOIN "public"."campaign_worker_ou" "cwo" ON (("cwo"."ou_id" = "cou"."ou_id")))
        )
 SELECT "m"."campaign_id",
    "oa"."ou_id",
    "oa"."parent_ou_id",
    "oa"."ou_group_id",
    "oa"."is_group_container",
    "oa"."ou_name",
    "oa"."ou_type",
    "oa"."total_workers_estimated",
    "count"(DISTINCT "m"."worker_id") AS "allocated_worker_count"
   FROM ("membership" "m"
     LEFT JOIN "ou_assignments" "oa" ON ((("oa"."campaign_id" = "m"."campaign_id") AND ("oa"."worker_id" = "m"."worker_id"))))
  GROUP BY "m"."campaign_id", "oa"."ou_id", "oa"."parent_ou_id", "oa"."ou_group_id", "oa"."is_group_container", "oa"."ou_name", "oa"."ou_type", "oa"."total_workers_estimated";


ALTER VIEW "public"."campaign_unit_assignment_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."campaign_unit_assignment_summary" IS 'Per (campaign, ou) count of allocated workers. ou_id IS NULL rows represent the synthetic "Unallocated" bucket (campaign members with no campaign_worker_ou row). parent_ou_id + ou_group_id + is_group_container surface the OU group structure so consumers can roll up sub-units into their parent group.';



CREATE OR REPLACE VIEW "public"."campaign_unit_hierarchy_summary" WITH ("security_invoker"='true') AS
 WITH "parent_descendants" AS (
         SELECT "p_1"."campaign_id",
            "p_1"."ou_id" AS "parent_ou_id",
            "p_1"."ou_id" AS "scope_ou_id"
           FROM "public"."campaign_organising_units" "p_1"
          WHERE ("p_1"."parent_ou_id" IS NULL)
        UNION ALL
         SELECT "c"."campaign_id",
            "c"."parent_ou_id",
            "c"."ou_id" AS "scope_ou_id"
           FROM "public"."campaign_organising_units" "c"
          WHERE ("c"."parent_ou_id" IS NOT NULL)
        )
 SELECT "p"."campaign_id",
    "p"."ou_id" AS "parent_ou_id",
    "p"."name" AS "parent_name",
    "p"."ou_type" AS "parent_ou_type",
    COALESCE("child_counts"."child_count", (0)::bigint) AS "child_count",
    COALESCE("child_counts"."child_ou_ids", ARRAY[]::integer[]) AS "child_ou_ids",
    "count"(DISTINCT "cwo"."worker_id") AS "aggregate_assigned_workers"
   FROM ((("public"."campaign_organising_units" "p"
     LEFT JOIN "parent_descendants" "pd" ON (("pd"."parent_ou_id" = "p"."ou_id")))
     LEFT JOIN "public"."campaign_worker_ou" "cwo" ON (("cwo"."ou_id" = "pd"."scope_ou_id")))
     LEFT JOIN ( SELECT "campaign_organising_units"."parent_ou_id",
            "count"(*) AS "child_count",
            "array_agg"("campaign_organising_units"."ou_id" ORDER BY "campaign_organising_units"."display_order", "campaign_organising_units"."ou_id") AS "child_ou_ids"
           FROM "public"."campaign_organising_units"
          WHERE ("campaign_organising_units"."parent_ou_id" IS NOT NULL)
          GROUP BY "campaign_organising_units"."parent_ou_id") "child_counts" ON (("child_counts"."parent_ou_id" = "p"."ou_id")))
  WHERE ("p"."parent_ou_id" IS NULL)
  GROUP BY "p"."campaign_id", "p"."ou_id", "p"."name", "p"."ou_type", "child_counts"."child_count", "child_counts"."child_ou_ids";


ALTER VIEW "public"."campaign_unit_hierarchy_summary" OWNER TO "postgres";


