CREATE OR REPLACE VIEW "public"."campaigns_view" AS
 SELECT "c"."campaign_id",
    "c"."name",
    "c"."description",
    "c"."campaign_type",
    "c"."status",
    "c"."start_date",
    "c"."end_date",
    "c"."organiser_id",
    "c"."notes",
    "c"."created_at",
    "c"."updated_at",
    "o"."organiser_name",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."campaign_actions" "ca"
          WHERE ("ca"."campaign_id" = "c"."campaign_id")) AS "action_count",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."campaign_universes" "cu"
          WHERE ("cu"."campaign_id" = "c"."campaign_id")) AS "universe_count"
   FROM ("public"."campaigns" "c"
     LEFT JOIN "public"."organisers" "o" ON (("o"."organiser_id" = "c"."organiser_id")));


