CREATE OR REPLACE VIEW "public"."employers_view" AS
 SELECT "employer_id",
    "employer_name",
    "trading_name",
    "abn",
    "employer_category",
    "parent_company",
    "website",
    "phone",
    "email",
    "address",
    "state",
    "postcode",
    "is_active",
    "created_at",
    "updated_at",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."agreements" "a"
          WHERE ("a"."employer_id" = "emp"."employer_id")) AS "agreement_count",
    ( SELECT ("count"(DISTINCT "ewr"."worksite_id"))::integer AS "count"
           FROM "public"."employer_worksite_roles" "ewr"
          WHERE (("ewr"."employer_id" = "emp"."employer_id") AND ("ewr"."is_current" = true))) AS "worksite_count",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."workers" "w"
          WHERE (("w"."employer_id" = "emp"."employer_id") AND ("w"."is_active" = true))) AS "worker_count",
    ( SELECT "string_agg"(DISTINCT ("s"."sector_name")::"text", ', '::"text" ORDER BY ("s"."sector_name")::"text") AS "string_agg"
           FROM ("public"."employer_sectors" "es"
             JOIN "public"."sectors" "s" ON (("s"."sector_id" = "es"."sector_id")))
          WHERE ("es"."employer_id" = "emp"."employer_id")) AS "sector_names"
   FROM "public"."employers" "emp";


