COMMENT ON COLUMN "public"."gate_definitions"."stage_number" IS 'Stage number (1–11) this gate belongs to. Populated for global template rows (campaign_id IS NULL).';



COMMENT ON COLUMN "public"."gate_definitions"."name" IS 'Duplicate display label for template rows (same as gate_name). Campaign-specific rows may use gate_name only.';



COMMENT ON COLUMN "public"."gate_definitions"."description" IS 'Description of what this gate requires, for display in the UI.';



COMMENT ON COLUMN "public"."gate_definitions"."gate_type" IS 'Gate enforcement type for template rows: hard (blocks progression) or soft (advisory).';



CREATE OR REPLACE VIEW "public"."gate_criteria_with_status" AS
 SELECT "gc"."criterion_id",
    "gc"."gate_id",
    "gc"."criterion_name",
    "gc"."description",
    "gc"."metric_type",
    "gc"."target_value",
    "gc"."current_value",
    "gc"."is_met",
    "gc"."is_hard_gate",
    "gc"."evidence_notes",
    "gc"."assessed_by",
    "gc"."assessed_at",
    "gc"."sort_order",
    "gc"."created_at",
    "gc"."updated_at",
    "gc"."last_calculated_at",
    "gc"."calculation_source",
    "gd"."campaign_id",
    "gd"."gate_number",
    "gd"."gate_name",
    "c"."name" AS "campaign_name",
        CASE
            WHEN ("gc"."last_calculated_at" IS NULL) THEN 'manual'::"text"
            ELSE 'auto'::"text"
        END AS "calculation_mode",
        CASE
            WHEN ("gc"."last_calculated_at" < ("now"() - '01:00:00'::interval)) THEN 'stale'::"text"
            ELSE 'current'::"text"
        END AS "freshness_status"
   FROM (("public"."gate_criteria" "gc"
     JOIN "public"."gate_definitions" "gd" ON (("gd"."gate_id" = "gc"."gate_id")))
     JOIN "public"."campaigns" "c" ON (("c"."campaign_id" = "gd"."campaign_id")))
  ORDER BY "gd"."gate_number", "gc"."sort_order";


ALTER VIEW "public"."gate_criteria_with_status" OWNER TO "postgres";


