CREATE TABLE IF NOT EXISTS "public"."intractable_bargaining_tracker" (
    "campaign_id" integer NOT NULL,
    "bargaining_commenced_at" "date" NOT NULL,
    "nine_month_threshold_at" "date" GENERATED ALWAYS AS (("bargaining_commenced_at" + '9 mons'::interval)) STORED,
    "intractable_application_filed_at" "date",
    "intractable_declaration_made_at" "date",
    "arbitration_outcome_recorded_at" "date",
    "state" "text",
    "last_reviewed_at" timestamp with time zone DEFAULT "now"(),
    "notes" "text",
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "intractable_bargaining_tracker_state_check" CHECK (("state" = ANY (ARRAY['safe'::"text", 'approaching'::"text", 'eligible'::"text", 'applied'::"text", 'declared'::"text", 'arbitrated'::"text"])))
);


ALTER TABLE "public"."intractable_bargaining_tracker" OWNER TO "postgres";


COMMENT ON TABLE "public"."intractable_bargaining_tracker" IS 'One row per campaign once bargaining has commenced. Tracks the 9-month Fair Work Act s 235 threshold and intractable bargaining application milestones.';



COMMENT ON COLUMN "public"."intractable_bargaining_tracker"."nine_month_threshold_at" IS 'Generated: bargaining_commenced_at + 9 months. The date from which an intractable bargaining application may be filed.';



COMMENT ON COLUMN "public"."intractable_bargaining_tracker"."state" IS 'Computed state: safe (<6 mo), approaching (6-9 mo), eligible (>=9 mo), applied, declared, arbitrated. Recomputed by refresh_intractable_state().';



