CREATE OR REPLACE VIEW "public"."organising_universe_view" AS
 SELECT "ws"."worksite_id",
    "ws"."worksite_name",
    "ws"."worksite_type",
    "ws"."is_offshore",
    "ws"."parent_worksite_id",
    "pws"."worksite_name" AS "parent_worksite_name",
    "ws"."principal_employer_id",
    "pe"."employer_name" AS "principal_employer_name",
    "p"."project_id",
    "p"."project_name",
    "p"."work_type",
    "p"."project_status",
    "ewr"."employer_id",
    "emp"."employer_name",
    "emp"."employer_category",
    "emp"."parent_employer_id",
    "a"."agreement_id",
    "a"."agreement_name",
    "a"."short_name" AS "agreement_short_name",
    "a"."status" AS "agreement_status",
    "a"."agreement_scope",
    "a"."expiry_date" AS "agreement_expiry",
    "s"."sector_id",
    "s"."sector_name",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."workers" "w"
          WHERE (("w"."worksite_id" = "ws"."worksite_id") AND ("w"."employer_id" = "ewr"."employer_id") AND (("w"."project_id" = "p"."project_id") OR (("w"."project_id" IS NULL) AND ("p"."project_id" IS NULL))) AND ("w"."is_active" = true))) AS "worker_count"
   FROM (((((((("public"."worksites" "ws"
     LEFT JOIN "public"."worksites" "pws" ON (("pws"."worksite_id" = "ws"."parent_worksite_id")))
     LEFT JOIN "public"."employers" "pe" ON (("pe"."employer_id" = "ws"."principal_employer_id")))
     LEFT JOIN "public"."employer_worksite_roles" "ewr" ON ((("ewr"."worksite_id" = "ws"."worksite_id") AND ("ewr"."is_current" = true))))
     LEFT JOIN "public"."employers" "emp" ON (("emp"."employer_id" = "ewr"."employer_id")))
     LEFT JOIN "public"."projects" "p" ON ((("p"."worksite_id" = "ws"."worksite_id") AND ("p"."is_active" = true))))
     LEFT JOIN "public"."agreement_worksites" "aw" ON (("aw"."worksite_id" = "ws"."worksite_id")))
     LEFT JOIN "public"."agreements" "a" ON ((("a"."agreement_id" = "aw"."agreement_id") AND (("a"."status")::"text" <> 'Terminated'::"text") AND (("a"."employer_id" = "ewr"."employer_id") OR (EXISTS ( SELECT 1
           FROM "public"."agreement_employers" "ae"
          WHERE (("ae"."agreement_id" = "a"."agreement_id") AND ("ae"."employer_id" = "ewr"."employer_id"))))))))
     LEFT JOIN "public"."sectors" "s" ON (("s"."sector_id" = "a"."sector_id")))
  WHERE ("ws"."is_active" = true);


ALTER VIEW "public"."organising_universe_view" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pabo_applications" (
    "pabo_id" integer NOT NULL,
    "campaign_id" integer NOT NULL,
    "application_filed_at" "date",
    "fwc_application_number" "text",
    "ballot_order_made_at" "date",
    "aec_ballot_agent" "text",
    "ballot_opens_at" timestamp with time zone,
    "ballot_closes_at" timestamp with time zone,
    "eligible_voter_count" integer,
    "votes_cast" integer,
    "voter_turnout_pct" numeric GENERATED ALWAYS AS (
CASE
    WHEN (("eligible_voter_count" > 0) AND ("votes_cast" IS NOT NULL)) THEN "round"(((("votes_cast")::numeric / ("eligible_voter_count")::numeric) * (100)::numeric), 2)
    ELSE NULL::numeric
END) STORED,
    "valid_from" "date",
    "valid_until" "date",
    "notice_period_required_days" integer DEFAULT 3,
    "status" "text",
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "pabo_applications_status_check" CHECK (("status" = ANY (ARRAY['drafting'::"text", 'lodged'::"text", 'granted'::"text", 'denied'::"text", 'expired'::"text", 'superseded'::"text", 'withdrawn'::"text"])))
);


ALTER TABLE "public"."pabo_applications" OWNER TO "postgres";


COMMENT ON TABLE "public"."pabo_applications" IS 'FWC s443 Protected Action Ballot Order applications. One row per application filing; superseded/expired rows are kept for audit history. voter_turnout_pct is auto-computed from eligible_voter_count / votes_cast.';



COMMENT ON COLUMN "public"."pabo_applications"."voter_turnout_pct" IS 'Generated column: (votes_cast / eligible_voter_count) * 100, rounded to 2dp. NULL when either input is NULL or eligible_voter_count = 0.';



COMMENT ON COLUMN "public"."pabo_applications"."notice_period_required_days" IS 'Minimum notice days required before industrial action can commence under the ballot order. Defaults to 3.';



