CREATE OR REPLACE VIEW "public"."pending_permission_requests" AS
 SELECT "pr"."request_id",
    "pr"."campaign_id",
    "c"."name" AS "campaign_name",
    "pr"."requested_by",
    "requester_profile"."organiser_id" AS "requested_by_organiser_id",
    "requester_org"."organiser_name" AS "requested_by_name",
    COALESCE("requester_org"."email", "requester_auth"."email") AS "requested_by_email",
    "pr"."reason",
    "pr"."status",
    "pr"."requested_at"
   FROM (((("public"."campaign_permission_requests" "pr"
     JOIN "public"."campaigns" "c" ON (("c"."campaign_id" = "pr"."campaign_id")))
     LEFT JOIN "public"."user_profiles" "requester_profile" ON (("requester_profile"."user_id" = "pr"."requested_by")))
     LEFT JOIN "public"."organisers" "requester_org" ON (("requester_org"."organiser_id" = "requester_profile"."organiser_id")))
     LEFT JOIN "auth"."users" "requester_auth" ON (("requester_auth"."id" = "pr"."requested_by")))
  WHERE (("pr"."status")::"text" = 'pending'::"text")
  ORDER BY "pr"."requested_at" DESC;


