CREATE TABLE IF NOT EXISTS "public"."phone_call_actions" (
    "action_id" integer NOT NULL,
    "campaign_id" integer NOT NULL,
    "created_by" "uuid",
    "assessment_id" integer,
    "variation_count" integer DEFAULT 1 NOT NULL,
    "variation_dimension" character varying(40),
    "entry_branch" character varying(40) NOT NULL,
    "script_id" integer,
    "list_ids" integer[] DEFAULT '{}'::integer[],
    "status" character varying(20) DEFAULT 'in_progress'::character varying NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "selected_assessment_ids" integer[] DEFAULT '{}'::integer[] NOT NULL,
    CONSTRAINT "phone_call_actions_entry_branch_check" CHECK ((("entry_branch")::"text" = ANY (ARRAY[('list_first'::character varying)::"text", ('script_first'::character varying)::"text", ('assessment_first'::character varying)::"text", ('assessment_list_first'::character varying)::"text", ('build_list'::character varying)::"text"]))),
    CONSTRAINT "phone_call_actions_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['in_progress'::character varying, 'completed'::character varying, 'abandoned'::character varying])::"text"[]))),
    CONSTRAINT "phone_call_actions_variation_dimension_check" CHECK ((("variation_dimension" IS NULL) OR (("variation_dimension")::"text" = ANY ((ARRAY['membership_status'::character varying, 'organising_role'::character varying, 'occupation'::character varying, 'rating_band'::character varying, 'none'::character varying])::"text"[]))))
);


