CREATE OR REPLACE VIEW "public"."worksite_employer_eba_status" AS
 WITH "employer_worksite_eba" AS (
         SELECT "ewr"."employer_id",
            "ewr"."worksite_id",
            "a"."status" AS "agreement_status",
            "a"."expiry_date"
           FROM (("public"."employer_worksite_roles" "ewr"
             JOIN "public"."agreement_worksites" "aw" ON (("aw"."worksite_id" = "ewr"."worksite_id")))
             JOIN "public"."agreements" "a" ON (("a"."agreement_id" = "aw"."agreement_id")))
          WHERE (("ewr"."is_current" = true) AND (("a"."status")::"text" <> 'Terminated'::"text") AND (("a"."employer_id" = "ewr"."employer_id") OR (EXISTS ( SELECT 1
                   FROM "public"."agreement_employers" "ae"
                  WHERE (("ae"."agreement_id" = "a"."agreement_id") AND ("ae"."employer_id" = "ewr"."employer_id"))))))
        ), "employer_worksite_summary" AS (
         SELECT "ewr"."employer_id",
            "ewr"."worksite_id",
            "max"(
                CASE
                    WHEN (("eweba"."agreement_status")::"text" = 'Current'::"text") THEN "eweba"."expiry_date"
                    ELSE NULL::"date"
                END) AS "max_current_expiry",
            COALESCE("bool_or"((("eweba"."agreement_status")::"text" = 'Current'::"text")), false) AS "has_current",
            COALESCE("bool_or"((("eweba"."agreement_status")::"text" = 'Expired'::"text")), false) AS "has_expired",
            COALESCE("bool_or"((("eweba"."agreement_status")::"text" = 'Under_Negotiation'::"text")), false) AS "has_bargaining"
           FROM ("public"."employer_worksite_roles" "ewr"
             LEFT JOIN "employer_worksite_eba" "eweba" ON ((("eweba"."employer_id" = "ewr"."employer_id") AND ("eweba"."worksite_id" = "ewr"."worksite_id"))))
          WHERE ("ewr"."is_current" = true)
          GROUP BY "ewr"."employer_id", "ewr"."worksite_id"
        ), "employer_has_prior_eba" AS (
         SELECT DISTINCT "sub"."employer_id"
           FROM ( SELECT "agreements"."employer_id"
                   FROM "public"."agreements"
                  WHERE (("agreements"."status")::"text" = ANY ((ARRAY['Current'::character varying, 'Expired'::character varying, 'Terminated'::character varying])::"text"[]))
                UNION
                 SELECT "ae"."employer_id"
                   FROM ("public"."agreement_employers" "ae"
                     JOIN "public"."agreements" "a" ON (("a"."agreement_id" = "ae"."agreement_id")))
                  WHERE (("a"."status")::"text" = ANY ((ARRAY['Current'::character varying, 'Expired'::character varying, 'Terminated'::character varying])::"text"[]))) "sub"
        )
 SELECT "ews"."employer_id",
    "ews"."worksite_id",
    "e"."employer_name",
    "ws"."worksite_name",
    "ws"."principal_employer_id",
    "pe"."employer_name" AS "principal_employer_name",
    "e"."parent_employer_id",
        CASE
            WHEN ("ews"."has_current" AND ("ews"."max_current_expiry" IS NOT NULL) AND ("ews"."max_current_expiry" < (CURRENT_DATE + '6 mons'::interval))) THEN 'expiry_lt_6m'::"text"
            WHEN ("ews"."has_current" AND ("ews"."max_current_expiry" IS NOT NULL) AND ("ews"."max_current_expiry" < (CURRENT_DATE + '1 year'::interval))) THEN 'expiry_6_12m'::"text"
            WHEN ("ews"."has_current" AND ("ews"."max_current_expiry" IS NOT NULL) AND ("ews"."max_current_expiry" < (CURRENT_DATE + '2 years'::interval))) THEN 'expiry_12_24m'::"text"
            WHEN "ews"."has_current" THEN 'expiry_gt_24m'::"text"
            WHEN ("ews"."has_bargaining" AND ("epa"."employer_id" IS NULL)) THEN 'first_bargaining'::"text"
            WHEN ("ews"."has_expired" OR "ews"."has_bargaining") THEN 'expired_eba'::"text"
            ELSE 'no_eba_no_bargaining'::"text"
        END AS "eba_status_category",
    "ews"."max_current_expiry",
    "ews"."has_current",
    "ews"."has_expired",
    "ews"."has_bargaining"
   FROM (((("employer_worksite_summary" "ews"
     JOIN "public"."employers" "e" ON (("e"."employer_id" = "ews"."employer_id")))
     JOIN "public"."worksites" "ws" ON (("ws"."worksite_id" = "ews"."worksite_id")))
     LEFT JOIN "public"."employers" "pe" ON (("pe"."employer_id" = "ws"."principal_employer_id")))
     LEFT JOIN "employer_has_prior_eba" "epa" ON (("epa"."employer_id" = "ews"."employer_id")));


ALTER VIEW "public"."worksite_employer_eba_status" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."principal_employer_eba_summary" AS
 WITH "pe_scope" AS (
         SELECT "ws"."principal_employer_id" AS "pe_id",
            "ewr"."employer_id",
            "ewr"."worksite_id"
           FROM ("public"."employer_worksite_roles" "ewr"
             JOIN "public"."worksites" "ws" ON (("ws"."worksite_id" = "ewr"."worksite_id")))
          WHERE (("ws"."principal_employer_id" IS NOT NULL) AND ("ewr"."is_current" = true))
        UNION
         SELECT "e"."parent_employer_id" AS "pe_id",
            "ewr"."employer_id",
            "ewr"."worksite_id"
           FROM ("public"."employers" "e"
             JOIN "public"."employer_worksite_roles" "ewr" ON (("ewr"."employer_id" = "e"."employer_id")))
          WHERE (("e"."parent_employer_id" IS NOT NULL) AND ("ewr"."is_current" = true))
        ), "scope_with_status" AS (
         SELECT DISTINCT "ps"."pe_id",
            "wees"."employer_id",
            "wees"."worksite_id",
            "wees"."eba_status_category"
           FROM ("pe_scope" "ps"
             JOIN "public"."worksite_employer_eba_status" "wees" ON ((("wees"."employer_id" = "ps"."employer_id") AND ("wees"."worksite_id" = "ps"."worksite_id"))))
        )
 SELECT "pe"."employer_id" AS "principal_employer_id",
    "pe"."employer_name" AS "principal_employer_name",
    "count"(*) AS "total_pairs",
    "count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'no_eba_no_bargaining'::"text")) AS "count_no_eba",
    "count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'first_bargaining'::"text")) AS "count_first_bargaining",
    "count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expired_eba'::"text")) AS "count_expired",
    "count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expiry_lt_6m'::"text")) AS "count_lt_6m",
    "count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expiry_6_12m'::"text")) AS "count_6_12m",
    "count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expiry_12_24m'::"text")) AS "count_12_24m",
    "count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expiry_gt_24m'::"text")) AS "count_gt_24m",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'no_eba_no_bargaining'::"text")))::numeric * 100.0) / ("count"(*))::numeric), 1)
            ELSE (0)::numeric
        END AS "pct_no_eba",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'first_bargaining'::"text")))::numeric * 100.0) / ("count"(*))::numeric), 1)
            ELSE (0)::numeric
        END AS "pct_first_bargaining",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expired_eba'::"text")))::numeric * 100.0) / ("count"(*))::numeric), 1)
            ELSE (0)::numeric
        END AS "pct_expired",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expiry_lt_6m'::"text")))::numeric * 100.0) / ("count"(*))::numeric), 1)
            ELSE (0)::numeric
        END AS "pct_lt_6m",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expiry_6_12m'::"text")))::numeric * 100.0) / ("count"(*))::numeric), 1)
            ELSE (0)::numeric
        END AS "pct_6_12m",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expiry_12_24m'::"text")))::numeric * 100.0) / ("count"(*))::numeric), 1)
            ELSE (0)::numeric
        END AS "pct_12_24m",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("sws"."eba_status_category" = 'expiry_gt_24m'::"text")))::numeric * 100.0) / ("count"(*))::numeric), 1)
            ELSE (0)::numeric
        END AS "pct_gt_24m"
   FROM ("public"."employers" "pe"
     JOIN "scope_with_status" "sws" ON (("sws"."pe_id" = "pe"."employer_id")))
  WHERE (("pe"."employer_category")::"text" = 'Principal_Employer'::"text")
  GROUP BY "pe"."employer_id", "pe"."employer_name";


