    CONSTRAINT "section_plans_archived_consistency_chk" CHECK (((("status" = 'archived'::"text") AND ("archived_at" IS NOT NULL)) OR (("status" <> 'archived'::"text") AND ("archived_at" IS NULL)))),
    CONSTRAINT "section_plans_dates_chk" CHECK (("end_date" >= "start_date")),
    CONSTRAINT "section_plans_status_chk" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'completed'::"text", 'archived'::"text"])))
);


ALTER TABLE "public"."section_plans" OWNER TO "postgres";


COMMENT ON TABLE "public"."section_plans" IS 'Phase 1 of the Section Planning module: period-scoped sibling planner. Each row scopes a stripped-back plan to a date range under one campaign. Sibling to campaign_stage_plans (P2W) — does NOT gate or interact with stage progression.';



COMMENT ON COLUMN "public"."section_plans"."purpose" IS '1-2 sentence description of why this period needs a discrete plan (e.g. "Pre-ballot surge", "Week beginning 4 May 2025").';



COMMENT ON COLUMN "public"."section_plans"."timeframe_kind" IS 'Drives the timeframe banner colour only — presentational, never gates progression. user_set = internal/flexible; user_set_firm = internal measure with external date; hard_external_deadline = externally controlled and measured (e.g. EBA ballot).';



COMMENT ON COLUMN "public"."section_plans"."external_anchor_label" IS 'Free-text label naming the external anchor when timeframe_kind is firm or hard (e.g. "Ballot opens", "First bargaining meeting", "NERR window closes"). NULL otherwise.';



