    "last_outbound_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "closed_by_user_id" "uuid",
    CONSTRAINT "sms_conversations_state_check" CHECK ((("state")::"text" = ANY ((ARRAY['needs_message'::character varying, 'messaged'::character varying, 'needs_response'::character varying, 'convo'::character varying, 'closed'::character varying, 'triage'::character varying])::"text"[])))
);


