CREATE TABLE IF NOT EXISTS "public"."sms_lists" (
    "list_id" integer NOT NULL,
    "campaign_id" integer NOT NULL,
    "draft_id" integer,
    "name" character varying(300) NOT NULL,
    "description" "text",
    "status" character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    "source_filters" "jsonb",
    "sender_number_id" integer,
    "timezone" "text" DEFAULT 'Australia/Perth'::"text" NOT NULL,
    "blackout_override" boolean DEFAULT false NOT NULL,
    "blackout_override_reason" "text",
    "scheduled_for" timestamp with time zone,
    "total_items" integer DEFAULT 0 NOT NULL,
    "sent_items" integer DEFAULT 0 NOT NULL,
    "delivered_items" integer DEFAULT 0 NOT NULL,
    "failed_items" integer DEFAULT 0 NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "mode" character varying(10) DEFAULT 'blast'::character varying NOT NULL,
    "selected_assessment_ids" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "assessment_campaign_id" integer,
    "relay_id" integer,
    "archived_at" timestamp with time zone,
    CONSTRAINT "sms_lists_mode_check" CHECK ((("mode")::"text" = ANY ((ARRAY['blast'::character varying, 'p2p'::character varying])::"text"[]))),
    CONSTRAINT "sms_lists_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'queued'::character varying, 'sending'::character varying, 'sent'::character varying, 'paused'::character varying, 'cancelled'::character varying])::"text"[])))
);


ALTER TABLE "public"."sms_lists" OWNER TO "postgres";


COMMENT ON TABLE "public"."sms_lists" IS 'Persistent recipient lists for SMS broadcasts. Mirrors email_lists; queued/sending lists are drained by /api/cron/dispatch-sms-queue.';



COMMENT ON COLUMN "public"."sms_lists"."mode" IS 'blast = bulk broadcast drained by the dispatch cron. p2p = chat-board working list: initials are sent progressively per organiser selection via the p2p-send route; the list stays in status draft while the board is active and flips to sent when closed — it must never reach queued/sending, which is what the cron drains.';



COMMENT ON COLUMN "public"."sms_lists"."selected_assessment_ids" IS 'P2P chat boards: campaign_activities ids (activity_kind=''assessment'') pinned to this board and rendered one-tap in the chat workspace member pane. Ignored for mode=''blast''. Postgres cannot FK an array element, so membership is validated in the PATCH route and stale ids are filtered on read — an assessment deleted mid-session must degrade the pinned control, never break the board.';



COMMENT ON COLUMN "public"."sms_lists"."assessment_campaign_id" IS 'Standalone chat boards only: the REAL campaign whose assessments this board''s ratings are recorded against. Standalone sends hang off hidden is_sms_episode campaigns (see lib/sms/sms-episode.ts), which have no assessment activities and never appear on a wall chart, so rating against them would produce invisible data. NULL means "use sms_lists.campaign_id" — the normal case for a campaign chat. Set only when the list''s own campaign is_sms_episode; the PATCH route rejects it otherwise. ON DELETE SET NULL degrades the board to "nominate a campaign again" rather than orphaning it.';



COMMENT ON COLUMN "public"."sms_lists"."relay_id" IS 'When set, this blast is a launch text for the relay: it invites members to text the relay number. A relay may have several (launch, reminder). The relay number is a permitted sender ONLY for lists carrying its relay_id.';



COMMENT ON COLUMN "public"."sms_lists"."archived_at" IS 'Hygiene archive. NULL = in the default SMS Tools list. Set only when the blast/board is inert (sent/cancelled; chat boards closed). Does not stop inbound threads or unwind ratings.';



