CREATE TABLE IF NOT EXISTS "public"."sms_surveys" (
    "survey_id" integer NOT NULL,
    "campaign_id" integer NOT NULL,
    "activity_id" integer,
    "title" character varying(200) NOT NULL,
    "purpose" character varying(20) DEFAULT 'survey'::character varying NOT NULL,
    "status" character varying(10) DEFAULT 'draft'::character varying NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "retry_limit" integer DEFAULT 2 NOT NULL,
    "question_timeout_minutes" integer DEFAULT 240 NOT NULL,
    "session_ttl_hours" integer DEFAULT 72 NOT NULL,
    "reminder_offsets" "jsonb" DEFAULT '[1440, 2880]'::"jsonb" NOT NULL,
    "handoff_escalate_to" "uuid",
    "sender_number_id" integer,
    "timezone" character varying(50) DEFAULT 'Australia/Perth'::character varying NOT NULL,
    "blackout_override" boolean DEFAULT false NOT NULL,
    "blackout_override_reason" "text",
    "invitation_body" "text",
    "completion_body" "text",
    "opened_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revote_policy" character varying(20) DEFAULT 'locked'::character varying NOT NULL,
    "receipt_salt" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "results_restricted" boolean DEFAULT false NOT NULL,
    "source_worker_list_id" integer,
    "is_test" boolean DEFAULT true NOT NULL,
    "pause_mode" character varying(10),
    "paused_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    CONSTRAINT "chk_sms_surveys_revote_policy" CHECK ((("revote_policy")::"text" = ANY ((ARRAY['locked'::character varying, 'revote_until_close'::character varying])::"text"[]))),
    CONSTRAINT "sms_surveys_pause_mode_check" CHECK ((("pause_mode" IS NULL) OR (("pause_mode")::"text" = ANY ((ARRAY['soft'::character varying, 'hard'::character varying])::"text"[])))),
    CONSTRAINT "sms_surveys_purpose_check" CHECK ((("purpose")::"text" = ANY ((ARRAY['survey'::character varying, 'indicative_ballot'::character varying])::"text"[]))),
    CONSTRAINT "sms_surveys_question_timeout_minutes_check" CHECK ((("question_timeout_minutes" >= 10) AND ("question_timeout_minutes" <= 10080))),
    CONSTRAINT "sms_surveys_retry_limit_check" CHECK ((("retry_limit" >= 0) AND ("retry_limit" <= 5))),
    CONSTRAINT "sms_surveys_session_ttl_hours_check" CHECK ((("session_ttl_hours" >= 1) AND ("session_ttl_hours" <= 720))),
    CONSTRAINT "sms_surveys_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'open'::character varying, 'paused'::character varying, 'closed'::character varying])::"text"[])))
);


ALTER TABLE "public"."sms_surveys" OWNER TO "postgres";


COMMENT ON TABLE "public"."sms_surveys" IS 'Reply-native SMS survey definitions (brief §4.1). purpose ''indicative_ballot'' is reserved for Phase 5 ballot mode. Definitions are immutable once opened; sessions pin version.';



COMMENT ON COLUMN "public"."sms_surveys"."revote_policy" IS 'Ballot revote policy (§4.2): locked = one vote per member (default, §8.1); revote_until_close = last response wins, supersessions logged in sms_ballot_events.';



COMMENT ON COLUMN "public"."sms_surveys"."receipt_salt" IS 'Per-ballot salt for completion receipt hashes — sha256(salt|worker_id|ordered parsed answers), first 10 hex chars. Receipts are recomputed on read, never stored.';



COMMENT ON COLUMN "public"."sms_surveys"."results_restricted" IS 'When true the UI renders no per-member answer surface for this ballot; vw_sms_ballot_tally is the only reporting surface. NOTE: sms_survey_answers remains staff-readable (confidential, not anonymous — brief §4.2, accepted §8.1).';



COMMENT ON COLUMN "public"."sms_surveys"."source_worker_list_id" IS 'The campaign_worker_lists cohort this draft survey was fired from (Build List -> SMS -> Survey pathway), if any. Provenance / default-audience-selection hint only: the survey eligibility roll is frozen fresh at OPEN time by POST /api/campaigns/[id]/sms-surveys/[surveyId]/actions, which is the sole source of truth for who was invited. This column is never read by that freeze logic.';



