    CONSTRAINT "upcoming_projects_scrape_runs_status_check" CHECK (("status" = ANY (ARRAY['running'::"text", 'success'::"text", 'partial'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."upcoming_projects_scrape_runs" OWNER TO "postgres";


CREATE SEQUENCE IF NOT EXISTS "public"."upcoming_projects_scrape_runs_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE "public"."upcoming_projects_scrape_runs_id_seq" OWNER TO "postgres";


ALTER SEQUENCE "public"."upcoming_projects_scrape_runs_id_seq" OWNED BY "public"."upcoming_projects_scrape_runs"."id";



CREATE TABLE IF NOT EXISTS "public"."user_oauth_connections" (
    "connection_id" bigint NOT NULL,
    "user_id" "uuid" NOT NULL,
    "provider" "text" NOT NULL,
    "provider_user_id" "text" NOT NULL,
    "email" "text",
    "display_name" "text",
    "tenant_id" "text",
    "scopes" "text" NOT NULL,
    "access_token_ct" "text",
    "access_token_expires_at" timestamp with time zone,
    "refresh_token_ct" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "last_error" "text",
    "last_used_at" timestamp with time zone,
    "connected_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_polled_at" timestamp with time zone,
    CONSTRAINT "user_oauth_connections_provider_check" CHECK (("provider" = ANY (ARRAY['microsoft'::"text", 'google'::"text"]))),
    CONSTRAINT "user_oauth_connections_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'revoked'::"text", 'error'::"text"])))
);


ALTER TABLE "public"."user_oauth_connections" OWNER TO "postgres";


COMMENT ON TABLE "public"."user_oauth_connections" IS 'Per-user OAuth refresh + access tokens for outbound integrations (Microsoft Graph, Gmail). Encrypted at rest with OAUTH_TOKEN_ENCRYPTION_KEY (server env). One row per (user, provider).';



COMMENT ON COLUMN "public"."user_oauth_connections"."access_token_ct" IS 'AES-256-GCM ciphertext of the cached access token. Short-lived (~1h for MS); refreshed on demand if expired.';



COMMENT ON COLUMN "public"."user_oauth_connections"."refresh_token_ct" IS 'AES-256-GCM ciphertext of the refresh token, base64-encoded as iv|ciphertext|authTag. Never logged.';



CREATE SEQUENCE IF NOT EXISTS "public"."user_oauth_connections_connection_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE "public"."user_oauth_connections_connection_id_seq" OWNER TO "postgres";


ALTER SEQUENCE "public"."user_oauth_connections_connection_id_seq" OWNED BY "public"."user_oauth_connections"."connection_id";



CREATE OR REPLACE VIEW "public"."v_bargaining_progress" AS
 SELECT "c"."campaign_id",
    "c"."name" AS "campaign_name",
    ("c"."current_phase")::"text" AS "current_phase",
    "c"."bargaining_commenced_at",
    "sa"."assessed_at" AS "last_strength_assessed_at",
    "sa"."outcome" AS "last_strength_verdict",
    ( SELECT "count"(*) AS "count"
           FROM "public"."bargaining_decision_points" "dp"
          WHERE (("dp"."campaign_id" = "c"."campaign_id") AND ("dp"."resolution" = 'pending'::"text"))) AS "open_decision_count",
    ( SELECT "pabo_applications"."status"
           FROM "public"."pabo_applications"
          WHERE ("pabo_applications"."campaign_id" = "c"."campaign_id")
          ORDER BY "pabo_applications"."created_at" DESC
         LIMIT 1) AS "latest_pabo_status",
    ( SELECT "member_endorsement_votes"."outcome"
           FROM "public"."member_endorsement_votes"
          WHERE ("member_endorsement_votes"."campaign_id" = "c"."campaign_id")
          ORDER BY "member_endorsement_votes"."vote_closes_at" DESC NULLS LAST
         LIMIT 1) AS "latest_vote_outcome",
    ( SELECT "count"(*) AS "count"
           FROM "public"."pia_actions"
          WHERE (("pia_actions"."campaign_id" = "c"."campaign_id") AND ("pia_actions"."is_concluded" = false))) AS "active_pia_count",
    "ibt"."state" AS "intractable_status",
    (CURRENT_DATE - "ibt"."bargaining_commenced_at") AS "intractable_days_elapsed"
   FROM (("public"."campaigns" "c"
     LEFT JOIN LATERAL ( SELECT "bargaining_strength_assessments"."assessed_at",
            "bargaining_strength_assessments"."outcome"
           FROM "public"."bargaining_strength_assessments"
          WHERE ("bargaining_strength_assessments"."campaign_id" = "c"."campaign_id")
          ORDER BY "bargaining_strength_assessments"."assessed_at" DESC
         LIMIT 1) "sa" ON (true))
     LEFT JOIN "public"."intractable_bargaining_tracker" "ibt" ON (("ibt"."campaign_id" = "c"."campaign_id")))
  WHERE ("c"."current_phase" = 'bargaining_to_win'::"public"."campaign_phase_enum");


ALTER VIEW "public"."v_bargaining_progress" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_bargaining_progress" IS 'Per-campaign bargaining KPIs for the reports dashboard. One row per campaign in current_phase = bargaining_to_win. Aggregates strength verdict, open decision count, PABO status, latest vote outcome, active PIA count, and intractable state.';



CREATE TABLE IF NOT EXISTS "public"."woc_members" (
    "woc_member_id" bigint NOT NULL,
    "woc_id" bigint NOT NULL,
    "worker_id" integer NOT NULL,
    "woc_role" "text" DEFAULT 'member'::"text" NOT NULL,
    "joined_on" "date" DEFAULT CURRENT_DATE NOT NULL,
    "left_on" "date",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "woc_members_woc_role_check" CHECK (("woc_role" = ANY (ARRAY['chair'::"text", 'mapper'::"text", 'comms_steward'::"text", 'recruitment_lead'::"text", 'member'::"text"])))
);


ALTER TABLE "public"."woc_members" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_campaign_activist_register" WITH ("security_invoker"='true') AS
 SELECT "p"."profile_id",
    "p"."campaign_id",
    "p"."worker_id",
    ((("w"."first_name")::"text" || ' '::"text") || ("w"."last_name")::"text") AS "worker_name",
    "w"."member_role_type_id",
    "mrt"."role_name",
    "mrt"."display_name" AS "role_display_name",
    "umt"."type_name" AS "union_membership_type",
    "w"."is_hsr",
    "w"."is_bargaining_rep",
    "cwrs"."cumulative_rating" AS "current_rating",
    "p"."source",
    "p"."is_archived",
    "p"."identified_via",
    "p"."recruited_by",
    "p"."recruited_by_text",
    "p"."recruited_at",
    "p"."domain",
    "p"."followers_evidence",
    "p"."skab_notes",
    "p"."current_rung",
    "p"."four_a_stage",
    "p"."last_contact_date",
    "p"."next_contact_date",
    "p"."notes",
    "p"."created_at",
    "p"."updated_at",
    "t"."activist_task_id" AS "current_task_id",
    "t"."responsibility" AS "current_task_responsibility",
    "t"."rung" AS "current_task_rung",
    "t"."due_date" AS "current_task_due",
    "t"."status" AS "current_task_status",
    "wm"."woc_ids",
    "wm"."woc_names"
   FROM (((((("public"."campaign_activist_profiles" "p"
     JOIN "public"."workers" "w" ON (("w"."worker_id" = "p"."worker_id")))
     LEFT JOIN "public"."member_role_types" "mrt" ON (("mrt"."role_type_id" = "w"."member_role_type_id")))
     LEFT JOIN "public"."union_membership_types" "umt" ON (("umt"."union_membership_type_id" = "w"."union_membership_type_id")))
     LEFT JOIN "public"."campaign_worker_rating_summary" "cwrs" ON ((("cwrs"."campaign_id" = "p"."campaign_id") AND ("cwrs"."worker_id" = "p"."worker_id"))))
     LEFT JOIN LATERAL ( SELECT "activist_tasks"."activist_task_id",
            "activist_tasks"."responsibility",
            "activist_tasks"."rung",
            "activist_tasks"."due_date",
            "activist_tasks"."status"
           FROM "public"."activist_tasks"
          WHERE (("activist_tasks"."campaign_id" = "p"."campaign_id") AND ("activist_tasks"."worker_id" = "p"."worker_id") AND ("activist_tasks"."status" = ANY (ARRAY['draft'::"text", 'assigned'::"text", 'in_progress'::"text"])))
          ORDER BY COALESCE("activist_tasks"."assigned_at", ("activist_tasks"."created_at")::"date") DESC, "activist_tasks"."activist_task_id" DESC
         LIMIT 1) "t" ON (true))
     LEFT JOIN LATERAL ( SELECT "array_agg"("cw"."woc_id") AS "woc_ids",
            "array_agg"("cw"."name") AS "woc_names"
           FROM ("public"."woc_members" "m"
             JOIN "public"."campaign_wocs" "cw" ON (("cw"."woc_id" = "m"."woc_id")))
          WHERE (("m"."worker_id" = "p"."worker_id") AND ("cw"."campaign_id" = "p"."campaign_id") AND ("m"."left_on" IS NULL))) "wm" ON (true));


ALTER VIEW "public"."v_campaign_activist_register" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_campaign_coverage_map" WITH ("security_invoker"='true') AS
 SELECT "cou"."campaign_id",
    "cou"."ou_id",
    "cou"."name" AS "ou_name",
    "cou"."ou_type",
    "cou"."parent_ou_id",
    COALESCE("cou"."is_group_container", false) AS "is_group_container",
    "cou"."total_workers_estimated",
    "counts"."assigned_workers",
    "counts"."member_count",
        CASE
            WHEN (COALESCE("counts"."assigned_workers", (0)::bigint) = 0) THEN NULL::numeric
            ELSE "round"((("counts"."member_count")::numeric / ("counts"."assigned_workers")::numeric), 3)
        END AS "density",
    "cov"."leader_worker_id",
    ((("lw"."first_name")::"text" || ' '::"text") || ("lw"."last_name")::"text") AS "leader_name",
    "leader_rating"."cumulative_rating" AS "leader_rating",
    "cov"."second_worker_id",
    ((("sw"."first_name")::"text" || ' '::"text") || ("sw"."last_name")::"text") AS "second_name",
    "cov"."reachable_48h",
    "cov"."priority_action",
        CASE
            WHEN ("cov"."leader_worker_id" IS NULL) THEN 'gap'::"text"
            WHEN ("cov"."second_worker_id" IS NULL) THEN 'leader_no_second'::"text"
            ELSE 'covered'::"text"
        END AS "coverage_status"
   FROM ((((("public"."campaign_organising_units" "cou"
     LEFT JOIN "public"."campaign_ou_coverage" "cov" ON (("cov"."ou_id" = "cou"."ou_id")))
     LEFT JOIN "public"."workers" "lw" ON (("lw"."worker_id" = "cov"."leader_worker_id")))
     LEFT JOIN "public"."workers" "sw" ON (("sw"."worker_id" = "cov"."second_worker_id")))
     LEFT JOIN "public"."campaign_worker_rating_summary" "leader_rating" ON ((("leader_rating"."campaign_id" = "cou"."campaign_id") AND ("leader_rating"."worker_id" = "cov"."leader_worker_id"))))
     LEFT JOIN LATERAL ( SELECT "count"(DISTINCT "cwo"."worker_id") AS "assigned_workers",
            "count"(DISTINCT "cwo"."worker_id") FILTER (WHERE (("umt"."type_name")::"text" = ANY ((ARRAY['financial_member'::character varying, 'member_pending'::character varying])::"text"[]))) AS "member_count"
           FROM (("public"."campaign_worker_ou" "cwo"
             JOIN "public"."workers" "w" ON (("w"."worker_id" = "cwo"."worker_id")))
             LEFT JOIN "public"."union_membership_types" "umt" ON (("umt"."union_membership_type_id" = "w"."union_membership_type_id")))
          WHERE ("cwo"."ou_id" = "cou"."ou_id")) "counts" ON (true));


ALTER VIEW "public"."v_campaign_coverage_map" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_campaign_coverage_summary" WITH ("security_invoker"='true') AS
 SELECT "campaign_id",
    "count"(*) AS "units_mapped",
    "count"(*) FILTER (WHERE ("coverage_status" = 'covered'::"text")) AS "units_covered",
    "count"(*) FILTER (WHERE ("coverage_status" = 'leader_no_second'::"text")) AS "units_leader_no_second",
    "count"(*) FILTER (WHERE ("coverage_status" = 'gap'::"text")) AS "units_gap",
    "sum"(COALESCE("assigned_workers", (0)::bigint)) AS "workers_mapped",
    "sum"(COALESCE("member_count", (0)::bigint)) AS "members",
        CASE
            WHEN ("sum"(COALESCE("assigned_workers", (0)::bigint)) = (0)::numeric) THEN NULL::numeric
            ELSE "round"(("sum"(COALESCE("member_count", (0)::bigint)) / "sum"(COALESCE("assigned_workers", (0)::bigint))), 3)
        END AS "overall_density"
   FROM "public"."v_campaign_coverage_map" "m"
  WHERE ("is_group_container" = false)
  GROUP BY "campaign_id";


ALTER VIEW "public"."v_campaign_coverage_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_campaign_foundational_readiness" WITH ("security_invoker"='true') AS
 SELECT "campaign_id",
    (COALESCE(( SELECT "sum"("ou"."total_workers_estimated") AS "sum"
           FROM "public"."campaign_organising_units" "ou"
          WHERE (("ou"."campaign_id" = "c"."campaign_id") AND ("ou"."total_workers_estimated" IS NOT NULL))), (0)::bigint))::integer AS "universe_size",
    (( SELECT "count"(DISTINCT "cwm"."worker_id") AS "count"
           FROM "public"."campaign_worker_membership" "cwm"
          WHERE ("cwm"."campaign_id" = "c"."campaign_id")))::integer AS "workers_allocated",
    (( SELECT "count"(DISTINCT "cwm"."worker_id") AS "count"
           FROM ("public"."campaign_worker_membership" "cwm"
             JOIN "public"."workers" "w" ON (("w"."worker_id" = "cwm"."worker_id")))
          WHERE (("cwm"."campaign_id" = "c"."campaign_id") AND ((("w"."phone" IS NOT NULL) AND (("w"."phone")::"text" <> ''::"text")) OR (("w"."email" IS NOT NULL) AND (("w"."email")::"text" <> ''::"text"))))))::integer AS "workers_with_contact",
    (( SELECT "count"(DISTINCT "cwrs"."worker_id") AS "count"
           FROM "public"."campaign_worker_rating_summary" "cwrs"
          WHERE (("cwrs"."campaign_id" = "c"."campaign_id") AND ("cwrs"."cumulative_rating" IS NOT NULL))))::integer AS "workers_with_rating",
    (( SELECT "count"(*) AS "count"
           FROM "public"."campaign_organising_units" "ou"
          WHERE (("ou"."campaign_id" = "c"."campaign_id") AND ("ou"."anchor_worker_id" IS NULL))))::integer AS "ous_missing_leaders"
   FROM "public"."campaigns" "c";


ALTER VIEW "public"."v_campaign_foundational_readiness" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_campaign_foundational_readiness" IS 'Per-campaign readiness snapshot for the Phase 2 bargaining hub. Five metrics: universe_size (sum of OU estimates), workers_allocated (campaign_worker_membership headcount), workers_with_contact (have phone or email), workers_with_rating (have a cumulative_rating), ous_missing_leaders (no anchor_worker_id). security_invoker=true so RLS on underlying tables is inherited.';



CREATE OR REPLACE VIEW "public"."v_campaign_section_stage_coverage" WITH ("security_invoker"='on') AS
 SELECT "sp"."campaign_id",
    "sp"."section_plan_id",
    "sp"."name" AS "section_name",
    "sp"."status" AS "section_status",
    "m"."stage_number",
    ("count"(*))::integer AS "subject_count",
    "array_agg"(DISTINCT "m"."subject_kind") AS "subject_kinds",
    ("avg"("m"."confidence"))::numeric(3,2) AS "avg_confidence",
    "bool_or"("m"."human_confirmed") AS "any_confirmed"
   FROM ("public"."section_plans" "sp"
     JOIN "public"."section_plan_stage_mappings" "m" ON (("m"."section_plan_id" = "sp"."section_plan_id")))
  GROUP BY "sp"."campaign_id", "sp"."section_plan_id", "sp"."name", "sp"."status", "m"."stage_number";


ALTER VIEW "public"."v_campaign_section_stage_coverage" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_intractable_state" AS
 SELECT "campaign_id",
    (CURRENT_DATE - "bargaining_commenced_at") AS "days_elapsed",
    ("nine_month_threshold_at" - CURRENT_DATE) AS "days_remaining_to_threshold",
    "state",
        CASE "state"
            WHEN 'safe'::"text" THEN 'On track'::"text"
            WHEN 'approaching'::"text" THEN 'Approaching threshold'::"text"
            WHEN 'eligible'::"text" THEN 'Eligible — threshold reached'::"text"
            WHEN 'applied'::"text" THEN 'Application filed'::"text"
            WHEN 'declared'::"text" THEN 'Intractable declared'::"text"
            WHEN 'arbitrated'::"text" THEN 'Arbitrated'::"text"
            ELSE 'Unknown'::"text"
        END AS "state_label",
        CASE "state"
            WHEN 'safe'::"text" THEN (((('Bargaining commenced '::"text" || ((CURRENT_DATE - "bargaining_commenced_at"))::"text") || ' days ago — '::"text") || (("nine_month_threshold_at" - CURRENT_DATE))::"text") || ' days to threshold'::"text")
            WHEN 'approaching'::"text" THEN (('Approaching 9-month threshold — '::"text" || (("nine_month_threshold_at" - CURRENT_DATE))::"text") || ' days remaining'::"text")
            WHEN 'eligible'::"text" THEN 'Threshold reached — intractable application may be filed'::"text"
            WHEN 'applied'::"text" THEN ('Intractable application filed '::"text" || "to_char"(("intractable_application_filed_at")::timestamp with time zone, 'DD Mon YYYY'::"text"))
            WHEN 'declared'::"text" THEN ('Intractable bargaining declared '::"text" || "to_char"(("intractable_declaration_made_at")::timestamp with time zone, 'DD Mon YYYY'::"text"))
            WHEN 'arbitrated'::"text" THEN ('Arbitration outcome recorded '::"text" || "to_char"(("arbitration_outcome_recorded_at")::timestamp with time zone, 'DD Mon YYYY'::"text"))
            ELSE 'Bargaining status unknown'::"text"
        END AS "headline",
    "bargaining_commenced_at",
    "nine_month_threshold_at",
    "intractable_application_filed_at",
    "intractable_declaration_made_at",
    "arbitration_outcome_recorded_at",
    "last_reviewed_at",
    "notes"
   FROM "public"."intractable_bargaining_tracker" "ibt";


ALTER VIEW "public"."v_intractable_state" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_intractable_state" IS 'Computed view over intractable_bargaining_tracker. Exposes days_elapsed, days_remaining_to_threshold, state_label, and a human-readable headline for the IntractableBannerCard UI component.';



CREATE OR REPLACE VIEW "public"."v_pia_participation_by_action" WITH ("security_invoker"='true') AS
 SELECT "pa"."action_id",
    "pa"."campaign_id",
    "pa"."action_type",
    "pa"."escalation_level",
    "pa"."action_starts_at",
    "pa"."is_concluded",
    "count"(
        CASE
            WHEN ((("car"."rating_phase")::"text" = 'expected'::"text") AND (("car"."binary_value")::"text" = 'true'::"text")) THEN 1
            ELSE NULL::integer
        END) AS "total_pledged",
    "count"(
        CASE
            WHEN ((("car"."rating_phase")::"text" = 'actual'::"text") AND (("car"."binary_value")::"text" = 'true'::"text")) THEN 1
            ELSE NULL::integer
        END) AS "total_participated",
        CASE
            WHEN ("count"(
            CASE
                WHEN ((("car"."rating_phase")::"text" = 'expected'::"text") AND (("car"."binary_value")::"text" = 'true'::"text")) THEN 1
                ELSE NULL::integer
            END) > 0) THEN "round"(((("count"(
            CASE
                WHEN ((("car"."rating_phase")::"text" = 'actual'::"text") AND (("car"."binary_value")::"text" = 'true'::"text")) THEN 1
                ELSE NULL::integer
            END))::numeric / ("count"(
            CASE
                WHEN ((("car"."rating_phase")::"text" = 'expected'::"text") AND (("car"."binary_value")::"text" = 'true'::"text")) THEN 1
                ELSE NULL::integer
            END))::numeric) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS "participation_rate",
        CASE
            WHEN ("cm"."total_workers" > 0) THEN "round"(((("count"(
            CASE
                WHEN ((("car"."rating_phase")::"text" = 'actual'::"text") AND (("car"."binary_value")::"text" = 'true'::"text")) THEN 1
                ELSE NULL::integer
            END))::numeric / ("cm"."total_workers")::numeric) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS "percent_membership"
   FROM ((("public"."pia_actions" "pa"
     LEFT JOIN "public"."activity_events" "ae" ON (("ae"."pia_action_id" = "pa"."action_id")))
     LEFT JOIN "public"."campaign_activity_ratings" "car" ON (("car"."event_id" = "ae"."event_id")))
     LEFT JOIN ( SELECT "campaign_worker_membership"."campaign_id",
            "count"(*) AS "total_workers"
           FROM "public"."campaign_worker_membership"
          GROUP BY "campaign_worker_membership"."campaign_id") "cm" ON (("cm"."campaign_id" = "pa"."campaign_id")))
  GROUP BY "pa"."action_id", "pa"."campaign_id", "pa"."action_type", "pa"."escalation_level", "pa"."action_starts_at", "pa"."is_concluded", "cm"."total_workers";


ALTER VIEW "public"."v_pia_participation_by_action" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_pia_participation_by_action" IS 'Aggregates pledged vs participated counts per pia_actions row. total_pledged = expected binary ratings; total_participated = actual binary ratings. participation_rate = actual/pledged × 100. percent_membership = actual / campaign_worker_membership count × 100.';



CREATE OR REPLACE VIEW "public"."v_section_plan_soc_recording_grid" WITH ("security_invoker"='on') AS
 SELECT "s"."soc_id",
    "sp"."section_plan_id",
    "sp"."campaign_id",
    "s"."soc_kind",
    "s"."name" AS "soc_name",
    "w"."worker_id",
    ((("w"."first_name")::"text" || ' '::"text") || ("w"."last_name")::"text") AS "worker_name",
    "w"."member_role_type_id",
    "cwrs"."cumulative_rating" AS "current_rating",
    "r"."no_vote_rating",
    "r"."pabo_rating",
    "r"."member_status_confirmed",
    "r"."notes",
    "r"."recorded_at",
    "r"."activity_event_id"
   FROM ((((("public"."section_plan_socs" "s"
     JOIN "public"."section_plans" "sp" ON (("sp"."section_plan_id" = "s"."section_plan_id")))
     JOIN "public"."campaign_worker_membership" "cwm" ON (("cwm"."campaign_id" = "sp"."campaign_id")))
     JOIN "public"."workers" "w" ON (("w"."worker_id" = "cwm"."worker_id")))
     LEFT JOIN "public"."campaign_worker_rating_summary" "cwrs" ON ((("cwrs"."campaign_id" = "sp"."campaign_id") AND ("cwrs"."worker_id" = "w"."worker_id"))))
     LEFT JOIN LATERAL ( SELECT "section_plan_soc_recordings"."no_vote_rating",
            "section_plan_soc_recordings"."pabo_rating",
            "section_plan_soc_recordings"."member_status_confirmed",
            "section_plan_soc_recordings"."notes",
            "section_plan_soc_recordings"."recorded_at",
            "section_plan_soc_recordings"."activity_event_id"
           FROM "public"."section_plan_soc_recordings"
          WHERE (("section_plan_soc_recordings"."soc_id" = "s"."soc_id") AND ("section_plan_soc_recordings"."worker_id" = "w"."worker_id"))
          ORDER BY "section_plan_soc_recordings"."recorded_at" DESC
         LIMIT 1) "r" ON (true));


ALTER VIEW "public"."v_section_plan_soc_recording_grid" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_section_plan_summary" WITH ("security_invoker"='on') AS
 SELECT "sp"."section_plan_id",
    "sp"."campaign_id",
    "sp"."name",
    "sp"."status",
    "sp"."timeframe_kind",
    "sp"."start_date",
    "sp"."end_date",
    COALESCE("amb"."cnt", 0) AS "ambitions_count",
    COALESCE("wtp"."cnt", 0) AS "wtp_count",
    COALESCE("cap"."cnt", 0) AS "capacities_count",
        CASE
            WHEN ("tow"."theory_id" IS NOT NULL) THEN 1
            ELSE 0
        END AS "theories_count",
    COALESCE("act"."cnt", 0) AS "activities_count"
   FROM ((((("public"."section_plans" "sp"
     LEFT JOIN ( SELECT "plan_ambitions"."section_plan_id",
            ("count"(*))::integer AS "cnt"
           FROM "public"."plan_ambitions"
          WHERE ("plan_ambitions"."section_plan_id" IS NOT NULL)
          GROUP BY "plan_ambitions"."section_plan_id") "amb" ON (("amb"."section_plan_id" = "sp"."section_plan_id")))
     LEFT JOIN ( SELECT "plan_where_to_play"."section_plan_id",
            ("count"(*))::integer AS "cnt"
           FROM "public"."plan_where_to_play"
          WHERE ("plan_where_to_play"."section_plan_id" IS NOT NULL)
          GROUP BY "plan_where_to_play"."section_plan_id") "wtp" ON (("wtp"."section_plan_id" = "sp"."section_plan_id")))
     LEFT JOIN ( SELECT "plan_capacities"."section_plan_id",
            ("count"(*))::integer AS "cnt"
           FROM "public"."plan_capacities"
          WHERE ("plan_capacities"."section_plan_id" IS NOT NULL)
          GROUP BY "plan_capacities"."section_plan_id") "cap" ON (("cap"."section_plan_id" = "sp"."section_plan_id")))
     LEFT JOIN LATERAL ( SELECT "plan_theory_of_winning"."theory_id"
           FROM "public"."plan_theory_of_winning"
          WHERE (("plan_theory_of_winning"."section_plan_id" = "sp"."section_plan_id") AND (COALESCE("plan_theory_of_winning"."is_current", true) = true))
          ORDER BY "plan_theory_of_winning"."version" DESC NULLS LAST
         LIMIT 1) "tow" ON (true))
     LEFT JOIN ( SELECT "campaign_activities"."section_plan_id",
            ("count"(*))::integer AS "cnt"
           FROM "public"."campaign_activities"
          WHERE ("campaign_activities"."section_plan_id" IS NOT NULL)
          GROUP BY "campaign_activities"."section_plan_id") "act" ON (("act"."section_plan_id" = "sp"."section_plan_id")));


ALTER VIEW "public"."v_section_plan_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_section_plan_workforce_mapping" WITH ("security_invoker"='on') AS
 SELECT "ou"."campaign_id",
    "ou"."ou_id" AS "worksite_ou_id",
    "ou"."name" AS "worksite_name",
    "ou"."total_workers_estimated",
    ("count"(DISTINCT "cwo"."worker_id"))::integer AS "workers_count",
    ("count"(DISTINCT
        CASE
            WHEN ("w"."member_role_type_id" IS NOT NULL) THEN "cwo"."worker_id"
            ELSE NULL::integer
        END))::integer AS "members_count",
        CASE
            WHEN ("count"(DISTINCT "cwo"."worker_id") = 0) THEN NULL::numeric
            ELSE "round"(((100.0 * ("count"(DISTINCT
            CASE
                WHEN ("w"."member_role_type_id" IS NOT NULL) THEN "cwo"."worker_id"
                ELSE NULL::integer
            END))::numeric) / ("count"(DISTINCT "cwo"."worker_id"))::numeric), 1)
        END AS "density_pct",
    ("count"(DISTINCT
        CASE
            WHEN ("w"."member_role_type_id" IS NULL) THEN "cwo"."worker_id"
            ELSE NULL::integer
        END))::integer AS "non_member_count",
    ("count"(DISTINCT
        CASE
            WHEN ("cwrs"."cumulative_rating" IS NULL) THEN "cwo"."worker_id"
            ELSE NULL::integer
        END))::integer AS "unrated_count"
   FROM ((("public"."campaign_organising_units" "ou"
     LEFT JOIN "public"."campaign_worker_ou" "cwo" ON (("cwo"."ou_id" = "ou"."ou_id")))
     LEFT JOIN "public"."workers" "w" ON (("w"."worker_id" = "cwo"."worker_id")))
     LEFT JOIN "public"."campaign_worker_rating_summary" "cwrs" ON ((("cwrs"."campaign_id" = "ou"."campaign_id") AND ("cwrs"."worker_id" = "cwo"."worker_id"))))
  WHERE (("ou"."ou_type")::"text" = 'worksite'::"text")
  GROUP BY "ou"."campaign_id", "ou"."ou_id", "ou"."name", "ou"."total_workers_estimated";


ALTER VIEW "public"."v_section_plan_workforce_mapping" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_section_plan_workplan" WITH ("security_invoker"='on') AS
 SELECT "t"."target_id",
    "t"."section_plan_id",
    "t"."day_of_week",
    "t"."target_date",
    "t"."activity_id",
    "t"."activity_label",
    "t"."calls_target",
    "t"."notes",
    "ca"."title" AS "activity_title",
    "ca"."activity_kind",
        CASE
            WHEN ("t"."activity_id" IS NULL) THEN NULL::integer
            ELSE COALESCE("ev"."completed", 0)
        END AS "completed_count",
    COALESCE("ev"."outcomes_summary", NULL::"text") AS "outcomes_summary"
   FROM (("public"."section_plan_workplan_targets" "t"
     LEFT JOIN "public"."campaign_activities" "ca" ON (("ca"."activity_id" = "t"."activity_id")))
     LEFT JOIN LATERAL ( SELECT ("count"(*) FILTER (WHERE ("e"."is_concluded" = true)))::integer AS "completed",
            "string_agg"(DISTINCT NULLIF(("e"."outcome" ->> 'outcome'::"text"), ''::"text"), ', '::"text") AS "outcomes_summary"
           FROM "public"."activity_events" "e"
          WHERE (("e"."activity_id" = "t"."activity_id") AND (("e"."scheduled_at")::"date" = "t"."target_date"))) "ev" ON (true));


ALTER VIEW "public"."v_section_plan_workplan" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_strength_assessment_inputs" WITH ("security_invoker"='true') AS
 WITH "rating_counts" AS (
         SELECT "campaign_worker_rating_summary"."campaign_id",
            "count"(*) AS "eligible_count",
            "count"(*) FILTER (WHERE ("campaign_worker_rating_summary"."cumulative_rating" = 1)) AS "supportive_leader_count",
            "count"(*) FILTER (WHERE ("campaign_worker_rating_summary"."cumulative_rating" = 2)) AS "supporter_count",
            "count"(*) FILTER (WHERE ("campaign_worker_rating_summary"."cumulative_rating" = 3)) AS "neutral_count",
            "count"(*) FILTER (WHERE ("campaign_worker_rating_summary"."cumulative_rating" = 4)) AS "opposed_count",
            "count"(*) FILTER (WHERE ("campaign_worker_rating_summary"."cumulative_rating" = 5)) AS "oppositional_count",
            "count"(*) FILTER (WHERE ("campaign_worker_rating_summary"."cumulative_rating" IS NULL)) AS "unassessed_count"
           FROM "public"."campaign_worker_rating_summary"
          GROUP BY "campaign_worker_rating_summary"."campaign_id"
        ), "ambition_agg" AS (
         SELECT "ambition_progress"."campaign_id",
            "sum"("ambition_progress"."universe") AS "total_ambition_universe",
            "sum"("ambition_progress"."supportive") AS "total_supportive",
            "sum"("ambition_progress"."unassessed") AS "total_unassessed",
                CASE
                    WHEN ("sum"("ambition_progress"."universe") > (0)::numeric) THEN "round"(((100.0 * "sum"("ambition_progress"."supportive")) / "sum"("ambition_progress"."universe")), 1)
                    ELSE (0)::numeric
                END AS "overall_supportive_pct"
           FROM "public"."ambition_progress"
          GROUP BY "ambition_progress"."campaign_id"
        )
 SELECT "rc"."campaign_id",
    "rc"."eligible_count",
    "rc"."supportive_leader_count",
    "rc"."supporter_count",
    "rc"."neutral_count",
    "rc"."opposed_count",
    "rc"."oppositional_count",
    "rc"."unassessed_count",
    "aa"."total_ambition_universe",
    "aa"."total_supportive",
    "aa"."total_unassessed",
    "aa"."overall_supportive_pct"
   FROM ("rating_counts" "rc"
     LEFT JOIN "ambition_agg" "aa" USING ("campaign_id"));


ALTER VIEW "public"."v_strength_assessment_inputs" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_strength_assessment_inputs" IS 'Live pre-population data for the bargaining strength capture form. Aggregates worker rating counts from campaign_worker_rating_summary and ambition progress from ambition_progress. Security-invoker so RLS is inherited.';



CREATE TABLE IF NOT EXISTS "public"."woc_scope_units" (
    "woc_id" bigint NOT NULL,
    "ou_id" integer NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."woc_scope_units" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_woc_unit_representation" WITH ("security_invoker"='true') AS
 WITH RECURSIVE "scope" AS (
         SELECT "cw_1"."woc_id",
            "cw_1"."scope_ou_id" AS "ou_id"
           FROM "public"."campaign_wocs" "cw_1"
          WHERE ("cw_1"."scope_ou_id" IS NOT NULL)
        UNION
         SELECT "wsu"."woc_id",
            "wsu"."ou_id"
           FROM "public"."woc_scope_units" "wsu"
        UNION
         SELECT "s_1"."woc_id",
            "child"."ou_id"
           FROM ("scope" "s_1"
             JOIN "public"."campaign_organising_units" "child" ON (("child"."parent_ou_id" = "s_1"."ou_id")))
        )
 SELECT "s"."woc_id",
    "cw"."campaign_id",
    "s"."ou_id",
    "cou"."name" AS "ou_name",
    "cou"."parent_ou_id",
    (EXISTS ( SELECT 1
           FROM ("public"."woc_members" "m"
             JOIN "public"."campaign_worker_ou" "cwo" ON ((("cwo"."worker_id" = "m"."worker_id") AND ("cwo"."ou_id" = "s"."ou_id"))))
          WHERE (("m"."woc_id" = "s"."woc_id") AND ("m"."left_on" IS NULL)))) AS "represented",
    ( SELECT "count"(DISTINCT "m"."worker_id") AS "count"
           FROM ("public"."woc_members" "m"
             JOIN "public"."campaign_worker_ou" "cwo" ON ((("cwo"."worker_id" = "m"."worker_id") AND ("cwo"."ou_id" = "s"."ou_id"))))
          WHERE (("m"."woc_id" = "s"."woc_id") AND ("m"."left_on" IS NULL))) AS "member_count"
   FROM (("scope" "s"
     JOIN "public"."campaign_wocs" "cw" ON (("cw"."woc_id" = "s"."woc_id")))
     JOIN "public"."campaign_organising_units" "cou" ON (("cou"."ou_id" = "s"."ou_id")))
  WHERE (COALESCE("cou"."is_group_container", false) = false);


ALTER VIEW "public"."v_woc_unit_representation" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_worker_escalation_tier" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "a"."campaign_id",
            "car"."worker_id",
            "a"."template_key",
            "ae"."scheduled_at",
            "car"."binary_value"
           FROM (("public"."campaign_activity_ratings" "car"
             JOIN "public"."activity_events" "ae" ON (("ae"."event_id" = "car"."event_id")))
             JOIN "public"."campaign_activities" "a" ON (("a"."activity_id" = "ae"."activity_id")))
          WHERE ((("car"."rating_phase")::"text" = 'actual'::"text") AND (("car"."binary_value")::"text" = 'true'::"text"))
        ), "tier_calc" AS (
         SELECT "base"."campaign_id",
            "base"."worker_id",
                CASE
                    WHEN ("max"(
                    CASE
                        WHEN (("base"."template_key")::"text" = 'indefinite_strike'::"text") THEN 5
                        ELSE NULL::integer
                    END) = 5) THEN 5
                    WHEN ("max"(
                    CASE
                        WHEN (("base"."template_key")::"text" = ANY ((ARRAY['stoppage_24hr'::character varying, 'stoppage_48hr'::character varying, 'stoppage_swing_meeting'::character varying])::"text"[])) THEN 4
                        ELSE NULL::integer
                    END) = 4) THEN 4
                    WHEN ("max"(
                    CASE
                        WHEN (("base"."template_key")::"text" = ANY ((ARRAY['work_ban_helideck'::character varying, 'work_ban_lifting_gear'::character varying, 'work_ban_permits'::character varying, 'work_ban'::character varying, 'overtime_ban'::character varying, 'stoppage_4hr'::character varying])::"text"[])) THEN 3
                        ELSE NULL::integer
                    END) = 3) THEN 3
                    WHEN ("max"(
                    CASE
                        WHEN (("base"."template_key")::"text" = 'pabo_voted_yes'::"text") THEN 2
                        ELSE NULL::integer
                    END) = 2) THEN 2
                    WHEN ("max"(
                    CASE
                        WHEN (("base"."template_key")::"text" = 'bargaining_pledge_signed'::"text") THEN 1
                        ELSE NULL::integer
                    END) = 1) THEN 1
                    ELSE 0
                END AS "current_tier",
            "max"("base"."scheduled_at") AS "last_action_at"
           FROM "base"
          GROUP BY "base"."campaign_id", "base"."worker_id"
        ), "last_action" AS (
         SELECT DISTINCT ON ("base"."campaign_id", "base"."worker_id") "base"."campaign_id",
            "base"."worker_id",
            "base"."template_key" AS "last_action_type"
           FROM "base"
          ORDER BY "base"."campaign_id", "base"."worker_id", "base"."scheduled_at" DESC NULLS LAST
        )
 SELECT "tc"."campaign_id",
    "tc"."worker_id",
    "tc"."current_tier",
    "tc"."last_action_at",
    "la"."last_action_type",
        CASE
            WHEN ("tc"."current_tier" >= 4) THEN 'escalate_to_24hr_or_above'::"text"
            WHEN ("tc"."current_tier" = 3) THEN 'ask_for_stoppage_swing'::"text"
            WHEN ("tc"."current_tier" = 2) THEN 'ask_for_work_ban'::"text"
            WHEN ("tc"."current_tier" = 1) THEN 'ask_for_pabo_pledge'::"text"
            ELSE 'initial_ask'::"text"
        END AS "next_recommended_ask"
   FROM ("tier_calc" "tc"
     LEFT JOIN "last_action" "la" ON ((("la"."campaign_id" = "tc"."campaign_id") AND ("la"."worker_id" = "tc"."worker_id"))));


ALTER VIEW "public"."v_worker_escalation_tier" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_worker_escalation_tier" IS 'Per-(campaign, worker) escalation tier (0–5) based on highest actual industrial action participation. 0=no data, 1=pledge, 2=PABO voted yes, 3=work ban / 4hr, 4=24–48hr / swing, 5=indefinite strike. next_recommended_ask gives the next escalation step to ask for.';



CREATE TABLE IF NOT EXISTS "public"."worker_activity_log" (
    "activity_id" bigint NOT NULL,
    "connection_id" bigint NOT NULL,
    "activity_type" "text" NOT NULL,
    "activity_date" timestamp with time zone DEFAULT "now"() NOT NULL,
    "description" "text",
    "outcome" "text",
    "event_id" integer,
    "duration_minutes" integer,
    "contact_method" "text",
    "volunteer_role" "text",
    "volunteer_hours" numeric(5,2),
    "rating" integer,
    "feedback" "text",
    "logged_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "metadata" "jsonb",
    "action_id" integer,
    CONSTRAINT "worker_activity_log_activity_type_check" CHECK (("activity_type" = ANY (ARRAY['contact'::"text", 'meeting'::"text", 'event_attendance'::"text", 'volunteer'::"text", 'donation'::"text", 'survey_response'::"text", 'details_updated'::"text", 'campaign_removal'::"text", 'other'::"text"]))),
    CONSTRAINT "worker_activity_log_contact_method_check" CHECK (("contact_method" = ANY (ARRAY['email'::"text", 'phone'::"text", 'sms'::"text", 'in_person'::"text", 'mail'::"text", 'other'::"text"]))),
    CONSTRAINT "worker_activity_log_rating_check" CHECK ((("rating" >= 1) AND ("rating" <= 5)))
);


ALTER TABLE "public"."worker_activity_log" OWNER TO "postgres";


COMMENT ON COLUMN "public"."worker_activity_log"."metadata" IS 'Arbitrary JSON payload — e.g. field-level diff for details_updated, reason_code for campaign_removal, action_id for phone-call attribution.';



COMMENT ON COLUMN "public"."worker_activity_log"."action_id" IS 'Optional link to the phone_call_actions session this activity occurred during.';



CREATE TABLE IF NOT EXISTS "public"."worker_campaign_connections" (
    "connection_id" bigint NOT NULL,
    "worker_id" integer NOT NULL,
    "campaign_id" integer NOT NULL,
    "connection_status" "text" DEFAULT 'potential'::"text" NOT NULL,
    "is_service_employer" boolean DEFAULT false,
    "job_title" "text",
    "first_contacted_at" timestamp with time zone,
    "last_contacted_at" timestamp with time zone,
    "contact_count" integer DEFAULT 0,
    "last_activity_at" timestamp with time zone,
    "preferred_contact_method" "text",
    "preferred_contact_time" "text",
    "joined_at" timestamp with time zone,
    "membership_number" "text",
    "activities_attended_count" integer DEFAULT 0,
    "last_activity_attended_at" timestamp with time zone,
    "volunteer_hours" numeric(5,2) DEFAULT 0,
    "support_level" "text",
    "willingness_to_volunteer" "text",
    "willingness_to_recruit" "text",
    "recruitment_potential" "text",
    "estimated_network_size" integer DEFAULT 0,
    "notes" "text",
    "risk_flags" "text"[] DEFAULT '{}'::"text"[],
    "tags" "text"[] DEFAULT '{}'::"text"[],
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "worker_campaign_connections_connection_status_check" CHECK (("connection_status" = ANY (ARRAY['potential'::"text", 'contacted'::"text", 'engaged'::"text", 'member'::"text", 'inactive'::"text", 'lost'::"text"]))),
    CONSTRAINT "worker_campaign_connections_preferred_contact_method_check" CHECK (("preferred_contact_method" = ANY (ARRAY['email'::"text", 'phone'::"text", 'sms'::"text", 'in_person'::"text", 'none'::"text"]))),
    CONSTRAINT "worker_campaign_connections_recruitment_potential_check" CHECK (("recruitment_potential" = ANY (ARRAY['high'::"text", 'medium'::"text", 'low'::"text", 'none'::"text"]))),
    CONSTRAINT "worker_campaign_connections_support_level_check" CHECK (("support_level" = ANY (ARRAY['strong_supporter'::"text", 'supporter'::"text", 'neutral'::"text", 'unsupportive'::"text", 'hostile'::"text"]))),
    CONSTRAINT "worker_campaign_connections_willingness_to_recruit_check" CHECK (("willingness_to_recruit" = ANY (ARRAY['very_willing'::"text", 'willing'::"text", 'maybe'::"text", 'unlikely'::"text", 'no'::"text"]))),
    CONSTRAINT "worker_campaign_connections_willingness_to_volunteer_check" CHECK (("willingness_to_volunteer" = ANY (ARRAY['very_willing'::"text", 'willing'::"text", 'maybe'::"text", 'unlikely'::"text", 'no'::"text"])))
);


ALTER TABLE "public"."worker_campaign_connections" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_call_action_report" AS
 SELECT "cl"."campaign_id",
    "cl"."list_id",
    "cl"."name" AS "list_name",
    "cl"."section_plan_id",
    COALESCE("ca"."script_id", "cl"."script_id") AS "script_id",
    "cs"."title" AS "script_title",
    "ca"."attempt_id",
    "ca"."started_at",
    "ca"."dial_disposition",
    "ca"."call_disposition",
    "ca"."outcome_classification",
    "ca"."cta_response",
    "ca"."support_level_assessed",
    "cli"."worker_id",
    "w"."first_name",
    "w"."last_name",
        CASE
            WHEN (("umt"."type_name")::"text" = 'member_pending'::"text") THEN 'member_pending'::"text"
            WHEN (("umt"."type_name")::"text" = ANY ((ARRAY['financial_member'::character varying, 'non_oa_member'::character varying])::"text"[])) THEN 'member'::"text"
            WHEN (("umt"."type_name")::"text" = 'resigned_member'::"text") THEN 'lapsed'::"text"
            ELSE 'non_member'::"text"
        END AS "membership_status",
    "w"."worksite_id",
    "ws"."worksite_name",
    "cwou"."ou_id" AS "campaign_unit_id",
    "cou"."name" AS "campaign_unit_name",
    ( SELECT "count"(*) AS "count"
           FROM "public"."call_attempt_objections" "o"
          WHERE ("o"."attempt_id" = "ca"."attempt_id")) AS "objection_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."call_issue_observations" "i"
          WHERE ("i"."attempt_id" = "ca"."attempt_id")) AS "issue_count",
    (("ca"."call_disposition")::"text" = ANY ((ARRAY['removed_from_campaign'::character varying, 'no_longer_in_universe'::character varying])::"text"[])) AS "removed_from_campaign",
    ( SELECT ("count"(*) > 0)
           FROM "public"."worker_activity_log" "wal"
          WHERE (("wal"."connection_id" IN ( SELECT "wcc"."connection_id"
                   FROM "public"."worker_campaign_connections" "wcc"
                  WHERE (("wcc"."worker_id" = "cli"."worker_id") AND ("wcc"."campaign_id" = "cl"."campaign_id")))) AND ("wal"."activity_type" = 'details_updated'::"text") AND ("wal"."activity_date" >= "ca"."started_at") AND (("ca"."ended_at" IS NULL) OR ("wal"."activity_date" <= ("ca"."ended_at" + '00:05:00'::interval))))) AS "details_updated",
    ( SELECT "jsonb_agg"("jsonb_build_object"('activity_id', "caar"."activity_id", 'rating', "caar"."rating", 'notes', "caar"."notes")) AS "jsonb_agg"
           FROM "public"."call_attempt_assessment_ratings" "caar"
          WHERE ("caar"."attempt_id" = "ca"."attempt_id")) AS "assessment_ratings"
   FROM (((((((("public"."call_lists" "cl"
     JOIN "public"."call_list_items" "cli" ON (("cli"."list_id" = "cl"."list_id")))
     LEFT JOIN "public"."call_attempts" "ca" ON (("ca"."list_item_id" = "cli"."item_id")))
     LEFT JOIN "public"."call_scripts" "cs" ON (("cs"."script_id" = COALESCE("ca"."script_id", "cl"."script_id"))))
     JOIN "public"."workers" "w" ON (("w"."worker_id" = "cli"."worker_id")))
     LEFT JOIN "public"."union_membership_types" "umt" ON (("umt"."union_membership_type_id" = "w"."union_membership_type_id")))
     LEFT JOIN "public"."worksites" "ws" ON (("ws"."worksite_id" = "w"."worksite_id")))
     LEFT JOIN "public"."campaign_organising_units" "cou" ON (("cou"."campaign_id" = "cl"."campaign_id")))
     LEFT JOIN "public"."campaign_worker_ou" "cwou" ON ((("cwou"."ou_id" = "cou"."ou_id") AND ("cwou"."worker_id" = "w"."worker_id"))));


ALTER VIEW "public"."vw_call_action_report" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_call_action_report" IS 'Flat reporting view joining call attempts with worker, membership, worksite, unit, plus removal/details_updated flags and aggregated per-call assessment ratings (one row per attempt).';



CREATE OR REPLACE VIEW "public"."vw_campaign_worker_call_status" AS
 WITH "ranked_attempts" AS (
         SELECT "cl"."campaign_id",
            "cli"."worker_id",
            "cli"."list_id",
            "cl"."name" AS "list_name",
            "ca"."attempt_id",
            "ca"."started_at",
            "ca"."dial_disposition",
            "ca"."call_disposition",
            "ca"."outcome_classification",
            "ca"."caller_user_id",
            "ca"."caller_session_label",
            "row_number"() OVER (PARTITION BY "cl"."campaign_id", "cli"."worker_id" ORDER BY "ca"."started_at" DESC NULLS LAST, "ca"."attempt_id" DESC) AS "rn"
           FROM (("public"."call_attempts" "ca"
             JOIN "public"."call_list_items" "cli" ON (("cli"."item_id" = "ca"."list_item_id")))
             JOIN "public"."call_lists" "cl" ON (("cl"."list_id" = "cli"."list_id")))
          WHERE ("cli"."worker_id" IS NOT NULL)
        )
 SELECT "campaign_id",
    "worker_id",
    "list_id",
    "list_name",
    "attempt_id" AS "last_attempt_id",
    "started_at" AS "last_attempt_at",
    "dial_disposition" AS "last_dial_disposition",
    "call_disposition" AS "last_call_disposition",
    "outcome_classification" AS "last_outcome_classification",
    "caller_user_id" AS "last_caller_user_id",
    "caller_session_label" AS "last_caller_session_label"
   FROM "ranked_attempts"
  WHERE ("rn" = 1);


ALTER VIEW "public"."vw_campaign_worker_call_status" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_campaign_worker_list_activity" AS
 SELECT 'email'::"text" AS "channel",
    "el"."campaign_id",
    "eli"."worker_id",
    "el"."list_id",
    "el"."name" AS "list_name",
    "el"."status" AS "list_status",
    "eli"."status" AS "item_status",
    "eli"."created_at" AS "added_at"
   FROM ("public"."email_list_items" "eli"
     JOIN "public"."email_lists" "el" ON (("el"."list_id" = "eli"."list_id")))
  WHERE ("eli"."worker_id" IS NOT NULL)
UNION ALL
 SELECT 'phone'::"text" AS "channel",
    "cl"."campaign_id",
    "cli"."worker_id",
    "cl"."list_id",
    "cl"."name" AS "list_name",
    "cl"."status" AS "list_status",
    "cli"."status" AS "item_status",
    "cli"."created_at" AS "added_at"
   FROM ("public"."call_list_items" "cli"
     JOIN "public"."call_lists" "cl" ON (("cl"."list_id" = "cli"."list_id")))
  WHERE ("cli"."worker_id" IS NOT NULL)
UNION ALL
 SELECT 'task'::"text" AS "channel",
    "tl"."campaign_id",
    "tli"."worker_id",
    "tl"."task_list_id" AS "list_id",
    "tl"."title" AS "list_name",
    "tl"."status" AS "list_status",
    NULL::"text" AS "item_status",
    "tli"."created_at" AS "added_at"
   FROM ("public"."campaign_task_list_items" "tli"
     JOIN "public"."campaign_task_lists" "tl" ON (("tl"."task_list_id" = "tli"."task_list_id")))
  WHERE ("tli"."worker_id" IS NOT NULL)
UNION ALL
 SELECT 'sms'::"text" AS "channel",
    "sl"."campaign_id",
    "sli"."worker_id",
    "sl"."list_id",
    "sl"."name" AS "list_name",
    "sl"."status" AS "list_status",
    "sli"."status" AS "item_status",
    "sli"."created_at" AS "added_at"
   FROM ("public"."sms_list_items" "sli"
     JOIN "public"."sms_lists" "sl" ON (("sl"."list_id" = "sli"."list_id")))
  WHERE ("sli"."worker_id" IS NOT NULL);


ALTER VIEW "public"."vw_campaign_worker_list_activity" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_email_campaign_summary" AS
 SELECT "el"."campaign_id",
    "el"."list_id",
    "el"."name" AS "list_name",
    "el"."status" AS "list_status",
    "el"."draft_id",
    "el"."wrapper_id",
    "el"."timezone",
    "el"."blackout_override",
    "el"."scheduled_for",
    "el"."total_items",
    "el"."sent_items",
    "el"."delivered_items",
    "el"."failed_items",
    "el"."created_at",
    "count"("eli"."item_id") AS "item_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'pending'::"text")) AS "pending_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'queued'::"text")) AS "queued_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'sending'::"text")) AS "sending_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'sent'::"text")) AS "sent_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'delivered'::"text")) AS "delivered_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'failed'::"text")) AS "failed_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'skipped'::"text")) AS "skipped_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'bounced'::"text")) AS "bounced_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'unsubscribed'::"text")) AS "unsubscribed_count",
    "count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'opted_out'::"text")) AS "opted_out_count",
        CASE
            WHEN ("count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = ANY ((ARRAY['sent'::character varying, 'delivered'::character varying, 'failed'::character varying, 'bounced'::character varying])::"text"[]))) > 0) THEN "round"(((100.0 * ("count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = 'delivered'::"text")))::numeric) / ("count"("eli"."item_id") FILTER (WHERE (("eli"."status")::"text" = ANY ((ARRAY['sent'::character varying, 'delivered'::character varying, 'failed'::character varying, 'bounced'::character varying])::"text"[]))))::numeric), 1)
            ELSE (0)::numeric
        END AS "delivery_rate_pct"
   FROM ("public"."email_lists" "el"
     LEFT JOIN "public"."email_list_items" "eli" ON (("eli"."list_id" = "el"."list_id")))
  GROUP BY "el"."campaign_id", "el"."list_id", "el"."name", "el"."status", "el"."draft_id", "el"."wrapper_id", "el"."timezone", "el"."blackout_override", "el"."scheduled_for", "el"."total_items", "el"."sent_items", "el"."delivered_items", "el"."failed_items", "el"."created_at";


ALTER VIEW "public"."vw_email_campaign_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_sms_assessment_report" AS
 SELECT "a"."campaign_id",
    "r"."source",
    ("count"(*))::integer AS "ratings_count",
    ("count"(DISTINCT "r"."worker_id"))::integer AS "workers_count",
    ("count"(*) FILTER (WHERE ("r"."rating" IS NOT NULL)))::integer AS "scale_count",
    ("count"(*) FILTER (WHERE ("r"."binary_value" IS NOT NULL)))::integer AS "binary_count",
    "min"("r"."rated_at") AS "first_rated_at",
    "max"("r"."rated_at") AS "last_rated_at"
   FROM ("public"."campaign_activity_ratings" "r"
     JOIN "public"."campaign_activities" "a" ON (("a"."activity_id" = "r"."activity_id")))
  WHERE (("r"."source")::"text" = ANY ((ARRAY['sms'::character varying, 'sms_chat'::character varying, 'sms_survey'::character varying, 'sms_inbound'::character varying])::"text"[]))
  GROUP BY "a"."campaign_id", "r"."source";


ALTER VIEW "public"."vw_sms_assessment_report" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_sms_assessment_report" IS 'SMS-sourced assessments per (campaign, source) under the Phase 12 taxonomy: sms_chat (staff capture in the inbox/chat), sms_survey (survey answer mapping), sms_inbound (keyword-mapped reply). Legacy ''sms'' is included so pre-split rows stay visible.';



CREATE OR REPLACE VIEW "public"."vw_sms_ballot_tally" AS
 SELECT "s"."survey_id",
    "q"."question_id",
    "q"."sort_order",
    "q"."qtype",
    "a"."parsed_value",
    ("count"(*))::integer AS "vote_count"
   FROM ((("public"."sms_surveys" "s"
     JOIN "public"."sms_survey_questions" "q" ON (("q"."survey_id" = "s"."survey_id")))
     JOIN "public"."sms_survey_sessions" "ss" ON ((("ss"."survey_id" = "s"."survey_id") AND (("ss"."state")::"text" = 'completed'::"text"))))
     JOIN "public"."sms_survey_answers" "a" ON ((("a"."session_id" = "ss"."session_id") AND ("a"."question_id" = "q"."question_id") AND ("a"."parsed_value" IS NOT NULL))))
  WHERE ((("s"."purpose")::"text" = 'indicative_ballot'::"text") AND (("q"."qtype")::"text" <> 'open_text'::"text"))
  GROUP BY "s"."survey_id", "q"."question_id", "q"."sort_order", "q"."qtype", "a"."parsed_value";


ALTER VIEW "public"."vw_sms_ballot_tally" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_sms_ballot_tally" IS 'Aggregate ballot tally: vote counts per (question, parsed_value) over COMPLETED sessions only. No worker ids — the reporting surface for results_restricted ballots.';



CREATE OR REPLACE VIEW "public"."vw_sms_campaign_rollup" AS
 WITH "blast" AS (
         SELECT "sl"."campaign_id",
            ("count"(DISTINCT "sl"."list_id"))::integer AS "blast_count",
            ("count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = ANY ((ARRAY['sent'::character varying, 'delivered'::character varying, 'failed'::character varying])::"text"[]))))::integer AS "sends_count",
            ("count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'delivered'::"text")))::integer AS "delivered_count",
            ("count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'failed'::"text")))::integer AS "failed_count",
            ("count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = ANY ((ARRAY['opted_out'::character varying, 'blocked'::character varying])::"text"[]))))::integer AS "blast_opt_out_count"
           FROM ("public"."sms_lists" "sl"
             LEFT JOIN "public"."sms_list_items" "sli" ON (("sli"."list_id" = "sl"."list_id")))
          GROUP BY "sl"."campaign_id"
        ), "convo" AS (
         SELECT "c_1"."campaign_id",
            ("count"(DISTINCT "c_1"."conversation_id"))::integer AS "conversation_count",
            ("count"(DISTINCT "c_1"."conversation_id") FILTER (WHERE (("c_1"."state")::"text" = ANY ((ARRAY['needs_response'::character varying, 'convo'::character varying])::"text"[]))))::integer AS "active_conversation_count",
            ("count"(DISTINCT "c_1"."conversation_id") FILTER (WHERE ("c_1"."last_inbound_at" IS NOT NULL)))::integer AS "conversations_with_reply",
            ("count"("m"."message_id") FILTER (WHERE (("m"."direction")::"text" = 'inbound'::"text")))::integer AS "inbound_reply_count"
           FROM ("public"."sms_conversations" "c_1"
             LEFT JOIN "public"."sms_messages" "m" ON (("m"."conversation_id" = "c_1"."conversation_id")))
          WHERE ("c_1"."campaign_id" IS NOT NULL)
          GROUP BY "c_1"."campaign_id"
        ), "survey" AS (
         SELECT "s"."campaign_id",
            ("count"(DISTINCT "s"."survey_id"))::integer AS "survey_count",
            ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'completed'::"text")))::integer AS "surveys_completed_count",
            ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'opted_out'::"text")))::integer AS "survey_opt_out_count"
           FROM ("public"."sms_surveys" "s"
             LEFT JOIN "public"."sms_survey_sessions" "ss" ON (("ss"."survey_id" = "s"."survey_id")))
          GROUP BY "s"."campaign_id"
        )
 SELECT "c"."campaign_id",
    COALESCE("b"."blast_count", 0) AS "blast_count",
    COALESCE("b"."sends_count", 0) AS "sends_count",
    COALESCE("b"."delivered_count", 0) AS "delivered_count",
    COALESCE("b"."failed_count", 0) AS "failed_count",
        CASE
            WHEN (COALESCE("b"."sends_count", 0) > 0) THEN "round"(((100.0 * ("b"."delivered_count")::numeric) / ("b"."sends_count")::numeric), 1)
            ELSE (0)::numeric
        END AS "delivery_rate_pct",
    COALESCE("cv"."conversation_count", 0) AS "conversation_count",
    COALESCE("cv"."active_conversation_count", 0) AS "active_conversation_count",
    COALESCE("cv"."inbound_reply_count", 0) AS "inbound_reply_count",
    COALESCE("cv"."conversations_with_reply", 0) AS "conversations_with_reply",
        CASE
            WHEN (COALESCE("b"."delivered_count", 0) > 0) THEN "round"(((100.0 * (COALESCE("cv"."conversations_with_reply", 0))::numeric) / ("b"."delivered_count")::numeric), 1)
            ELSE (0)::numeric
        END AS "reply_rate_pct",
    (COALESCE("b"."blast_opt_out_count", 0) + COALESCE("sv"."survey_opt_out_count", 0)) AS "opt_outs_count",
    COALESCE("sv"."survey_count", 0) AS "survey_count",
    COALESCE("sv"."surveys_completed_count", 0) AS "surveys_completed_count"
   FROM ((("public"."campaigns" "c"
     LEFT JOIN "blast" "b" ON (("b"."campaign_id" = "c"."campaign_id")))
     LEFT JOIN "convo" "cv" ON (("cv"."campaign_id" = "c"."campaign_id")))
     LEFT JOIN "survey" "sv" ON (("sv"."campaign_id" = "c"."campaign_id")));


ALTER VIEW "public"."vw_sms_campaign_rollup" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_sms_campaign_rollup" IS 'Campaign-level SMS totals across blasts, conversations and surveys. delivery_rate_pct and reply_rate_pct use delivered as the denominator per brief §3.1 item 11.';



CREATE OR REPLACE VIEW "public"."vw_sms_campaign_summary" AS
 SELECT "sl"."campaign_id",
    "sl"."list_id",
    "sl"."name" AS "list_name",
    "sl"."status" AS "list_status",
    "sl"."draft_id",
    "sl"."sender_number_id",
    "sl"."timezone",
    "sl"."blackout_override",
    "sl"."scheduled_for",
    "sl"."total_items",
    "sl"."sent_items",
    "sl"."delivered_items",
    "sl"."failed_items",
    "sl"."created_at",
    "count"("sli"."item_id") AS "item_count",
    "count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'pending'::"text")) AS "pending_count",
    "count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'queued'::"text")) AS "queued_count",
    "count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'sending'::"text")) AS "sending_count",
    "count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'sent'::"text")) AS "sent_count",
    "count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'delivered'::"text")) AS "delivered_count",
    "count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'failed'::"text")) AS "failed_count",
    "count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'skipped'::"text")) AS "skipped_count",
    "count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'opted_out'::"text")) AS "opted_out_count",
    "count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'blocked'::"text")) AS "blocked_count",
        CASE
            WHEN ("count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = ANY ((ARRAY['sent'::character varying, 'delivered'::character varying, 'failed'::character varying])::"text"[]))) > 0) THEN "round"(((100.0 * ("count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = 'delivered'::"text")))::numeric) / ("count"("sli"."item_id") FILTER (WHERE (("sli"."status")::"text" = ANY ((ARRAY['sent'::character varying, 'delivered'::character varying, 'failed'::character varying])::"text"[]))))::numeric), 1)
            ELSE (0)::numeric
        END AS "delivery_rate_pct",
    "sl"."mode",
    "sl"."archived_at"
   FROM ("public"."sms_lists" "sl"
     LEFT JOIN "public"."sms_list_items" "sli" ON (("sli"."list_id" = "sl"."list_id")))
  GROUP BY "sl"."campaign_id", "sl"."list_id", "sl"."name", "sl"."status", "sl"."draft_id", "sl"."sender_number_id", "sl"."timezone", "sl"."blackout_override", "sl"."scheduled_for", "sl"."total_items", "sl"."sent_items", "sl"."delivered_items", "sl"."failed_items", "sl"."created_at", "sl"."mode", "sl"."archived_at";


ALTER VIEW "public"."vw_sms_campaign_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_sms_chat_session_report" AS
 WITH "openers" AS (
         SELECT "l"."campaign_id",
            "l"."list_id",
            "l"."name",
            "l"."status",
            "l"."created_by",
            "l"."created_at",
            "i"."item_id",
            "i"."worker_id",
            "i"."conversation_id",
            "i"."sent_at",
            "c"."last_inbound_at",
            "c"."closed_at",
            ( SELECT "min"("m"."created_at") AS "min"
                   FROM "public"."sms_messages" "m"
                  WHERE (("m"."conversation_id" = "i"."conversation_id") AND (("m"."direction")::"text" = 'inbound'::"text") AND ("m"."created_at" >= "i"."sent_at"))) AS "first_reply_at"
           FROM (("public"."sms_lists" "l"
             JOIN "public"."sms_list_items" "i" ON (("i"."list_id" = "l"."list_id")))
             LEFT JOIN "public"."sms_conversations" "c" ON (("c"."conversation_id" = "i"."conversation_id")))
          WHERE ((("l"."mode")::"text" = 'p2p'::"text") AND ("i"."sent_at" IS NOT NULL))
        )
 SELECT "campaign_id",
    "list_id",
    "name",
    "status",
    "created_by",
    "created_at",
    ("count"(*))::integer AS "openers_sent",
    ("count"("first_reply_at"))::integer AS "replies_received",
    "round"(((100.0 * ("count"("first_reply_at"))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "response_rate_pct",
    ("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY ((EXTRACT(epoch FROM ("first_reply_at" - "sent_at")))::double precision)) FILTER (WHERE ("first_reply_at" IS NOT NULL)))::numeric AS "median_first_reply_seconds",
    ("count"(*) FILTER (WHERE ("last_inbound_at" IS NOT NULL)))::integer AS "conversations_responded",
    ("count"(*) FILTER (WHERE ("closed_at" IS NOT NULL)))::integer AS "conversations_closed",
    (( SELECT "count"(*) AS "count"
           FROM ("public"."campaign_activity_ratings" "r"
             JOIN "public"."campaign_activities" "a" ON (("a"."activity_id" = "r"."activity_id")))
          WHERE (("a"."campaign_id" = "o"."campaign_id") AND (("r"."source")::"text" = ANY ((ARRAY['sms_chat'::character varying, 'sms_survey'::character varying, 'sms_inbound'::character varying])::"text"[])) AND ("r"."worker_id" IN ( SELECT "o2"."worker_id"
                   FROM "openers" "o2"
                  WHERE ("o2"."list_id" = "o"."list_id"))))))::integer AS "assessments_recorded"
   FROM "openers" "o"
  GROUP BY "campaign_id", "list_id", "name", "status", "created_by", "created_at";


ALTER VIEW "public"."vw_sms_chat_session_report" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_sms_chat_session_report" IS 'Per P2P chat session (sms_lists.mode = ''p2p''): openers sent, replies received, response rate, median seconds to first reply, conversations that ever received a reply, conversations marked complete, and SMS-sourced assessments recorded against the session''s members. Group by created_by for per-organiser throughput.';



CREATE OR REPLACE VIEW "public"."vw_sms_sender_stats" AS
 WITH "ordered" AS (
         SELECT "c"."campaign_id",
            "m"."conversation_id",
            "m"."sender_user_id",
            "m"."direction",
            "m"."ai_assisted",
            "m"."created_at",
            ("ssl"."send_id" IS NOT NULL) AS "is_blast_mirror",
            "lag"("m"."direction") OVER "w" AS "prev_direction",
            "lag"("m"."created_at") OVER "w" AS "prev_created_at"
           FROM (("public"."sms_messages" "m"
             JOIN "public"."sms_conversations" "c" ON (("c"."conversation_id" = "m"."conversation_id")))
             LEFT JOIN "public"."sms_send_log" "ssl" ON (((("ssl"."provider_message_id")::"text" = ("m"."provider_message_id")::"text") AND ("m"."provider_message_id" IS NOT NULL))))
          WINDOW "w" AS (PARTITION BY "m"."conversation_id" ORDER BY "m"."created_at", "m"."message_id")
        )
 SELECT "campaign_id",
    "sender_user_id",
    ("count"(*))::integer AS "replies_sent",
    ("count"(DISTINCT "conversation_id"))::integer AS "conversations",
    ("count"(*) FILTER (WHERE "ai_assisted"))::integer AS "ai_assisted_count",
    "percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY ((EXTRACT(epoch FROM ("created_at" - "prev_created_at")))::double precision)) FILTER (WHERE (("prev_direction")::"text" = 'inbound'::"text")) AS "median_reply_latency_seconds"
   FROM "ordered"
  WHERE ((("direction")::"text" = 'outbound'::"text") AND ("sender_user_id" IS NOT NULL) AND (NOT "is_blast_mirror"))
  GROUP BY "campaign_id", "sender_user_id";


ALTER VIEW "public"."vw_sms_sender_stats" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_sms_sender_stats" IS 'Per (campaign, sender) outbound conversation stats. median_reply_latency_seconds pairs each outbound with the immediately-preceding inbound in the same thread (NULL when the sender has no such pairs).';



CREATE OR REPLACE VIEW "public"."vw_sms_survey_answer_distribution" AS
 SELECT "q"."survey_id",
    "q"."question_id",
    "q"."sort_order",
    "q"."qtype",
    "a"."parsed_value",
    ("count"(*))::integer AS "answer_count",
    ("count"(*) FILTER (WHERE (("ss"."state")::"text" = 'completed'::"text")))::integer AS "completed_answer_count"
   FROM (("public"."sms_survey_questions" "q"
     JOIN "public"."sms_survey_answers" "a" ON ((("a"."question_id" = "q"."question_id") AND ("a"."parsed_value" IS NOT NULL))))
     JOIN "public"."sms_survey_sessions" "ss" ON (("ss"."session_id" = "a"."session_id")))
  WHERE (("q"."qtype")::"text" <> 'open_text'::"text")
  GROUP BY "q"."survey_id", "q"."question_id", "q"."sort_order", "q"."qtype", "a"."parsed_value";


ALTER VIEW "public"."vw_sms_survey_answer_distribution" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_sms_survey_answer_distribution" IS 'Aggregate answer counts per (question, parsed_value) for the visual survey report. answer_count = every session that answered (survey reading); completed_answer_count = completed sessions only (ballot reading). No worker ids, no raw bodies — same privacy class as vw_sms_ballot_tally. Excludes open_text.';



CREATE OR REPLACE VIEW "public"."vw_sms_survey_funnel" AS
 SELECT "s"."survey_id",
    "s"."campaign_id",
    ("count"("ss"."session_id"))::integer AS "total_sessions",
    ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'queued'::"text")))::integer AS "queued_count",
    ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'invited'::"text")))::integer AS "invited_count",
    ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'active'::"text")))::integer AS "active_count",
    ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'completed'::"text")))::integer AS "completed_count",
    ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'expired'::"text")))::integer AS "expired_count",
    ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'opted_out'::"text")))::integer AS "opted_out_count",
    ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'handed_off'::"text")))::integer AS "handed_off_count",
    ("count"("ss"."session_id") FILTER (WHERE (("ss"."state")::"text" = 'undeliverable'::"text")))::integer AS "undeliverable_count",
    ("count"("ss"."session_id") FILTER (WHERE ("ss"."invited_at" IS NOT NULL)))::integer AS "ever_invited_count",
    ("count"("ss"."session_id") FILTER (WHERE ("ss"."first_answer_at" IS NOT NULL)))::integer AS "started_count"
   FROM ("public"."sms_surveys" "s"
     LEFT JOIN "public"."sms_survey_sessions" "ss" ON (("ss"."survey_id" = "s"."survey_id")))
  GROUP BY "s"."survey_id", "s"."campaign_id";


ALTER VIEW "public"."vw_sms_survey_funnel" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_sms_survey_question_stats" AS
 SELECT "q"."survey_id",
    "q"."question_id",
    "q"."sort_order",
    "q"."qtype",
    ("count"("a"."answer_id") FILTER (WHERE ("a"."parsed_value" IS NOT NULL)))::integer AS "answered_count",
    ("count"("a"."answer_id") FILTER (WHERE ("a"."parsed_value" IS NULL)))::integer AS "unparsed_count",
    (COALESCE("sum"("a"."invalid_attempts"), (0)::bigint))::integer AS "invalid_attempts"
   FROM ("public"."sms_survey_questions" "q"
     LEFT JOIN "public"."sms_survey_answers" "a" ON (("a"."question_id" = "q"."question_id")))
  GROUP BY "q"."survey_id", "q"."question_id", "q"."sort_order", "q"."qtype";


ALTER VIEW "public"."vw_sms_survey_question_stats" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."woc_committee_meetings" (
    "meeting_id" bigint NOT NULL,
    "woc_id" bigint NOT NULL,
    "meeting_date" "date" NOT NULL,
    "format" "text",
    "chair_worker_id" integer,
    "activity_id" integer,
    "event_id" integer,
    "whats_new" "text",
    "recognition_notes" "text",
    "new_tasks_summary" "text",
