CREATE OR REPLACE VIEW "public"."workers_view" WITH ("security_invoker"='true') AS
 SELECT "w"."worker_id",
    "w"."first_name",
    "w"."last_name",
    "w"."email",
    "w"."phone",
    "w"."address",
    "w"."suburb",
    "w"."state",
    "w"."postcode",
    "w"."date_of_birth",
    "w"."gender",
    "w"."occupation",
    "w"."classification",
    "w"."employer_id",
    "w"."worksite_id",
    "w"."member_role_type_id",
    "w"."union_id",
    "w"."member_number",
    "w"."join_date",
    "w"."resignation_date",
    "w"."action_network_id",
    "w"."notes",
    "w"."is_active",
    "w"."created_at",
    "w"."updated_at",
    "w"."project_id",
    "w"."canonical_occupation_id",
    "w"."preferred_name",
    "w"."union_membership_type_id",
    "w"."is_hsr",
    "w"."is_bargaining_rep",
    "w"."reference_id",
    "w"."rejoin_date",
    "w"."resignation_reason",
    "w"."non_oa_union_option_id",
    "e"."employer_name",
    "ws"."worksite_name",
    "ws"."is_offshore",
    "mrt"."display_name" AS "member_role_display",
    "umt"."display_name" AS "union_membership_display",
    "u"."union_code",
    "u"."union_name",
    "nauo"."badge_initials" AS "non_oa_union_badge_initials",
    "nauo"."display_name" AS "non_oa_union_display_name",
    "p"."project_name",
    "p"."work_type",
    "p"."project_status"
   FROM ((((((("public"."workers" "w"
     LEFT JOIN "public"."employers" "e" ON (("e"."employer_id" = "w"."employer_id")))
     LEFT JOIN "public"."worksites" "ws" ON (("ws"."worksite_id" = "w"."worksite_id")))
     LEFT JOIN "public"."member_role_types" "mrt" ON (("mrt"."role_type_id" = "w"."member_role_type_id")))
     LEFT JOIN "public"."union_membership_types" "umt" ON (("umt"."union_membership_type_id" = "w"."union_membership_type_id")))
     LEFT JOIN "public"."unions" "u" ON (("u"."union_id" = "w"."union_id")))
     LEFT JOIN "public"."projects" "p" ON (("p"."project_id" = "w"."project_id")))
     LEFT JOIN "public"."non_oa_union_options" "nauo" ON (("nauo"."non_oa_union_option_id" = "w"."non_oa_union_option_id")));


ALTER VIEW "public"."workers_view" OWNER TO "postgres";


