CREATE OR REPLACE VIEW "public"."workload_campaign_activities" AS
 SELECT "campaign_id",
    "name" AS "campaign_name",
    "status" AS "campaign_status",
    "campaign_type",
    ( SELECT "count"(*) AS "count"
           FROM "public"."campaign_actions" "ca"
          WHERE (("ca"."campaign_id" = "c"."campaign_id") AND (("ca"."status")::"text" = 'in_progress'::"text"))) AS "in_progress_actions",
    ( SELECT "count"(*) AS "count"
           FROM ("public"."gate_assessments" "ga"
             JOIN "public"."gate_definitions" "gd" ON (("ga"."gate_id" = "gd"."gate_id")))
          WHERE (("gd"."campaign_id" = "c"."campaign_id") AND (("ga"."outcome")::"text" = 'pending'::"text"))) AS "pending_gate_assessments",
    ( SELECT "count"(*) AS "count"
           FROM "public"."campaign_stage_plans" "csp"
          WHERE (("csp"."campaign_id" = "c"."campaign_id") AND (("csp"."status")::"text" = 'active'::"text"))) AS "active_stage_plans",
    ((( SELECT "count"(*) AS "count"
           FROM "public"."campaign_actions" "ca"
          WHERE (("ca"."campaign_id" = "c"."campaign_id") AND (("ca"."status")::"text" = 'in_progress'::"text"))) + ( SELECT "count"(*) AS "count"
           FROM ("public"."gate_assessments" "ga"
             JOIN "public"."gate_definitions" "gd" ON (("ga"."gate_id" = "gd"."gate_id")))
          WHERE (("gd"."campaign_id" = "c"."campaign_id") AND (("ga"."outcome")::"text" = 'pending'::"text")))) + ( SELECT "count"(*) AS "count"
           FROM "public"."campaign_stage_plans" "csp"
          WHERE (("csp"."campaign_id" = "c"."campaign_id") AND (("csp"."status")::"text" = 'active'::"text")))) AS "total_activities_underway",
    ( SELECT "json_agg"("json_build_object"('action_id', "ca"."action_id", 'action_name', COALESCE("ca"."title", "ca"."action_type"), 'status', "ca"."status", 'due_date', "ca"."due_date", 'assigned_to', "ca"."assigned_organiser_id") ORDER BY "ca"."due_date") AS "json_agg"
           FROM ( SELECT "ca_1"."action_id",
                    "ca_1"."title",
                    "ca_1"."action_type",
                    "ca_1"."status",
                    "ca_1"."due_date",
                    "ca_1"."assigned_organiser_id"
                   FROM "public"."campaign_actions" "ca_1"
                  WHERE (("ca_1"."campaign_id" = "c"."campaign_id") AND (("ca_1"."status")::"text" = 'in_progress'::"text"))
                 LIMIT 5) "ca") AS "recent_actions"
   FROM "public"."campaigns" "c"
  WHERE (("status")::"text" = ANY ((ARRAY['active'::character varying, 'planning'::character varying])::"text"[]));


ALTER VIEW "public"."workload_campaign_activities" OWNER TO "postgres";


COMMENT ON VIEW "public"."workload_campaign_activities" IS 'Shows all activities underway for campaigns (actions, gate assessments, stage plans)';



CREATE OR REPLACE VIEW "public"."workload_campaign_entities" AS
 SELECT "campaign_id",
    "name" AS "campaign_name",
    "status" AS "campaign_status",
    "campaign_type",
    ( SELECT "count"(DISTINCT "cw"."worksite_id") AS "count"
           FROM "public"."campaign_worksites" "cw"
          WHERE ("cw"."campaign_id" = "c"."campaign_id")) AS "worksite_count",
    ( SELECT "count"(DISTINCT "a"."employer_id") AS "count"
           FROM ("public"."agreements" "a"
             JOIN "public"."campaign_timelines" "ct" ON (("ct"."agreement_id" = "a"."agreement_id")))
          WHERE ("ct"."campaign_id" = "c"."campaign_id")) AS "employer_count",
    ( SELECT "count"(DISTINCT "w"."worker_id") AS "count"
           FROM ((("public"."workers" "w"
             JOIN "public"."worker_agreements" "wa" ON (("w"."worker_id" = "wa"."worker_id")))
             JOIN "public"."agreements" "a" ON (("wa"."agreement_id" = "a"."agreement_id")))
             JOIN "public"."campaign_timelines" "ct" ON (("ct"."agreement_id" = "a"."agreement_id")))
          WHERE (("ct"."campaign_id" = "c"."campaign_id") AND ("w"."is_active" = true))) AS "worker_count",
    ( SELECT "count"(DISTINCT "leader_ids"."lid") AS "count"
           FROM ( SELECT ('w:'::"text" || ("ctl"."leader_worker_id")::"text") AS "lid"
                   FROM "public"."campaign_task_lists" "ctl"
                  WHERE (("ctl"."campaign_id" = "c"."campaign_id") AND ("ctl"."leader_worker_id" IS NOT NULL))
                UNION
                 SELECT ('o:'::"text" || ("ctl"."leader_organiser_id")::"text")
                   FROM "public"."campaign_task_lists" "ctl"
                  WHERE (("ctl"."campaign_id" = "c"."campaign_id") AND ("ctl"."leader_organiser_id" IS NOT NULL))) "leader_ids") AS "leader_count"
   FROM "public"."campaigns" "c"
  WHERE (("status")::"text" = ANY ((ARRAY['active'::character varying, 'planning'::character varying])::"text"[]));


ALTER VIEW "public"."workload_campaign_entities" OWNER TO "postgres";


COMMENT ON VIEW "public"."workload_campaign_entities" IS 'Shows counts of worksites, employers, workers, and leaders per campaign';



CREATE OR REPLACE VIEW "public"."workload_campaign_progress" AS
 WITH "campaign_criteria" AS (
         SELECT "gd"."campaign_id",
            "gd"."gate_id",
            "gd"."gate_number",
            "gd"."gate_name",
            "count"(*) AS "total_criteria",
            "sum"(
                CASE
                    WHEN "gc"."is_met" THEN 1
                    ELSE 0
                END) AS "met_criteria",
            "round"(((("sum"(
                CASE
                    WHEN "gc"."is_met" THEN 1
                    ELSE 0
                END))::numeric / ("count"(*))::numeric) * (100)::numeric), 2) AS "progress_percentage",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."gate_assessments" "ga"
                  WHERE (("ga"."gate_id" = "gd"."gate_id") AND (("ga"."outcome")::"text" = 'pending'::"text"))) AS "pending_assessments",
            "max"(
                CASE
                    WHEN (("gc"."last_calculated_at" IS NOT NULL) AND ("gc"."last_calculated_at" < ("now"() - '01:00:00'::interval))) THEN 1
                    ELSE 0
                END) AS "has_stale_criteria"
           FROM ("public"."gate_definitions" "gd"
             LEFT JOIN "public"."gate_criteria" "gc" ON (("gd"."gate_id" = "gc"."gate_id")))
          WHERE ("gd"."is_active" = true)
          GROUP BY "gd"."gate_id", "gd"."campaign_id", "gd"."gate_number", "gd"."gate_name"
        )
 SELECT "c"."campaign_id",
    "c"."name" AS "campaign_name",
    "c"."status" AS "campaign_status",
    "c"."campaign_type",
    COALESCE("sum"("cc"."total_criteria"), (0)::numeric) AS "total_criteria",
    COALESCE("sum"("cc"."met_criteria"), (0)::numeric) AS "met_criteria",
        CASE
            WHEN ("sum"("cc"."total_criteria") > (0)::numeric) THEN "round"((("sum"("cc"."met_criteria") / "sum"("cc"."total_criteria")) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "overall_progress_percentage",
    COALESCE("sum"("cc"."pending_assessments"), (0)::numeric) AS "pending_assessments",
    ( SELECT "json_agg"("json_build_object"('gate_number', "cc2"."gate_number", 'gate_name', "cc2"."gate_name", 'progress_percentage', "cc2"."progress_percentage", 'total_criteria', "cc2"."total_criteria", 'met_criteria', "cc2"."met_criteria", 'pending_assessments', "cc2"."pending_assessments") ORDER BY "cc2"."gate_number") AS "json_agg"
           FROM "campaign_criteria" "cc2"
          WHERE ("cc2"."campaign_id" = "c"."campaign_id")) AS "gate_progress_details"
   FROM ("public"."campaigns" "c"
     LEFT JOIN "campaign_criteria" "cc" ON (("c"."campaign_id" = "cc"."campaign_id")))
  WHERE (("c"."status")::"text" = ANY ((ARRAY['active'::character varying, 'planning'::character varying])::"text"[]))
  GROUP BY "c"."campaign_id", "c"."name", "c"."status", "c"."campaign_type";


ALTER VIEW "public"."workload_campaign_progress" OWNER TO "postgres";


COMMENT ON VIEW "public"."workload_campaign_progress" IS 'Shows progress towards gate criteria for each campaign';



CREATE OR REPLACE VIEW "public"."workload_campaigns_by_stage" AS
 SELECT "c"."campaign_id",
    "c"."name" AS "campaign_name",
    "c"."status" AS "campaign_status",
    "c"."campaign_type",
    "c"."created_by",
    COALESCE("csp"."stage_number", 0) AS "current_stage_number",
    COALESCE("csp"."stage_name", 'Not Started'::character varying) AS "current_stage_name",
    COALESCE("csp"."status", 'none'::character varying) AS "stage_status",
    "csp"."planned_start_date",
    "csp"."planned_end_date",
        CASE
            WHEN (("csp"."status")::"text" = 'active'::"text") THEN 'Active'::"text"
            WHEN (("csp"."status")::"text" = 'completed'::"text") THEN 'Completed'::"text"
            WHEN (("csp"."status")::"text" = 'draft'::"text") THEN 'Planning'::"text"
            WHEN (("csp"."status")::"text" = 'blocked'::"text") THEN 'Blocked'::"text"
            ELSE 'Not Started'::"text"
        END AS "stage_display_status",
        CASE
            WHEN (("csp"."planned_end_date" IS NOT NULL) AND ("csp"."planned_end_date" < CURRENT_DATE) AND (("csp"."status")::"text" <> ALL ((ARRAY['completed'::character varying, 'blocked'::character varying])::"text"[]))) THEN true
            ELSE false
        END AS "is_overdue",
        CASE
            WHEN (("csp"."planned_end_date" IS NOT NULL) AND (("csp"."planned_end_date" >= CURRENT_DATE) AND ("csp"."planned_end_date" <= (CURRENT_DATE + '7 days'::interval))) AND (("csp"."status")::"text" <> ALL ((ARRAY['completed'::character varying, 'blocked'::character varying])::"text"[]))) THEN true
            ELSE false
        END AS "is_due_soon"
   FROM ("public"."campaigns" "c"
     LEFT JOIN "public"."campaign_stage_plans" "csp" ON ((("c"."campaign_id" = "csp"."campaign_id") AND ("csp"."stage_number" = ( SELECT COALESCE("max"("campaign_stage_plans"."stage_number"), 0) AS "coalesce"
           FROM "public"."campaign_stage_plans"
          WHERE (("campaign_stage_plans"."campaign_id" = "c"."campaign_id") AND (("campaign_stage_plans"."status")::"text" = ANY ((ARRAY['active'::character varying, 'completed'::character varying])::"text"[]))))))))
  WHERE (("c"."status")::"text" = ANY ((ARRAY['active'::character varying, 'planning'::character varying])::"text"[]));


ALTER VIEW "public"."workload_campaigns_by_stage" OWNER TO "postgres";


COMMENT ON VIEW "public"."workload_campaigns_by_stage" IS 'Shows campaigns grouped by their current stage with overdue/due soon indicators';



CREATE OR REPLACE VIEW "public"."workload_dashboard_summary" AS
 SELECT "c"."campaign_id",
    "c"."name" AS "campaign_name",
    "c"."status" AS "campaign_status",
    "c"."campaign_type",
    "c"."created_by",
    "c"."created_at",
    COALESCE("cbs"."current_stage_number", 0) AS "current_stage_number",
    COALESCE("cbs"."current_stage_name", 'Not Started'::character varying) AS "current_stage_name",
    COALESCE("cbs"."stage_display_status", 'Not Started'::"text") AS "stage_display_status",
    "cbs"."is_overdue",
    "cbs"."is_due_soon",
    COALESCE("cp"."overall_progress_percentage", (0)::numeric) AS "overall_progress_percentage",
    COALESCE("cp"."total_criteria", (0)::numeric) AS "total_criteria",
    COALESCE("cp"."met_criteria", (0)::numeric) AS "met_criteria",
    COALESCE("cp"."pending_assessments", (0)::numeric) AS "pending_assessments",
    COALESCE("ce"."worksite_count", (0)::bigint) AS "worksite_count",
    COALESCE("ce"."employer_count", (0)::bigint) AS "employer_count",
    COALESCE("ce"."worker_count", (0)::bigint) AS "worker_count",
    COALESCE("ce"."leader_count", (0)::bigint) AS "leader_count",
    COALESCE("ca"."total_activities_underway", (0)::bigint) AS "total_activities_underway",
    COALESCE("ca"."in_progress_actions", (0)::bigint) AS "in_progress_actions",
    COALESCE("ca"."pending_gate_assessments", (0)::bigint) AS "pending_gate_assessments",
    COALESCE("ca"."active_stage_plans", (0)::bigint) AS "active_stage_plans"
   FROM (((("public"."campaigns" "c"
     LEFT JOIN "public"."workload_campaigns_by_stage" "cbs" ON (("c"."campaign_id" = "cbs"."campaign_id")))
     LEFT JOIN "public"."workload_campaign_progress" "cp" ON (("c"."campaign_id" = "cp"."campaign_id")))
     LEFT JOIN "public"."workload_campaign_entities" "ce" ON (("c"."campaign_id" = "ce"."campaign_id")))
     LEFT JOIN "public"."workload_campaign_activities" "ca" ON (("c"."campaign_id" = "ca"."campaign_id")))
  WHERE (("c"."status")::"text" = ANY ((ARRAY['active'::character varying, 'planning'::character varying])::"text"[]));


ALTER VIEW "public"."workload_dashboard_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."workload_dashboard_summary" IS 'Summary view for Organiser Workload Dashboard combining all key metrics';



