CREATE OR REPLACE VIEW "public"."worksite_hierarchy_report_rows" AS
 WITH "role_rows" AS (
         SELECT "w"."worksite_id",
            "w"."worksite_name",
            "w"."is_offshore",
            "w"."worksite_type",
            "w"."principal_employer_id",
            "w"."operator_id",
            "ewr"."employer_id" AS "provider_employer_id",
            "ep"."employer_name" AS "provider_name",
            "string_agg"(DISTINCT "replace"(("ewr"."role_type")::"text", '_'::"text", ' '::"text"), ', '::"text" ORDER BY ("replace"(("ewr"."role_type")::"text", '_'::"text", ' '::"text"))) AS "provider_roles"
           FROM (("public"."worksites" "w"
             LEFT JOIN "public"."employer_worksite_roles" "ewr" ON ((("ewr"."worksite_id" = "w"."worksite_id") AND ("ewr"."is_current" = true))))
             LEFT JOIN "public"."employers" "ep" ON (("ep"."employer_id" = "ewr"."employer_id")))
          WHERE ("w"."is_active" = true)
          GROUP BY "w"."worksite_id", "w"."worksite_name", "w"."is_offshore", "w"."worksite_type", "w"."principal_employer_id", "w"."operator_id", "ewr"."employer_id", "ep"."employer_name"
        ), "scope_rows" AS (
         SELECT "ws"."worksite_id",
            "ws"."employer_id" AS "provider_employer_id",
            "string_agg"(DISTINCT ("s"."scope_name")::"text", ', '::"text" ORDER BY ("s"."scope_name")::"text") AS "scope_names"
           FROM ("public"."worksite_scopes" "ws"
             JOIN "public"."work_scopes" "s" ON (("s"."scope_id" = "ws"."scope_id")))
          WHERE (("ws"."is_current" = true) AND ("ws"."employer_id" IS NOT NULL))
          GROUP BY "ws"."worksite_id", "ws"."employer_id"
        )
 SELECT "rr"."worksite_id",
    "rr"."worksite_name",
        CASE
            WHEN "rr"."is_offshore" THEN 'Offshore'::"text"
            ELSE 'Onshore'::"text"
        END AS "geo",
    "replace"(("rr"."worksite_type")::"text", '_'::"text", ' '::"text") AS "service_type",
    COALESCE("pe"."employer_name", "op"."employer_name", 'Unassigned producer'::character varying) AS "producer_name",
    "rr"."provider_employer_id",
    COALESCE("rr"."provider_name", 'No mapped provider'::character varying) AS "provider_name",
    COALESCE("rr"."provider_roles", '—'::"text") AS "provider_roles",
    COALESCE("sr"."scope_names", '—'::"text") AS "scope_names",
    "concat_ws"(' > '::"text",
        CASE
            WHEN "rr"."is_offshore" THEN 'Offshore'::"text"
            ELSE 'Onshore'::"text"
        END, "replace"(("rr"."worksite_type")::"text", '_'::"text", ' '::"text"), COALESCE("pe"."employer_name", "op"."employer_name", 'Unassigned producer'::character varying), "rr"."worksite_name") AS "hierarchy_path_geo_service",
    "concat_ws"(' > '::"text", COALESCE("pe"."employer_name", "op"."employer_name", 'Unassigned producer'::character varying),
        CASE
            WHEN "rr"."is_offshore" THEN 'Offshore'::"text"
            ELSE 'Onshore'::"text"
        END, "rr"."worksite_name") AS "hierarchy_path_producer_geo"
   FROM ((("role_rows" "rr"
     LEFT JOIN "public"."employers" "pe" ON (("pe"."employer_id" = "rr"."principal_employer_id")))
     LEFT JOIN "public"."employers" "op" ON (("op"."employer_id" = "rr"."operator_id")))
     LEFT JOIN "scope_rows" "sr" ON ((("sr"."worksite_id" = "rr"."worksite_id") AND ("sr"."provider_employer_id" = "rr"."provider_employer_id"))));


ALTER VIEW "public"."worksite_hierarchy_report_rows" OWNER TO "postgres";


COMMENT ON VIEW "public"."worksite_hierarchy_report_rows" IS 'Canonical hierarchy report rows for worksite reporting paths with provider-role-scope mappings.';



CREATE MATERIALIZED VIEW "public"."worksite_hierarchy_report_rows_mv" AS
 SELECT "worksite_id",
