    "geo",
    "service_type",
    "producer_name",
    "provider_employer_id",
    "provider_name",
    "provider_roles",
    "scope_names",
    "hierarchy_path_geo_service",
    "hierarchy_path_producer_geo"
   FROM "public"."worksite_hierarchy_report_rows"
  WITH NO DATA;


