CREATE OR REPLACE VIEW "public"."worksites_view" AS
 SELECT "ws"."worksite_id",
    "ws"."worksite_name",
    "ws"."worksite_type",
    "ws"."operator_id",
    "ws"."location_description",
    "ws"."latitude",
    "ws"."longitude",
    "ws"."basin",
    "ws"."is_offshore",
    "ws"."is_active",
    "ws"."notes",
    "ws"."created_at",
    "ws"."updated_at",
    "ws"."principal_employer_id",
    "ws"."parent_worksite_id",
    "e"."employer_name" AS "operator_name",
    "pws"."worksite_name" AS "parent_worksite_name",
    "pe"."employer_name" AS "principal_employer_name",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."agreement_worksites" "aw"
          WHERE ("aw"."worksite_id" = "ws"."worksite_id")) AS "agreement_count",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."workers" "w"
          WHERE (("w"."worksite_id" = "ws"."worksite_id") AND ("w"."is_active" = true))) AS "worker_count",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."projects" "p"
          WHERE (("p"."worksite_id" = "ws"."worksite_id") AND ("p"."is_active" = true))) AS "project_count"
   FROM ((("public"."worksites" "ws"
     LEFT JOIN "public"."employers" "e" ON (("e"."employer_id" = "ws"."operator_id")))
     LEFT JOIN "public"."worksites" "pws" ON (("pws"."worksite_id" = "ws"."parent_worksite_id")))
     LEFT JOIN "public"."employers" "pe" ON (("pe"."employer_id" = "ws"."principal_employer_id")));


